window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0219", [{"word":"minimal","ipa_uk":"/ˈmɪnɪməl/","ipa_us":"/ˈmɪnɪməl/","definition_zh":"最小的；极少的；最低限度的；极简风格的","definition_en":"the smallest or least possible in amount, size or degree","core_image":"一只几乎见底的杯子，杯壁上只剩一道水痕","scene":"舞台上一张桌子、两把椅子，再无他物，灯光只照向演员。The set is minimal, with one table and two chairs on an empty stage.","sceneCN":"这里指布景精简到最低限度（第 3 个义项：去掉装饰、只留必要的样式）；句意为布景极简，空舞台上只有一桌两椅。","pos":[{"tag":"adj.","zh":"最小的；极少的；最低限度的；极简的"}],"collocations":[{"phrase":"minimal cost","zh":"最低成本"},{"phrase":"minimal impact","zh":"最小影响"},{"phrase":"minimal change","zh":"最小改动"},{"phrase":"minimal design","zh":"极简设计"},{"phrase":"minimal pair","zh":"最小对立对（语言学）"},{"phrase":"minimal requirement","zh":"最低要求"}],"forms":[{"label":"原形","form":"minimal"},{"label":"比较级","form":"more minimal"},{"label":"最高级","form":"most minimal"},{"label":"副词","form":"minimally"}],"derivatives":[{"word":"minimally","pos":"adv.","zh":"最低限度地；极简地"},{"word":"minimalism","pos":"n.","zh":"极简主义；极简风格"},{"word":"minimalist","pos":"n./adj.","zh":"极简主义者；极简的"},{"word":"minimalistic","pos":"adj.","zh":"极简风格的"}],"senses":[{"no":"01","title":"The smallest possible amount","titleCN":"可能的最小数量","definition":"the least amount or degree that is possible in a situation","definitionCN":"在某种情形下可能达到的最小数量或程度","example":"The plan was changed at minimal cost to the company.","exampleCN":"这项计划以对公司最低的成本做了改动。","why":"The Latin superlative minimus already fixes the word at the bottom of a scale, so the sense is the floor rather than merely something small.","whyCN":"拉丁语最高级 minimus 已把词固定在刻度最底端，因此这一义项指下限，而不只是尺寸小。"},{"no":"02","title":"The lowest acceptable level","titleCN":"可接受的最低限度","definition":"the lowest level that still meets a requirement","definitionCN":"仍然满足要求的最低水平","example":"The committee set minimal standards for safety.","exampleCN":"委员会为安全设定了最低标准。","why":"Once a standard exists, the word marks the line below which a thing no longer counts.","whyCN":"标准一旦存在，这个词就标出低于它便不算数的那条线。"},{"no":"03","title":"A stripped-down style","titleCN":"极简的样式","definition":"a style that removes decoration and keeps only what is necessary","definitionCN":"去掉装饰、只保留必要元素的风格","example":"The poster uses minimal type and a single image.","exampleCN":"这张海报只用极少的字体和一张图。","why":"Design borrowed the word to name the beauty of leaving things out.","whyCN":"设计借这个词来命名「删到不能再删」的美。"},{"no":"04","title":"Barely noticeable in degree","titleCN":"程度上极轻微","definition":"so slight that it is hard to notice","definitionCN":"轻微到几乎难以察觉","example":"The two versions differ by a minimal amount.","exampleCN":"两个版本之间只有极小的差别。","why":"At this end of the scale the word approaches zero without reaching it.","whyCN":"在这一端，这个词逼近零却没有到零。"},{"no":"05","title":"A smallest element in mathematics","titleCN":"数学上的极小元","definition":"an element or set than which nothing smaller satisfies the conditions","definitionCN":"在给定条件下没有更小者能满足的元或集合","example":"The proof rests on a minimal set of assumptions.","exampleCN":"这个证明依赖一组极小的假设。","why":"Logic needs a name for the floor of a chain, and the Latin superlative supplies it.","whyCN":"逻辑学需要给链的底端一个名字，拉丁语最高级正好提供。"},{"no":"06","title":"A minimal pair in linguistics","titleCN":"语言学的最小对立对","definition":"two words that differ in one sound and therefore in meaning","definitionCN":"只差一个音、因而意义不同的两个词","example":"Cat and bat form a minimal pair in English.","exampleCN":"「猫」与「球棒」的英文词只差一个音，构成一组最小对立对。","why":"The term marks the smallest sound difference that still changes meaning.","whyCN":"这个术语标出仍能改变意义的最小语音差别。"},{"no":"07","title":"The least intrusive option","titleCN":"最不打扰的选项","definition":"the choice that disturbs people or systems least","definitionCN":"对人或系统打扰最小的选择","example":"Engineers chose the minimal intervention that fixed the fault.","exampleCN":"工程师选择了能排障的最小干预。","why":"In repair and policy the word means doing as little as possible.","whyCN":"在维修与政策中，这个词表示尽量少动手。"},{"no":"08","title":"Reduced art or music","titleCN":"极简主义作品","definition":"art or music built from very few repeated elements","definitionCN":"只用很少几个反复元素构成的艺术或音乐","example":"The minimal piece holds one chord for several minutes.","exampleCN":"这首极简作品让同一个和弦持续了好几分钟。","why":"The 1960s movements took the word as a banner for reduction itself.","whyCN":"二十世纪六十年代的流派把这个词当作「减法」的旗帜。"}],"etymology":{"intro":{"en":"Minimal joins the Latin superlative minimus, meaning smallest, to the English adjective suffix -al. The direct source is clear; only the first English date is approximate.","cn":"minimal 把意为「最小」的拉丁语最高级 minimus 与英语形容词后缀 -al 结合。直接来源清楚，只有英语首见年代是约数。"},"items":[{"era":"LATIN MINIMUS","en":"Minimus is the superlative of parvus, small, and means the smallest member of a group.","cn":"Minimus 是 parvus「小的」的最高级，意为一组中最小者。"},{"era":"MEDIEVAL MINIM","en":"Medieval music named its shortest note value with the same superlative, and English kept minim for a half note.","cn":"中世纪音乐用同一个最高级命名最短的音符时值，英语保留 minim 指二分音符。"},{"era":"FRENCH MINIMAL","en":"Learned French used minimal for the least or smallest before English borrowed the adjective.","cn":"学术法语先用 minimal 表示「最小」，英语随后借入。"},{"era":"ENGLISH ADJECTIVE","en":"Minimal appears in English in the nineteenth century; the exact first date is uncertain.","cn":"minimal 在十九世纪进入英语，确切首见年代不确定。"},{"era":"BARE STYLE","en":"Twentieth-century design and art attached the word to forms stripped to essentials.","cn":"二十世纪的设计与艺术把这个词系到删到只剩必要的形式上。"},{"era":"WIDER TECHNICAL USE","en":"Mathematics, linguistics and policy all use it for the floor of a scale.","cn":"数学、语言学与政策领域都用它指一个刻度的下限。"}]},"similar":{"note":{"en":"The first group shares the Latin small-root family; the second group names ideas close to the least end of a scale.","cn":"第一组共享拉丁语「小」的词族；第二组是接近刻度最低端的近义说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"minimize","ipa":"/ˈmɪnɪmaɪz/","tag":"same root","definition":"To reduce something to the least possible amount; built on minimum rather than on minimal.","definitionCN":"把某物减到最少；由 minimum 而非 minimal 构成。"},{"word":"minimum","ipa":"/ˈmɪnɪməm/","tag":"same root","definition":"The lowest point or amount that is allowed or recorded.","definitionCN":"被允许或记录的最低点、最低量。"},{"word":"minim","ipa":"/ˈmɪnɪm/","tag":"same root","definition":"A half note in older music, named with the same Latin superlative.","definitionCN":"旧记谱法中的二分音符，用同一个拉丁最高级命名。"},{"word":"minor","ipa":"/ˈmaɪnə(r)/","tag":"related root","definition":"Smaller or less important; a Latin comparative from the same small-root family, not a form of minimal.","definitionCN":"更小的、次要的；同属「小」词族的拉丁比较级，不是 minimal 的变形。"},{"word":"minus","ipa":"/ˈmaɪnəs/","tag":"related root","definition":"Less; the sign for subtraction, from the same comparative stem.","definitionCN":"较少；减号，来自同一比较级词干。"}]},{"heading":"NEAR MEANING","entries":[{"word":"least","ipa":"/liːst/","tag":"near meaning","definition":"The smallest amount in a group or scale.","definitionCN":"一组或一个刻度中数量最小的。"},{"word":"slight","ipa":"/slaɪt/","tag":"near meaning","definition":"Small in degree and often barely worth noticing.","definitionCN":"程度小，常指几乎不值得注意。"},{"word":"negligible","ipa":"/ˈneɡlɪdʒəbl/","tag":"near meaning","definition":"So small that it can be disregarded.","definitionCN":"小到可以忽略不计。"},{"word":"scant","ipa":"/skænt/","tag":"near meaning","definition":"Barely enough, often with a hint of shortage.","definitionCN":"勉强够，常含不足之意。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real Latin superlative, the real family and real fixed phrases.","cn":"正常联想使用真实的拉丁最高级、真实同族词与真实固定搭配。"},"normal":[{"en":"Minimus is the superlative of parvus, so the word starts at the very bottom of small.","cn":"minimus 是 parvus 的最高级，因此这个词从「小」的最底端起步。"},{"en":"A minimal pair is a pair like cat and bat: one sound apart, two different words.","cn":"最小对立对如「猫」与「球棒」这两个英文词：只差一个音，就是两个词。"},{"en":"Minimalism is the art of taking things away until only the necessary remains.","cn":"极简主义就是一路拿掉，直到只剩必要之物。"},{"en":"Minimum is the allowed floor, while minimal describes what sits at that floor.","cn":"minimum 是允许的下限，minimal 则描述处于该下限的东西。"},{"en":"Fixed phrases mark the use: minimal cost, minimal impact and minimal change.","cn":"固定说法标出用法：最低成本、最小影响与最小改动。"}],"abstract":[{"en":"Minimal is a room with one chair, and the empty space is part of the design.","cn":"极简是一间只放一把椅子的屋子，空出来的地方也是设计的一部分。"},{"en":"At the bottom of a scale, nothing can be taken away without breaking the thing.","cn":"在刻度的底端，再拿走任何一点，事物就会散架。"},{"en":"A minimal answer trusts the question to carry what is left unsaid.","cn":"极简的回答相信问题本身能承担未说出的部分。"}]},"examples":[{"en":"The report was written in minimal prose, with no decorative clauses.","cn":"这份报告用极简的文笔写成，没有装饰性的从句。"},{"en":"A minimal dose was enough to keep the pain away.","cn":"最小剂量就足以止住疼痛。"},{"en":"The two designs differ in minimal ways, yet the cost gap is large.","cn":"两个设计差别极小，成本差距却很大。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「迷你猫」——小到只剩一只猫的影子：最小的、极简的","word":"minimal"},"root":"拉丁语最高级 minimus「最小的」← 原级 parvus「小的」；同族比较级 minor「更小的」与 minus「较少」并非由 minimal 派生。英语在十九世纪加上 -al 构成形容词，确切首见年代不确定；minim 另有中世纪音乐「二分音符」之义。","sensesIntro":{"en":"Eight senses all sit at the bottom of a scale: the least amount, the lowest acceptable line, a stripped style, a barely visible degree, a smallest element, a contrastive pair, the least intrusive choice, and reduced art.","cn":"八个义项都落在刻度的底端：最小数量、可接受的最低线、删繁的样式、几乎看不见的程度、极小的元素、最小对立对、最不打扰的选择，以及极简的作品。"},"semanticMap":{"core":{"en":"CORE IMAGE: a cup almost empty, one trace of water left on the wall.","cn":"核心意象：一只几乎见底的杯子，杯壁上只剩一道水痕。"},"chain":["LEAST AMOUNT","LOWEST LINE","STRIPPED FORM","FAINT DEGREE","SMALLEST UNIT","REDUCED ART"],"branches":[{"senses":"01","en":"THE LEAST: the bottom of any scale of amount.","cn":"最少：任何数量刻度的底端。"},{"senses":"02 · 07","en":"THE LINE AND THE LIGHT TOUCH: the lowest acceptable standard and the least intrusive act.","cn":"线与轻触：可接受的最低标准，以及打扰最小的动作。"},{"senses":"03 · 08","en":"THE STRIPPED FORM: design and art that remove until only the essential remains.","cn":"删繁的形式：设计与艺术一路删到只剩必要。"},{"senses":"04","en":"THE FAINT DEGREE: a difference that is barely there.","cn":"轻微的程度：几乎不存在的差别。"},{"senses":"05 · 06","en":"THE SMALLEST UNIT: the floor of a mathematical chain and the one-sound pair of linguistics.","cn":"最小单位：数学链的底端与语言学中只差一音的一对。"}]},"affixes":{"intro":{"en":"Minimal is the Latin superlative minimus plus the English suffix -al; the Latin family is clear, and no native root is involved.","cn":"minimal 是拉丁语最高级 minimus 加英语后缀 -al；拉丁词族清楚，不涉及本族语词根。"},"latinIntro":{"en":"Minimus, minor and minus belong to one small-root family, while parvus supplies the plain positive degree.","cn":"minimus、minor 与 minus 同属一个表示「小」的词族，parvus 则提供平常的原级。"},"items":[{"word":"minimus","structure":"Latin adjective, superlative of parvus","meaning":"smallest","meaningCN":"最小的","example":"The superlative fixes the floor of the scale.","exampleCN":"最高级把刻度固定在最底端。"},{"word":"parvus","structure":"Latin adjective, positive degree","meaning":"small","meaningCN":"小的","example":"Parvus supplies the plain positive that minimus replaces.","exampleCN":"原级 parvus 提供平常的「小」，由 minimus 承担最高级。"},{"word":"minor","structure":"Latin comparative adjective","meaning":"smaller; less","meaningCN":"更小的；较少的","example":"Minor is the comparative partner, not a form built from minimal.","exampleCN":"minor 是同级搭档，不是由 minimal 造出的形式。"},{"word":"minus","structure":"Latin neuter of minor","meaning":"less","meaningCN":"较少","example":"The same family gives the word behind the subtraction sign.","exampleCN":"同一词族也给出减号背后的说法。"},{"word":"minimum","structure":"Latin noun from minimus","meaning":"the least amount","meaningCN":"最小量","example":"The noun names the allowed floor and is the base of minimize.","exampleCN":"这个名词指允许的下限，也是 minimize 的基词。"},{"word":"minimal","structure":"English adjective from minimus","meaning":"least; stripped","meaningCN":"最小的；极简的","example":"English builds the adjective directly on the Latin superlative.","exampleCN":"英语直接把这个形容词建在拉丁最高级上。"},{"word":"-al","structure":"Latin adjective suffix","meaning":"relating to","meaningCN":"与…相关的","example":"The suffix turns the Latin stem into an English adjective.","exampleCN":"后缀把拉丁词干变成英语形容词。"},{"word":"minimally","structure":"English adverb","meaning":"to the least degree","meaningCN":"最低限度地","example":"The adverb marks the bottom of a scale of effort.","exampleCN":"副词标出用力程度的最低端。"},{"word":"minimalism","structure":"English noun","meaning":"art or design reduced to essentials","meaningCN":"极简主义","example":"The movement turned the adjective into a banner.","exampleCN":"该流派把这个形容词变成旗帜。"},{"word":"minimal pair","structure":"English compound term","meaning":"two words differing in one sound","meaningCN":"最小对立对","example":"Linguistics names the smallest contrastive unit a pair.","exampleCN":"语言学把最小的对立单位称为一对。"}],"latinEntries":[{"word":"minimus","structure":"minimus, minima, minimum (adj., superlative)","meaning":"smallest","meaningCN":"最小的"},{"word":"parvus","structure":"parvus, parva, parvum (adj., positive)","meaning":"small","meaningCN":"小的"},{"word":"minor","structure":"minor, minus (adj., comparative)","meaning":"smaller; less","meaningCN":"更小的；较少的"},{"word":"minus","structure":"minus (indeclinable neuter)","meaning":"less","meaningCN":"较少"}],"derivatives":[{"word":"minimally","pos":"adv.","zh":"最低限度地；极简地"},{"word":"minimalism","pos":"n.","zh":"极简主义"},{"word":"minimalist","pos":"n./adj.","zh":"极简主义者；极简的"},{"word":"minimalistic","pos":"adj.","zh":"极简风格的"}]}},{"word":"numerous","ipa_uk":"/ˈnjuːmərəs/","ipa_us":"/ˈnuːmərəs/","definition_zh":"许多的；数量众多的；为数不少的","definition_en":"existing in large numbers; many in count","core_image":"沙滩上一眼数不完的贝壳一直铺到浪线尽头","scene":"广场上一队接一队的人来登记，志愿者手里的表格翻了一页又一页。Numerous volunteers signed up before noon.","sceneCN":"这里指人数众多（第 2 个义项：人数很多的一群人）；句意为中午之前就有许多志愿者报名。","pos":[{"tag":"adj.","zh":"许多的；数量众多的"}],"collocations":[{"phrase":"numerous examples","zh":"大量例子"},{"phrase":"numerous studies","zh":"大量研究"},{"phrase":"on numerous occasions","zh":"在许多场合"},{"phrase":"numerous benefits","zh":"诸多好处"},{"phrase":"numerous times","zh":"许多次"},{"phrase":"numerous species","zh":"众多物种"}],"forms":[{"label":"原形","form":"numerous"},{"label":"比较级","form":"more numerous"},{"label":"最高级","form":"most numerous"},{"label":"副词","form":"numerously"}],"derivatives":[{"word":"numerously","pos":"adv.","zh":"众多地；大量地"},{"word":"numerousness","pos":"n.","zh":"众多；数量多"}],"senses":[{"no":"01","title":"A large number of things","titleCN":"大量的事物","definition":"a large number of separate countable things","definitionCN":"可单独计数的事物数量很大","example":"The shelf holds numerous small boxes.","exampleCN":"架子上放着许多小盒子。","why":"Latin numerus meant number and count, and the suffix -osus means full of, so numerous is literally full of number.","whyCN":"拉丁 numerus 意为数目与计数，后缀 -osus 意为充满，因此 numerous 字面就是「充满数目」。"},{"no":"02","title":"A great many people","titleCN":"众多的人","definition":"a large body of people","definitionCN":"人数很多的一群人","example":"Numerous guests arrived before the ceremony.","exampleCN":"许多客人在仪式开始前就到了。","why":"The adjective is at home with crowds because Latin numerosus described troops as well as things.","whyCN":"这个词与人群天然相合，因为拉丁 numerosus 既描述事物，也描述军队。"},{"no":"03","title":"Many separate occasions","titleCN":"许多次不同的场合","definition":"happening on many separate occasions over time","definitionCN":"在时间上分属许多不同场合","example":"She raised the point on numerous occasions.","exampleCN":"她在许多场合提出过这一点。","why":"Counting moves from objects to events, and the word follows without changing shape.","whyCN":"计数从物件转到事件，这个词的形态不变地跟了过去。"},{"no":"04","title":"Many items spread over an area","titleCN":"散布在广大区域内的许多事物","definition":"many separate items scattered across a wide area","definitionCN":"许多独立事物散布在广阔区域内","example":"The delta contains numerous islands.","exampleCN":"这片三角洲上有众多岛屿。","why":"A map shows the count as spread, and the same adjective covers that view.","whyCN":"地图把数量呈现为散落状态，同一个形容词也能覆盖这种视角。"},{"no":"05","title":"Many supporting details","titleCN":"大量支撑性细节","definition":"supplied in great quantity, as notes or examples","definitionCN":"以大量注释或例证的形式提供","example":"The paper offers numerous examples of the pattern.","exampleCN":"这篇论文为这一模式提供了大量例证。","why":"In academic prose the word counts evidence rather than objects.","whyCN":"在学术写作中，这个词数的是证据，而不是物件。"},{"no":"06","title":"Many reasons in an argument","titleCN":"论证中的许多理由","definition":"many points offered in support of a claim","definitionCN":"为支持某一主张而提出的许多论点","example":"There are numerous reasons to postpone the vote.","exampleCN":"推迟投票的理由有很多。","why":"Debate turns quantity into weight, and the adjective supplies the quantity.","whyCN":"辩论把数量变成分量，这个形容词负责提供数量。"},{"no":"07","title":"A large sample in research","titleCN":"研究中的大样本","definition":"a large count of cases in a study or survey","definitionCN":"研究或调查中大量案例的计数","example":"Numerous trials confirmed the effect.","exampleCN":"大量试验确认了这一效应。","why":"Statistics needs a plain word for a big count before any test is run.","whyCN":"统计在运行任何检验之前，需要一个表示大计数的平实词。"},{"no":"08","title":"A formal substitute for many","titleCN":"正式语体中的「许多」","definition":"used in formal writing where a bare many would sound abrupt","definitionCN":"用于正式写作，替下显得突兀的「许多」","example":"Numerous factors were considered by the board.","exampleCN":"董事会考虑了诸多因素。","why":"Register, not meaning, separates numerous from many in much modern use.","whyCN":"在现代用法中，这个词与「许多」的区别多在语体，而非意义。"}],"etymology":{"intro":{"en":"Numerous is Latin numerosus, full of number, built on numerus plus the suffix -osus. The Latin line is clear; the first English date is only approximate.","cn":"numerous 来自拉丁 numerosus「充满数目」，由 numerus 加后缀 -osus 构成。拉丁线索清楚，英语首见年代只是约数。"},"items":[{"era":"LATIN NUMERUS","en":"Numerus meant a number, a count, and also a rank or division; its deeper origin is usually traced to a root meaning to assign or allot.","cn":"numerus 指数目、计数，也指等级或队列；更深的来源通常追到一个表示「分配」的词根。"},{"era":"THE SUFFIX -OSUS","en":"The suffix -osus means full of or abounding in, so numerosus is literally full of number.","cn":"后缀 -osus 意为充满、多有，因此 numerosus 字面就是「充满数目」。"},{"era":"LATIN NUMEROSUS","en":"The adjective described things countable in great quantity, especially troops, examples and occasions.","cn":"这个形容词描述可大量计数之物，尤用于军队、例证与场合。"},{"era":"FRENCH AND ENGLISH","en":"English took the adjective in the sixteenth century; the exact first date is uncertain.","cn":"英语在十六世纪借入这个形容词，确切首见年代不确定。"},{"era":"MODERN REGISTER","en":"The word survives mainly in formal writing as a polished substitute for many.","cn":"这个词主要活在正式写作中，作为 many 的雅致替身。"},{"era":"THE FAMILY","en":"Number, numeral, enumerate and numerator all descend from numerus, while numerous is its adjective.","cn":"number、numeral、enumerate 与 numerator 都出自 numerus，numerous 则是它的形容词。"}]},"similar":{"note":{"en":"The first group descends from the Latin number word; the second group gives plainer ways of saying a large count.","cn":"第一组出自拉丁语「数目」一词；第二组是表示「大量」的更平实说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"number","ipa":"/ˈnʌmbə(r)/","tag":"same root","definition":"A count or total, reaching English through French from Latin numerus.","definitionCN":"计数或总数，经法语从拉丁 numerus 进入英语。"},{"word":"numeral","ipa":"/ˈnjuːmərəl/","tag":"same root","definition":"A sign or word for a number.","definitionCN":"表示数目的符号或词。"},{"word":"numerical","ipa":"/nuːˈmerɪkl/","tag":"same root","definition":"Expressed in or relating to numbers.","definitionCN":"用数字表示的；与数字有关的。"},{"word":"enumerate","ipa":"/ɪˈnjuːməreɪt/","tag":"same root","definition":"To list items one by one, from the same number stem.","definitionCN":"逐项列举，出自同一「数目」词干。"},{"word":"numerable","ipa":"/ˈnjuːmərəbl/","tag":"same root","definition":"Able to be counted.","definitionCN":"可以计数的。"}]},{"heading":"NEAR MEANING","entries":[{"word":"many","ipa":"/ˈmæni/","tag":"near meaning","definition":"A large but unspecified number; plainer than numerous.","definitionCN":"数量大而未指明；比 numerous 更平实。"},{"word":"countless","ipa":"/ˈkaʊntləs/","tag":"near meaning","definition":"Too many to count.","definitionCN":"多到数不清。"},{"word":"abundant","ipa":"/əˈbʌndənt/","tag":"near meaning","definition":"Present in great quantity, often of supply rather than items.","definitionCN":"大量存在，多指供给而非条目。"},{"word":"myriad","ipa":"/ˈmaɪriəd/","tag":"near meaning","definition":"A countless or extremely great number, often literary.","definitionCN":"无数或极多，常带文学色彩。"},{"word":"several","ipa":"/ˈsevrəl/","tag":"near meaning","definition":"More than two but not a large number.","definitionCN":"多于两个，但数量不算大。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real Latin number word, the real family and real collocations.","cn":"正常联想使用真实的拉丁「数目」词、真实同族词与真实搭配。"},"normal":[{"en":"Numerus is number, and -osus means full of, so numerous means full of numbers.","cn":"numerus 是数目，-osus 意为充满，所以 numerous 就是「满是数目」。"},{"en":"Number, numeral, enumerate and numerator all come from the same stem.","cn":"number、numeral、enumerate 与 numerator 都出自同一词干。"},{"en":"The fixed phrase for many occasions marks the time sense.","cn":"表示「在许多场合」的固定说法标出时间义。"},{"en":"Numerous replaces many most often in formal writing.","cn":"numerous 多在正式写作中替下「许多」这一平实说法。"},{"en":"A large sample is described as numerous trials or numerous cases.","cn":"大样本常被说成「大量试验」或「大量案例」。"}],"abstract":[{"en":"Numerous is a beach where the shells outnumber the footprints.","cn":"「众多」是一片沙滩，贝壳比脚印还多。"},{"en":"A count becomes a crowd, and a crowd becomes a weight in an argument.","cn":"计数变成人群，人群又变成论证里的分量。"},{"en":"The word never says exactly how many, only that counting would take a while.","cn":"这个词从不说确切多少，只说数起来要花些时间。"}]},"examples":[{"en":"Numerous small faults appeared along the surface of the beam.","cn":"梁的表面出现了许多细小裂纹。"},{"en":"The archive holds numerous letters from the same household.","cn":"档案馆存有这一户人家的许多信件。"},{"en":"Numerous attempts failed before the method was found.","cn":"在找到方法之前，已有许多次尝试失败。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「牛魔若死」——牛魔王的兵多到数不清：众多的","word":"numerous"},"root":"拉丁 numerosus「充满数目的」← numerus「数目、计数」+ -osus「充满」；numerus 更深来源一般认为与「分配」有关。同族 number、numeral、enumerate、numerator 均出 numerus，而 numerous 是该词的形容词。英语十六世纪借入，确切首见年代不确定。","sensesIntro":{"en":"Eight senses count from objects to people, occasions, places, evidence, reasons, samples, and finally to formal register.","cn":"八个义项从物件数到人、场合、地域、证据、理由、样本，最后落到正式语体。"},"semanticMap":{"core":{"en":"CORE IMAGE: shells on a beach, more than anyone could finish counting before the tide turns.","cn":"核心意象：沙滩上的贝壳，多到潮水转向之前谁也数不完。"},"chain":["NUMBER","FULL OF COUNT","MANY THINGS","MANY PEOPLE","MANY OCCASIONS","FORMAL MANY"],"branches":[{"senses":"01 · 04","en":"THE COUNT ITSELF: items large in number, whether stacked or scattered.","cn":"计数本身：数量很大的事物，无论堆叠还是散落。"},{"senses":"02","en":"THE CROWD: a large body of people.","cn":"人群：人数很多的一群人。"},{"senses":"03 · 07","en":"THE REPEATED CASE: many occasions and a large sample of trials.","cn":"重复的个案：许多场合与大量试验样本。"},{"senses":"05 · 06","en":"THE SUPPORTING MATERIAL: many examples and many reasons offered together.","cn":"支撑材料：一起给出的许多例证与许多理由。"},{"senses":"08","en":"THE REGISTER: the formal stand-in for a bare many.","cn":"语体：用于正式写作、替下 many 的说法。"}]},"affixes":{"intro":{"en":"Numerous is Latin numerosus plus the English adjective ending; the stem is the Latin number word.","cn":"numerous 是拉丁 numerosus 加英语形容词词尾；词干就是拉丁语「数目」一词。"},"latinIntro":{"en":"Numerus gives the noun family, -osus turns it into full of, and English keeps the adjective beside number and numeral.","cn":"numerus 提供名词词族，-osus 把它变成「充满」，英语则让这个形容词与 number、numeral 并存。"},"items":[{"word":"numerus","structure":"Latin noun, fourth declension","meaning":"number; count; rank","meaningCN":"数目；计数；队列","example":"The stem names the act of counting.","exampleCN":"这个词干命名计数的行为。"},{"word":"-osus","structure":"Latin adjective suffix","meaning":"full of; abounding in","meaningCN":"充满；多有","example":"The suffix turns a noun into plenty.","exampleCN":"后缀把名词变成「大量」。"},{"word":"numerosus","structure":"Latin adjective","meaning":"numerous; full of number","meaningCN":"众多的；数目多的","example":"Latin already used the adjective for troops and examples.","exampleCN":"拉丁语已用它形容军队与例证。"},{"word":"number","structure":"English noun through French","meaning":"a count; a total","meaningCN":"数目；总数","example":"French carried numerus across the Channel as nombre.","exampleCN":"法语把 numerus 以 nombre 的形式带过海峡。"},{"word":"numeral","structure":"Latin numeralis plus English -al","meaning":"a sign for a number","meaningCN":"数字符号","example":"The family separates the sign from the count.","exampleCN":"词族把符号与计数分开。"},{"word":"enumerate","structure":"Latin enumerare","meaning":"to list one by one","meaningCN":"逐项列举","example":"The verb walks through the items in order.","exampleCN":"动词按顺序把条目走一遍。"},{"word":"numerous","structure":"Latin numerosus","meaning":"many in count","meaningCN":"数量众多的","example":"English shortened the Latin ending to -ous.","exampleCN":"英语把拉丁词尾收成 -ous。"},{"word":"numerously","structure":"English adverb","meaning":"in large numbers","meaningCN":"大量地","example":"The adverb is rare but regular.","exampleCN":"这个副词罕见但构词规则。"},{"word":"-ous","structure":"English adjective suffix from Latin -osus","meaning":"full of; having","meaningCN":"充满；具有","example":"It also builds famous, dangerous and anxious.","exampleCN":"它也构成 famous、dangerous 与 anxious。"},{"word":"numerator","structure":"Latin numerator plus English -or","meaning":"the top term of a fraction","meaningCN":"分数的分子","example":"The counter of parts keeps the number stem.","exampleCN":"分数的「计数者」保留了数目词干。"}],"latinEntries":[{"word":"numerus","structure":"numerus, numeri (n., fourth declension)","meaning":"number; count","meaningCN":"数目；计数"},{"word":"numerosus","structure":"numerosus, numerosa, numerosum (adj.)","meaning":"full of number; numerous","meaningCN":"数目多的；众多的"}],"derivatives":[{"word":"numerously","pos":"adv.","zh":"大量地；众多地"},{"word":"numerousness","pos":"n.","zh":"众多；数量多"}]}},{"word":"obscure","ipa_uk":"/əˈskjʊə(r)/","ipa_us":"/əˈskjʊr/","definition_zh":"晦涩难懂的；不为人知的；昏暗的；使模糊；遮蔽；使黯然失色","definition_en":"hard to understand or not widely known; to make something unclear or hide it from view","core_image":"一层雾把整条街的轮廓抹平，只剩几盏灯还亮着","scene":"档案室里一摞旧卷宗没有编号，封面字迹已经褪成浅灰。The reason for the closure remains obscure.","sceneCN":"这里指原因不明、难以弄清（第 1 个义项：含义不清、不易理解）；句意为关闭的原因至今不明。","pos":[{"tag":"adj.","zh":"晦涩的；无名的；昏暗的；不清楚的"},{"tag":"v.","zh":"使模糊；遮蔽；使不显眼"}],"collocations":[{"phrase":"obscure meaning","zh":"晦涩的含义"},{"phrase":"obscure poet","zh":"无名诗人"},{"phrase":"obscure the view","zh":"遮挡视线"},{"phrase":"obscure the issue","zh":"使问题模糊"},{"phrase":"of obscure origin","zh":"来源不明"},{"phrase":"obscured by cloud","zh":"被云遮住"}],"forms":[{"label":"原形","form":"obscure"},{"label":"比较级","form":"obscurer / more obscure"},{"label":"最高级","form":"obscurest / most obscure"},{"label":"第三人称单数","form":"obscures"},{"label":"过去式","form":"obscured"},{"label":"过去分词","form":"obscured"},{"label":"现在分词","form":"obscuring"}],"derivatives":[{"word":"obscurely","pos":"adv.","zh":"晦涩地；不为人知地"},{"word":"obscurity","pos":"n.","zh":"晦涩；默默无闻；昏暗"},{"word":"obscuration","pos":"n.","zh":"遮蔽；掩盖"},{"word":"obscurantist","pos":"n./adj.","zh":"蒙昧主义者；蒙昧主义的"}],"senses":[{"no":"01","title":"Hard to understand","titleCN":"晦涩难懂","definition":"difficult to understand because the meaning is not clear","definitionCN":"因含义不清而难以理解","example":"The manual is written in obscure language.","exampleCN":"这本手册用晦涩的语言写成。","why":"Latin obscurus began as covered, and a covered meaning is one you cannot see into.","whyCN":"拉丁 obscurus 本义为「被盖住的」，被盖住的意义正是看不进去的意义。"},{"no":"02","title":"Little known","titleCN":"不为人知的","definition":"not famous and known only to a few people","definitionCN":"不出名，只有少数人知道","example":"He quoted an obscure poet from the provinces.","exampleCN":"他引了一位外省的无名诗人。","why":"The same covering hides a person from public view.","whyCN":"同一层「覆盖」也把人挡在公众视野之外。"},{"no":"03","title":"Hidden from sight","titleCN":"被挡住而看不见","definition":"not clearly visible because something blocks the view","definitionCN":"因有物遮挡而看不清","example":"The path was obscure behind the reeds.","exampleCN":"小路在芦苇后面看不清了。","why":"The oldest physical sense is simply dark or covered.","whyCN":"最古老的具体义就是暗或被遮住。"},{"no":"04","title":"To make unclear","titleCN":"使含义模糊","definition":"to make something harder to understand","definitionCN":"使某事物更难理解","example":"Jargon can obscure a simple point.","exampleCN":"行话会把一个简单的要点弄模糊。","why":"The verb applies the cover to meaning itself.","whyCN":"动词把这层遮盖直接盖到意义上。"},{"no":"05","title":"To block light or view","titleCN":"遮挡光线或视线","definition":"to keep light from passing or something from being seen","definitionCN":"挡住光线通过，或使人看不见某物","example":"Dust obscured the lens.","exampleCN":"灰尘遮住了镜头。","why":"The verb keeps the old physical covering intact.","whyCN":"动词保留了古老的具体「遮盖」义。"},{"no":"06","title":"To outshine another","titleCN":"使别人黯然失色","definition":"to make another thing seem less important by comparison","definitionCN":"通过对比使另一事物显得不重要","example":"Her calm presence obscured the panic around her.","exampleCN":"她的镇定让周围的慌乱显得不重要了。","why":"Something covered by a brighter thing disappears from notice.","whyCN":"被更亮之物盖住的东西，自然从视野里消失。"},{"no":"07","title":"Dim or dark","titleCN":"昏暗的","definition":"not bright; dimly lit","definitionCN":"不明亮；光线微弱","example":"The hall was obscure except for one lamp.","exampleCN":"大厅里除了一盏灯，其余地方都很暗。","why":"The Latin word first named darkness, not difficulty.","whyCN":"这个拉丁词最早命名的是黑暗，而不是难懂。"},{"no":"08","title":"Poorly defined in form","titleCN":"形态不明显","definition":"not sharply marked or distinct in shape, as in biology","definitionCN":"轮廓不清晰、形态不分明，如生物学用法","example":"The species has obscure markings on its wings.","exampleCN":"这个物种翅膀上的斑纹不明显。","why":"Science uses the word for edges that cannot be drawn clearly.","whyCN":"科学用它指画不清楚的边缘。"}],"etymology":{"intro":{"en":"Obscure goes back to Latin obscurus, dark or covered or unknown. The direct source is not in doubt, but the internal formation of obscurus is a hypothesis, and its second element is source uncertain.","cn":"obscure 源自拉丁 obscurus「暗的、被盖住的、不为人知的」。直接来源没有疑问，但 obscurus 的内部构词是一种假说，其第二成分来源不确定。"},"items":[{"era":"LATIN OBSCURUS","en":"Obscurus meant dark, dusky, hidden and, by extension, unknown.","cn":"obscurus 意为暗的、昏黑的、隐藏的，引申为不为人知的。"},{"era":"THE PREFIX OB-","en":"The prefix ob- means over, against or in front of, and it supplies the idea of something laid over a thing.","cn":"前缀 ob- 意为在上方、对着、在前方，提供「一物盖在另一物上」的意象。"},{"era":"THE SECOND ELEMENT","en":"The rest is usually connected with a root for covering, seen in scutum, shield; the exact root is source uncertain.","cn":"其余部分通常与表示「覆盖」的词根联系，见于 scutum「盾」；确切词根来源不确定。"},{"era":"OLD FRENCH OBSCUR","en":"Old French passed obscur to English, and the adjective kept both the dark and the unknown senses.","cn":"古法语把 obscur 传给英语，形容词同时保留「暗」与「不为人知」两义。"},{"era":"THE ENGLISH VERB","en":"English also formed a verb, to obscure, which applies the cover to light, view or meaning.","cn":"英语又造出动词 obscure，把这层遮盖加到光线、视线或意义上。"},{"era":"MODERN USE","en":"Critics call difficult writing obscure, while astronomers still speak of obscured light.","cn":"评论者称难读的文字晦涩，天文学家则仍说光线被遮蔽。"}]},"similar":{"note":{"en":"The first group is built on the same Latin adjective or merely resembles it; the second group names kinds of unclearness.","cn":"第一组由同一个拉丁形容词构成或只是形近；第二组是各种「不清楚」的近义说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"obscurity","ipa":"/əˈskjʊərəti/","tag":"same root","definition":"The state of being unclear or unknown; the noun from the same adjective.","definitionCN":"晦涩或默默无闻的状态；同一形容词的名词。"},{"word":"obscurely","ipa":"/əˈskjʊəli/","tag":"same root","definition":"In an unclear or little-known way.","definitionCN":"以晦涩或不为人知的方式。"},{"word":"obscurantism","ipa":"/ˌɒbskjʊˈræntɪzəm/","tag":"same root","definition":"A deliberate keeping of knowledge from people.","definitionCN":"故意不让人们获得知识的做法。"},{"word":"obscene","ipa":"/ɒbˈsiːn/","tag":"different root","definition":"Offensive to moral sense; from Latin obscenus, not from obscurus.","definitionCN":"有伤风化的；出自拉丁 obscenus，与 obscurus 无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"vague","ipa":"/veɪɡ/","tag":"near meaning","definition":"Not clearly expressed or understood.","definitionCN":"表达或理解得不清楚。"},{"word":"ambiguous","ipa":"/ˌæmˈbɪɡjuəs/","tag":"near meaning","definition":"Open to more than one interpretation.","definitionCN":"可作不止一种解释。"},{"word":"arcane","ipa":"/ɑːˈkeɪn/","tag":"near meaning","definition":"Understood by few because it is secret or specialized.","definitionCN":"因隐秘或专门而只有少数人懂。"},{"word":"dim","ipa":"/dɪm/","tag":"near meaning","definition":"Poorly lit; also faint or unclear.","definitionCN":"光线昏暗；也指微弱、不清楚。"},{"word":"unclear","ipa":"/ˌʌnˈklɪə(r)/","tag":"near meaning","definition":"Not easy to see or understand.","definitionCN":"不易看清或理解。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real Latin source, the real family and real collocations.","cn":"正常联想使用真实的拉丁来源、真实同族词与真实搭配。"},"normal":[{"en":"Obscurus meant covered, and a covered meaning is hard to read.","cn":"obscurus 意为被盖住，被盖住的意义自然难读。"},{"en":"Obscurity is the noun, obscurely the adverb, both from the same stem.","cn":"obscurity 是名词，obscurely 是副词，都出自同一词干。"},{"en":"An obscure poet is not a bad poet, only one few people know.","cn":"无名的诗人不等于差诗人，只是少有人知道。"},{"en":"The verb is used both for blocking a view and for blurring an issue, its two oldest shapes.","cn":"这个动词既能用于遮住视线，也能用于把问题弄模糊，这是它最古老的两种用法。"},{"en":"Obscene looks close but comes from a different Latin word.","cn":"obscene 形近，却出自另一个拉丁词。"}],"abstract":[{"en":"Obscure is a lamp behind a curtain: the light is there, but you cannot read by it.","cn":"晦涩是帘子后面的一盏灯：光还在，却读不了书。"},{"en":"Fame and clarity are both kinds of visibility, and the word covers both.","cn":"名声与清晰都是一种「可见」，这个词同时管着两者。"},{"en":"To obscure is not to destroy; it is to lay one thing over another.","cn":"遮蔽不是销毁，而是把一物盖在另一物上。"}]},"examples":[{"en":"The inscription is obscure after a century of rain.","cn":"经过百年雨水，铭文已经看不清了。"},{"en":"An obscure clause in the contract caused the dispute.","cn":"合同里一条晦涩的条款引发了争执。"},{"en":"Heavy curtains obscured the stage from the street.","cn":"厚重的窗帘从街上看遮住了舞台。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「哦不死Q」——雾把路盖住，谁也说不清：晦涩的；遮蔽","word":"obscure"},"root":"拉丁 obscurus「暗的、被盖住的、不为人知的」，一般解为 ob-「在上方、对着」加一个表示「覆盖」的词根，后者见于 scutum「盾」，词根来源不确定。经古法语 obscur 进入英语，形容词兼「晦涩」与「无名」，动词则施遮盖于光线、视线与意义。","sensesIntro":{"en":"Eight senses split between adjective and verb: unclear meaning, little fame, blocked sight, dim light, and the acts of blurring, covering, outshining and blurring an outline.","cn":"八个义项分属形容词与动词：含义不清、默默无闻、视线受阻、光线昏暗，以及使模糊、遮盖、使失色、使轮廓不清四种动作。"},"semanticMap":{"core":{"en":"CORE IMAGE: fog that erases the outline of a street, leaving only a few lamps.","cn":"核心意象：一层雾抹平街道的轮廓，只剩几盏灯。"},"chain":["COVERED","DARK","OUT OF SIGHT","LITTLE KNOWN","UNCLEAR MEANING","POORLY DEFINED"],"branches":[{"senses":"01 · 04","en":"THE UNCLEAR MEANING: writing that is hard to read and the act of making it harder.","cn":"含义不清：难读的文字，以及使之更难读的动作。"},{"senses":"02","en":"THE UNKNOWN PERSON: a name few people recognise.","cn":"无名之人：少有人认得的名字。"},{"senses":"03 · 05 · 07","en":"THE PHYSICAL COVER: something out of sight, light blocked, and a dim room.","cn":"具体的遮盖：看不见的物体、被挡住的光、昏暗的房间。"},{"senses":"06","en":"THE ECLIPSE: one thing made to look small beside another.","cn":"遮没：一物在旁边之物映衬下显得不重要。"},{"senses":"08","en":"THE BLURRED OUTLINE: markings too faint to be drawn clearly.","cn":"模糊的轮廓：淡到画不清的斑纹。"}]},"affixes":{"intro":{"en":"Obscure comes from the Latin adjective obscurus and adds English verb and noun forms; the Latin root is clear, the internal second element is not.","cn":"obscure 来自拉丁形容词 obscurus，并加上英语的动词与名词形式；拉丁来源清楚，内部的第二成分不清楚。"},"latinIntro":{"en":"The prefix ob- is secure; the element behind -scurus is a reconstruction, and the noun obscuritas keeps the abstract side.","cn":"前缀 ob- 可靠；-scurus 背后的成分是重构，抽象义由名词 obscuritas 承担。"},"items":[{"word":"ob-","structure":"Latin prefix","meaning":"over; against; in front of","meaningCN":"在上方；对着；在前方","example":"The prefix lays one thing over another.","exampleCN":"前缀把一物盖到另一物之上。"},{"word":"obscurus","structure":"Latin adjective","meaning":"dark; covered; unknown","meaningCN":"暗的；被盖住的；不为人知的","example":"The adjective already carried both the physical and the mental sense.","exampleCN":"这个形容词已兼具具体与心理两义。"},{"word":"obscuritas","structure":"Latin noun","meaning":"darkness; obscurity","meaningCN":"黑暗；晦涩","example":"The noun names the state rather than the thing.","exampleCN":"名词命名状态，而非事物。"},{"word":"obscurare","structure":"Latin verb","meaning":"to darken; to hide","meaningCN":"使变暗；隐藏","example":"The verb supplies the English action.","exampleCN":"动词提供了英语的动作义。"},{"word":"obscure","structure":"English adjective and verb","meaning":"unclear; to hide","meaningCN":"晦涩的；遮蔽","example":"English keeps the adjective and builds the verb on the same stem.","exampleCN":"英语保留形容词，并用同一词干造出动词。"},{"word":"obscurely","structure":"English adverb","meaning":"in an unclear way","meaningCN":"晦涩地","example":"The adverb marks manner.","exampleCN":"副词标出方式。"},{"word":"obscurity","structure":"English noun from Latin obscuritas","meaning":"the state of being unclear or unknown","meaningCN":"晦涩；无名","example":"The noun covers both difficulty and lack of fame.","exampleCN":"名词兼指难懂与无名。"},{"word":"obscuration","structure":"English noun from Latin obscuratio","meaning":"a covering or darkening","meaningCN":"遮蔽；变暗","example":"The word is rarer and stays close to the physical sense.","exampleCN":"这个词更罕见，贴近具体义。"},{"word":"obscurantism","structure":"English noun","meaning":"deliberate opposition to knowledge","meaningCN":"蒙昧主义","example":"The modern word adds a political edge.","exampleCN":"现代词增添了政治色彩。"},{"word":"-ity","structure":"Latin noun suffix","meaning":"state or quality","meaningCN":"状态或性质","example":"It turns the adjective into a state.","exampleCN":"它把形容词变成状态。"}],"latinEntries":[{"word":"obscurus","structure":"obscurus, obscura, obscurum (adj.)","meaning":"dark; covered; unknown","meaningCN":"暗的；被盖住的；不为人知的"},{"word":"obscuritas","structure":"obscuritas, obscuritatis (n., third declension)","meaning":"darkness; obscurity","meaningCN":"黑暗；晦涩"}],"derivatives":[{"word":"obscurely","pos":"adv.","zh":"晦涩地；不为人知地"},{"word":"obscurity","pos":"n.","zh":"晦涩；默默无闻"},{"word":"obscuration","pos":"n.","zh":"遮蔽；变暗"},{"word":"obscurantist","pos":"n./adj.","zh":"蒙昧主义者；蒙昧主义的"}]}},{"word":"optimal","ipa_uk":"/ˈɒptɪməl/","ipa_us":"/ˈɑːptɪməl/","definition_zh":"最佳的；最优的；最适宜的","definition_en":"best possible under the given conditions; most favourable","core_image":"一把尺子量到刚刚好，不多一格，也不少一格","scene":"调参的人把三组数值来回试了十几遍，最后停在中间那一组。That setting gives optimal performance without extra heat.","sceneCN":"这里指各种条件配合到最好（第 1 个义项：在现有条件下最好的结果）；句意为那组设置带来最佳性能，还不会额外发热。","pos":[{"tag":"adj.","zh":"最佳的；最优的；最适宜的"}],"collocations":[{"phrase":"optimal performance","zh":"最佳性能"},{"phrase":"optimal conditions","zh":"最适条件"},{"phrase":"optimal solution","zh":"最优解"},{"phrase":"optimal use","zh":"最优利用"},{"phrase":"optimal health","zh":"最佳健康状态"},{"phrase":"optimal temperature","zh":"最适温度"}],"forms":[{"label":"原形","form":"optimal"},{"label":"比较级","form":"more optimal"},{"label":"最高级","form":"most optimal"},{"label":"副词","form":"optimally"}],"derivatives":[{"word":"optimally","pos":"adv.","zh":"最佳地；最优地"},{"word":"optimality","pos":"n.","zh":"最优性"},{"word":"suboptimal","pos":"adj.","zh":"次优的；未达最佳的"}],"senses":[{"no":"01","title":"The best possible result","titleCN":"可能的最好结果","definition":"the best outcome available under the present limits","definitionCN":"在现有条件下能得到的最好结果","example":"The team reached an optimal result with the given budget.","exampleCN":"团队用既定预算取得了最佳结果。","why":"Optimus is the Latin superlative of good, so the word names the top of a scale rather than a direction.","whyCN":"optimus 是拉丁语「好」的最高级，因此这个词命名刻度的顶点，而不是某个方向。"},{"no":"02","title":"The most favourable conditions","titleCN":"最适宜的条件","definition":"the conditions under which a process works best","definitionCN":"某过程运作得最好的条件","example":"The plants grow at optimal temperature.","exampleCN":"这些植物在最适温度下生长。","why":"Once the top of the scale is a point, conditions can be tuned to that point.","whyCN":"一旦刻度的顶点成了一个点，条件就可以调到那一点。"},{"no":"03","title":"A mathematical optimum","titleCN":"数学上的最优点","definition":"a point where a function reaches its best value","definitionCN":"函数取得最好值的点","example":"The algorithm searches for an optimal point on the curve.","exampleCN":"算法在曲线上寻找一个最优点。","why":"Calculus formalised the everyday top of a scale as a stationary best value.","whyCN":"微积分把日常说的「顶点」形式化为一个驻定的最优值。"},{"no":"04","title":"An efficient economic allocation","titleCN":"经济学上的最优配置","definition":"the arrangement that uses resources with the least waste","definitionCN":"以最少浪费使用资源的安排","example":"The market reached an optimal allocation of labour.","exampleCN":"市场达到了劳动力的最优配置。","why":"Economics measures the top by output per unit of input.","whyCN":"经济学用每单位投入的产出来衡量这个顶点。"},{"no":"05","title":"The best dose or timing for the body","titleCN":"对身体最合适的剂量或时机","definition":"the amount or moment that does most good and least harm","definitionCN":"收益最大、伤害最小的用量或时点","example":"The trial looked for the optimal dose.","exampleCN":"这项试验寻找最佳剂量。","why":"Medicine turns the scale into a trade-off between benefit and harm.","whyCN":"医学把这个刻度变成收益与伤害之间的权衡。"},{"no":"06","title":"A settled engineering trade-off","titleCN":"工程上权衡后的最优点","definition":"the design point where competing requirements balance best","definitionCN":"各项相争的要求平衡得最好的设计点","example":"Weight and strength meet at an optimal thickness.","exampleCN":"重量与强度在某个最佳厚度上取得平衡。","why":"Engineering makes the top a compromise rather than a single peak.","whyCN":"工程学让这个顶点成为折中，而不是孤峰。"},{"no":"07","title":"A biological best fit","titleCN":"生物学上的最佳适应","definition":"the behaviour or form that suits an environment best","definitionCN":"最适应某环境的行为或形态","example":"The birds show optimal foraging in winter.","exampleCN":"这些鸟在冬季表现出最优觅食。","why":"Biology asks what a body or habit is best fitted to, not what is morally best.","whyCN":"生物学问的是身体或习性最适合什么，而非什么在道德上最好。"},{"no":"08","title":"The sensible everyday choice","titleCN":"日常判断中的最佳选择","definition":"the choice a careful person judges best overall","definitionCN":"谨慎的人综合判断后认为最好的选择","example":"Leaving early was the optimal decision given the traffic.","exampleCN":"考虑到交通，早走是最佳决定。","why":"Everyday speech borrows the superlative for a reasoned preference.","whyCN":"日常语言借这个最高级表达有理由的偏好。"}],"etymology":{"intro":{"en":"Optimal comes from Latin optimus, best, the suppletive superlative of bonus, good, with the English suffix -al. The direct source is clear; the deeper origin of optimus is a hypothesis.","cn":"optimal 来自拉丁 optimus「最好的」，它是 bonus「好的」的补充式最高级，再加英语后缀 -al。直接来源清楚；optimus 更深的来源是一种假说。"},"items":[{"era":"LATIN BONUS","en":"Bonus meant good, but its comparative melior and superlative optimus came from other stems, a suppletion familiar from good, better, best.","cn":"bonus 意为好的，但其比较级 melior 与最高级 optimus 来自别的词干，这种补充式与英语 good、better、best 相似。"},{"era":"LATIN OPTIMUS","en":"Optimus served as best and as most excellent in rank.","cn":"optimus 既作「最好的」，也指品级上最卓越的。"},{"era":"THE OPS HYPOTHESIS","en":"Optimus is often connected with ops, resources or power, which would make the earliest sense richest or most able; the derivation is source uncertain.","cn":"optimus 常与 ops「资源、力量」相联系，若如此则最早义为「最富足」或「最有能力」；这一派生来源不确定。"},{"era":"OPTIMUM","en":"The neuter optimum was borrowed as a noun for the best value, especially in mathematics.","cn":"中性形式 optimum 被借作名词，指最佳值，尤用于数学。"},{"era":"ENGLISH OPTIMAL","en":"English built optimal on optimus in the nineteenth century; the exact first date is uncertain.","cn":"英语在十九世纪用 optimus 造出 optimal，确切首见年代不确定。"},{"era":"MODERN USE","en":"Optimisation, suboptimal and optimal control extend the word without changing its peak sense.","cn":"最优化、次优与最优控制都沿用这个词，未改变其「顶点」义。"}]},"similar":{"note":{"en":"The first group shares the Latin best-stem; the second group names what sits at the top of a scale.","cn":"第一组共享拉丁语「最好」的词干；第二组是处在刻度顶端的近义说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"optimum","ipa":"/ˈɒptɪməm/","tag":"same root","definition":"The best value or point, especially in mathematics.","definitionCN":"最佳值或最优点，尤用于数学。"},{"word":"optimism","ipa":"/ˈɒptɪmɪzəm/","tag":"same root","definition":"The belief that things tend toward the best; coined from the Latin optimum.","definitionCN":"相信事物趋向最好的看法；由拉丁 optimum 造出。"},{"word":"optimize","ipa":"/ˈɒptɪmaɪz/","tag":"same root","definition":"To make something as good as it can be; built on optimum.","definitionCN":"使某物尽可能好；由 optimum 构成。"},{"word":"suboptimal","ipa":"/ˌsʌbˈɒptɪməl/","tag":"same root","definition":"Below the best level, built with the prefix sub-.","definitionCN":"低于最佳水平，由前缀 sub- 构成。"},{"word":"optimistic","ipa":"/ˌɒptɪˈmɪstɪk/","tag":"related form","definition":"Expecting the best outcome.","definitionCN":"期待最好结果。"}]},{"heading":"NEAR MEANING","entries":[{"word":"best","ipa":"/best/","tag":"near meaning","definition":"The highest in quality or rank; the plain English word.","definitionCN":"质量或等级最高的；最平实的英语说法。"},{"word":"ideal","ipa":"/aɪˈdiːl/","tag":"near meaning","definition":"Perfect in an imagined standard, sometimes unattainable.","definitionCN":"符合想象标准的完美，有时难以达到。"},{"word":"favourable","ipa":"/ˈfeɪvərəbl/","tag":"near meaning","definition":"Helpful to a plan or outcome.","definitionCN":"对计划或结果有利的。"},{"word":"prime","ipa":"/praɪm/","tag":"near meaning","definition":"Of the best quality or at the best moment.","definitionCN":"质量最好的或时机最佳的。"},{"word":"peak","ipa":"/piːk/","tag":"near meaning","definition":"The highest point reached.","definitionCN":"达到的最高点。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real Latin superlative, the real family and real collocations.","cn":"正常联想使用真实的拉丁最高级、真实同族词与真实搭配。"},"normal":[{"en":"Optimus is the superlative of bonus, just as best is the superlative of good.","cn":"optimus 是 bonus 的最高级，正如英语中「最好」是「好」的最高级。"},{"en":"Optimum is the noun for the best value; optimal is the adjective.","cn":"optimum 是「最佳值」的名词，optimal 是形容词。"},{"en":"The ops hypothesis would make optimus mean richest before it meant best.","cn":"若按 ops 假说，optimus 最早是「最富足」，后来才成「最好」。"},{"en":"Fixed phrases mark the sense: optimal performance, optimal conditions, optimal dose.","cn":"固定搭配标出义项：最佳性能、最适条件、最佳剂量。"},{"en":"Suboptimal is the useful opposite for anything below the best.","cn":"suboptimal 是表示「未达最佳」的常用反义说法。"}],"abstract":[{"en":"Optimal is a ruler that stops exactly at the mark, with no spare space.","cn":"最优是一把正好停在刻度上的尺子，不留多余空隙。"},{"en":"There can be only one top of a scale, which is why the word tolerates no better.","cn":"一个刻度只能有一个顶点，所以这个词容不下「更好」。"},{"en":"In engineering the peak is a compromise, not a triumph.","cn":"在工程里，顶点是折中，而不是凯旋。"}]},"examples":[{"en":"The optimal route avoids both the tunnel and the rush hour.","cn":"最优路线既避开隧道，也避开高峰时段。"},{"en":"An optimal diet is not the same for every patient.","cn":"最佳饮食对每位病人并不相同。"},{"en":"The engine runs at optimal speed only in cool air.","cn":"这台发动机只在凉爽空气中才以最佳转速运行。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「欧普提莫」——挑到最顶上那一个：最佳的","word":"optimal"},"root":"拉丁 optimus「最好的」，是 bonus「好的」的补充式最高级；更深来源一般认为与 ops「资源、力量」相关，亦有「最高处」的解释，词根来源不确定。中性 optimum 先作名词「最佳值」，英语十九世纪再加 -al 构成形容词，确切首见年代不确定；suboptimal 由 sub- 加 optimal 构成。","sensesIntro":{"en":"Eight senses move from the best result through conditions, mathematics, economics, medicine, engineering and biology to the ordinary reasoned choice.","cn":"八个义项从最好的结果出发，经条件、数学、经济、医学、工程与生物学，最后落到日常有理由的选择。"},"semanticMap":{"core":{"en":"CORE IMAGE: a ruler that stops exactly at the mark, no spare space either side.","cn":"核心意象：一把正好停在刻度上的尺子，两边都不留余地。"},"chain":["GOOD","BEST","TOP OF SCALE","BEST CONDITIONS","BEST POINT","BEST CHOICE"],"branches":[{"senses":"01","en":"THE BEST RESULT: the highest outcome the limits allow.","cn":"最好的结果：条件允许范围内的最高结果。"},{"senses":"02 · 08","en":"THE TUNED CONDITIONS AND THE WISE CHOICE: the setting that suits a process and the choice a person judges best.","cn":"调好的条件与明智的选择：适合某过程的环境，以及人判断为最好的选择。"},{"senses":"03","en":"THE MATHEMATICAL POINT: where a function reaches its best value.","cn":"数学上的点：函数取得最优值之处。"},{"senses":"04 · 06","en":"THE BALANCED ALLOCATION: resources used without waste and a design trade-off settled.","cn":"平衡的配置：资源无浪费地使用，设计权衡得以定案。"},{"senses":"05 · 07","en":"THE BEST FIT FOR A BODY: the dose that helps most and the habit that suits an environment.","cn":"对身体的最佳适配：收益最大的剂量与最适应环境的习性。"}]},"affixes":{"intro":{"en":"Optimal is the Latin best-stem optimus plus the English suffix -al; its noun optimum and its opposite suboptimal came later.","cn":"optimal 是拉丁语「最好」词干 optimus 加英语后缀 -al；名词 optimum 与反义形式 suboptimal 都后起。"},"latinIntro":{"en":"Optimus supplies the superlative, ops is the disputed deeper connection, and optimum supplies the noun.","cn":"optimus 提供最高级，ops 是有争议的更深关联，optimum 提供名词。"},"items":[{"word":"optimus","structure":"Latin adjective, superlative","meaning":"best","meaningCN":"最好的","example":"The superlative closes the scale at the top.","exampleCN":"最高级把刻度封在顶端。"},{"word":"bonus","structure":"Latin adjective, positive","meaning":"good","meaningCN":"好的","example":"Bonus supplies the positive that optimus replaces.","exampleCN":"bonus 提供由 optimus 顶替的原级。"},{"word":"ops","structure":"Latin noun","meaning":"resources; power","meaningCN":"资源；力量","example":"The disputed connection would make best originally richest.","exampleCN":"有争议的关联会让「最好」最早意为「最富足」。"},{"word":"optimum","structure":"Latin neuter adjective used as noun","meaning":"the best value","meaningCN":"最佳值","example":"Mathematics borrowed the neuter as a noun.","exampleCN":"数学把这个中性形式借作名词。"},{"word":"optimal","structure":"English adjective from optimus","meaning":"best under the limits","meaningCN":"条件下最佳的","example":"English adds -al to the Latin stem.","exampleCN":"英语给拉丁词干加上 -al。"},{"word":"optimally","structure":"English adverb","meaning":"in the best way","meaningCN":"最佳地","example":"The adverb marks the manner of reaching the peak.","exampleCN":"副词标出达到顶点的方式。"},{"word":"optimality","structure":"English noun","meaning":"the quality of being best","meaningCN":"最优性","example":"The noun belongs to mathematics and economics.","exampleCN":"这个名词属于数学与经济学。"},{"word":"optimize","structure":"English verb from optimum","meaning":"to make as good as possible","meaningCN":"使最优化","example":"The verb is built on optimum, not on optimal.","exampleCN":"这个动词由 optimum 构成，不是由 optimal。"},{"word":"sub-","structure":"Latin prefix","meaning":"under; below","meaningCN":"在下；低于","example":"The prefix names a level below the best.","exampleCN":"前缀命名低于最佳的水平。"},{"word":"-al","structure":"Latin adjective suffix","meaning":"relating to","meaningCN":"与…相关的","example":"It also builds final, formal and general.","exampleCN":"它也构成 final、formal 与 general。"}],"latinEntries":[{"word":"optimus","structure":"optimus, optima, optimum (adj., superlative)","meaning":"best","meaningCN":"最好的"},{"word":"bonus","structure":"bonus, bona, bonum (adj.)","meaning":"good","meaningCN":"好的"},{"word":"ops","structure":"ops, opis (n., third declension)","meaning":"resources; power","meaningCN":"资源；力量"}],"derivatives":[{"word":"optimally","pos":"adv.","zh":"最佳地"},{"word":"optimality","pos":"n.","zh":"最优性"},{"word":"suboptimal","pos":"adj.","zh":"次优的"}]}},{"word":"permanent","ipa_uk":"/ˈpɜːmənənt/","ipa_us":"/ˈpɜːrmənənt/","definition_zh":"永久的；长期不变的；常设的；正式编制的；（烫发）保持较久的","definition_en":"lasting for a very long time or indefinitely; not temporary","core_image":"石碑上凿出的字，雨水冲了几十年还在","scene":"河岸的界桩深深打进岩层，涨水也没能把它拔起。The border marker is a permanent fixture on the bank.","sceneCN":"这里指长期存在、不会自行消失（第 1 个义项：永久或长期存续的）；句意为这块界标是河岸上永久固定的设施。","pos":[{"tag":"adj.","zh":"永久的；长期的；常设的；正式编制的"},{"tag":"n.","zh":"烫发（口语）"}],"collocations":[{"phrase":"permanent residence","zh":"永久居留"},{"phrase":"permanent job","zh":"正式工作"},{"phrase":"permanent damage","zh":"永久性损害"},{"phrase":"permanent marker","zh":"不褪色记号笔"},{"phrase":"permanent record","zh":"永久档案"},{"phrase":"permanent solution","zh":"长久解决办法"}],"forms":[{"label":"原形","form":"permanent"},{"label":"比较级","form":"more permanent"},{"label":"最高级","form":"most permanent"},{"label":"副词","form":"permanently"},{"label":"名词（单数）","form":"permanent"},{"label":"名词（复数）","form":"permanents"}],"derivatives":[{"word":"permanence","pos":"n.","zh":"永久；持久"},{"word":"permanency","pos":"n.","zh":"永久性；长期职位"},{"word":"permanently","pos":"adv.","zh":"永久地；长期地"},{"word":"impermanent","pos":"adj.","zh":"非永久的；暂时的"},{"word":"impermanence","pos":"n.","zh":"无常；非永久"}],"senses":[{"no":"01","title":"Lasting indefinitely","titleCN":"永久存续","definition":"lasting forever or with no fixed end","definitionCN":"永远存在或没有确定终点","example":"The treaty made the river a permanent boundary.","exampleCN":"条约使这条河成为永久边界。","why":"Latin permanere means to remain through to the end, and the present participle fixes that staying into a quality.","whyCN":"拉丁 permanere 意为「一直留到最后」，现在分词把这层「留住」定成品性。"},{"no":"02","title":"Long-lasting rather than temporary","titleCN":"长期而非临时","definition":"intended to last a long time, in contrast with a temporary arrangement","definitionCN":"打算长期维持，与临时安排相对","example":"They moved into a permanent office after the trial year.","exampleCN":"试行一年后，他们搬进了长期办公室。","why":"Everyday use softens forever into for the foreseeable future.","whyCN":"日常用法把「永远」软化为「可预见的将来」。"},{"no":"03","title":"A regular staff position","titleCN":"正式编制职位","definition":"holding a post with a settled contract rather than a short-term one","definitionCN":"持有稳定合同的岗位，而非短期岗位","example":"She was offered a permanent post in the department.","exampleCN":"系里给了她一个正式职位。","why":"Employment law turns the word into a boundary between contract types.","whyCN":"劳动法把这个词变成合同类型之间的界限。"},{"no":"04","title":"A material that does not fade","titleCN":"不褪色的材料","definition":"marking a material whose colour or mark is meant to stay","definitionCN":"标记一种颜色或印记不易消失的材料","example":"He labelled the box with a permanent marker.","exampleCN":"他用不褪色记号笔在箱子上做了标记。","why":"The adjective moves from the arrangement to the stuff that holds it.","whyCN":"形容词从安排转到承载安排的材质上。"},{"no":"05","title":"A long-holding wave","titleCN":"保持较久的烫发","definition":"a hairstyle whose curl is meant to last for months","definitionCN":"卷发效果能维持数月的发型","example":"She asked the stylist for a permanent before the trip.","exampleCN":"出行前她请理发师给她烫个发。","why":"The trade noun keeps the promise of duration in a small everyday sense.","whyCN":"行业里的名词把「持久」的承诺放进一个日常小义。"},{"no":"06","title":"A resident status","titleCN":"永久居留身份","definition":"the legal right to live in a country without time limit","definitionCN":"在一国无限期居住的合法权利","example":"He applied for permanent residence after five years.","exampleCN":"五年后他申请了永久居留。","why":"Immigration law needs a term for the strongest form of stay.","whyCN":"移民法需要一个词指最稳固的居留形式。"},{"no":"07","title":"Irreversible harm","titleCN":"不可逆的损害","definition":"damage that will not heal or be undone","definitionCN":"不会痊愈或被撤销的损害","example":"The frost caused permanent damage to the buds.","exampleCN":"霜冻对花芽造成了永久性损害。","why":"The word marks the point where repair stops being possible.","whyCN":"这个词标出修复不再可能的那一点。"},{"no":"08","title":"A lasting record","titleCN":"永久档案记录","definition":"an official record that is kept indefinitely","definitionCN":"无限期保存的正式记录","example":"The offence stayed on his permanent record.","exampleCN":"这项过错留在了他的永久档案里。","why":"Bureaucracy uses the word to say that erasure is not allowed.","whyCN":"行政系统用这个词表示不允许抹除。"}],"etymology":{"intro":{"en":"Permanent comes from Latin permanens, the present participle of permanere, to remain throughout, built on per- through and manere to stay. Both parts are clear.","cn":"permanent 来自拉丁 permanens，即 permanere「一直留到最后」的现在分词，由 per-「贯穿」与 manere「停留」构成。两部分都清楚。"},"items":[{"era":"LATIN MANERE","en":"Manere meant to stay, remain or dwell, and it also gives mansion and manor through French.","cn":"manere 意为停留、留下、居住，经法语也给出 mansion 与 manor。"},{"era":"THE PREFIX PER-","en":"Per- means through or throughout, so permanere is to stay through the whole span.","cn":"per- 意为贯穿、始终，因此 permanere 是在整段时间里一直留下。"},{"era":"LATIN PERMANENS","en":"The present participle permanens described a thing that keeps its place or state.","cn":"现在分词 permanens 描述保持位置或状态的事物。"},{"era":"ENGLISH ENTRY","en":"English took permanent in the late Middle Ages; the exact first date is uncertain.","cn":"英语在中世纪晚期借入 permanent，确切首见年代不确定。"},{"era":"THE NOUN FAMILY","en":"Permanence and permanency name the state, while impermanent adds a Latin negative prefix.","cn":"permanence 与 permanency 命名状态，impermanent 则加拉丁否定前缀。"},{"era":"MODERN SPECIALISMS","en":"The word now also names a hairstyle, a marker and a residence status.","cn":"这个词如今还指一种发型、一种记号笔与一种居留身份。"}]},"similar":{"note":{"en":"The first group shares the Latin stay-root; the second group names duration and stability.","cn":"第一组共享拉丁语「停留」词根；第二组是表示持续与稳定的近义说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"permanence","ipa":"/ˈpɜːmənəns/","tag":"same root","definition":"The state of lasting or remaining unchanged.","definitionCN":"持久或保持不变的状态。"},{"word":"permanently","ipa":"/ˈpɜːmənəntli/","tag":"same root","definition":"In a way that is meant to last.","definitionCN":"以打算长久维持的方式。"},{"word":"impermanent","ipa":"/ɪmˈpɜːmənənt/","tag":"same root","definition":"Not lasting; the negative form built with im-.","definitionCN":"不持久的；用 im- 构成的否定形式。"},{"word":"remain","ipa":"/rɪˈmeɪn/","tag":"same root","definition":"To stay behind or continue in a place, from the same Latin verb through French.","definitionCN":"留下或继续在某处，经法语出自同一拉丁动词。"},{"word":"mansion","ipa":"/ˈmænʃn/","tag":"same root","definition":"A large house, from the Latin idea of dwelling.","definitionCN":"大宅，出自拉丁语「居住」的观念。"}]},{"heading":"NEAR MEANING","entries":[{"word":"lasting","ipa":"/ˈlɑːstɪŋ/","tag":"near meaning","definition":"Continuing for a long time, without implying forever.","definitionCN":"持续很久，但不含「永远」。"},{"word":"enduring","ipa":"/ɪnˈdjʊərɪŋ/","tag":"near meaning","definition":"Lasting through hardship or time.","definitionCN":"历经困难或时间仍持续。"},{"word":"perpetual","ipa":"/pəˈpetʃuəl/","tag":"near meaning","definition":"Continuing without interruption, often stronger than permanent.","definitionCN":"不间断地持续，语气常比 permanent 更强。"},{"word":"fixed","ipa":"/fɪkst/","tag":"near meaning","definition":"Set in place and not changing.","definitionCN":"固定就位、不再改变。"},{"word":"stable","ipa":"/ˈsteɪbl/","tag":"near meaning","definition":"Steady and not likely to move or fail.","definitionCN":"稳定，不易移动或失效。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real Latin verb, the real family and real collocations.","cn":"正常联想使用真实的拉丁动词、真实同族词与真实搭配。"},"normal":[{"en":"Manere is to stay, and per- is through, so permanent is to stay through the whole span.","cn":"manere 是停留，per- 是贯穿，所以 permanent 是整段时间都留下。"},{"en":"Mansion and manor come from the same dwelling word.","cn":"mansion 与 manor 出自同一个「居住」词。"},{"en":"Impermanent is the negative: im- plus permanent.","cn":"impermanent 是反义：im- 加 permanent。"},{"en":"Fixed phrases mark the use: permanent residence, permanent job, permanent damage.","cn":"固定搭配标出用法：永久居留、正式工作、永久损害。"},{"en":"A permanent marker keeps its mark; a permanent wave keeps its curl.","cn":"不褪色记号笔留住字迹，烫发留住卷度。"}],"abstract":[{"en":"Permanent is a stone carved with letters that outlast the hand that cut them.","cn":"永久是石头上凿的字，比刻字的手活得更久。"},{"en":"The word promises duration without naming an end, which is why lawyers argue over it.","cn":"这个词承诺持续却不说明终点，所以律师总要争它。"},{"en":"To call a thing permanent is to bet that time will not revise it.","cn":"称某物为永久，就是赌时间不会改写它。"}]},"examples":[{"en":"The bridge was built as a permanent crossing, not a seasonal one.","cn":"这座桥建成永久通道，而非季节性设施。"},{"en":"A permanent loss of hearing followed the explosion.","cn":"爆炸之后出现了永久性听力丧失。"},{"en":"The museum keeps a permanent collection in the east wing.","cn":"博物馆在东翼设有永久藏品。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「泼门能特」——门泼上漆也烂不掉：永久的","word":"permanent"},"root":"拉丁 permanens「一直留下的」← permanere「留到最后」← per-「贯穿」+ manere「停留、居住」。manere 经法语也给出 mansion 与 manor；英语中世纪晚期借入 permanent，确切首见年代不确定。permanence 指状态，impermanent 由 im- 否定；现代另有烫发、不褪色记号笔与永久居留等专义。","sensesIntro":{"en":"Eight senses move from endless duration to long arrangements, posts, materials, hairstyles, statuses, harm and records.","cn":"八个义项从无限持续，转到长期安排、职位、材料、发型、身份、损害与档案。"},"semanticMap":{"core":{"en":"CORE IMAGE: letters cut into stone, still readable after decades of rain.","cn":"核心意象：凿进石头的字，几十年雨水之后仍可辨认。"},"chain":["STAY","THROUGH THE SPAN","LASTING","SETTLED POST","FIXED MATERIAL","UNCHANGING RECORD"],"branches":[{"senses":"01","en":"THE ENDLESS STAY: duration with no fixed end.","cn":"没有终点的停留：没有确定终点的持续。"},{"senses":"02","en":"THE LONG ARRANGEMENT: what is meant to outlast a trial period.","cn":"长期安排：打算熬过试行期的安排。"},{"senses":"03 · 06","en":"THE SETTLED STATUS: a staff post and a residence right.","cn":"稳固的身份：正式职位与居留权利。"},{"senses":"04 · 05","en":"THE FIXED MARK: ink that does not fade and a curl that holds.","cn":"固定的印记：不褪的字迹与持久的卷度。"},{"senses":"07 · 08","en":"THE UNCHANGING RECORD: harm that cannot be undone and a file that is never erased.","cn":"不可改的记录：无法撤销的损害与永不抹除的档案。"}]},"affixes":{"intro":{"en":"Permanent is Latin permanens plus the English adjective ending; the verb permanere carries both per- and manere.","cn":"permanent 是拉丁 permanens 加英语形容词词尾；动词 permanere 同时带着 per- 与 manere。"},"latinIntro":{"en":"Manere gives the stay-root, per- carries it through time, and permanens supplies the participle behind the English adjective.","cn":"manere 提供「停留」词根，per- 让它贯穿时间，permanens 提供英语形容词背后的分词。"},"items":[{"word":"per-","structure":"Latin prefix","meaning":"through; throughout","meaningCN":"贯穿；始终","example":"The prefix stretches the stay across the whole span.","exampleCN":"前缀把「停留」拉满整段时间。"},{"word":"manere","structure":"Latin verb, second conjugation","meaning":"to stay; to remain","meaningCN":"停留；留下","example":"The verb is the plain act of remaining.","exampleCN":"动词就是「留下」这一平实动作。"},{"word":"permanere","structure":"Latin verb, compound of per- and manere","meaning":"to remain throughout","meaningCN":"一直留到最后","example":"Latin joined the two parts into one verb.","exampleCN":"拉丁语把两部分合成一个动词。"},{"word":"permanens","structure":"Latin present participle","meaning":"remaining; lasting","meaningCN":"留下的；持久的","example":"The participle turns the act into a quality.","exampleCN":"分词把动作变成品性。"},{"word":"permanentia","structure":"Latin noun","meaning":"endurance; permanence","meaningCN":"持久；永久","example":"The noun names the state the participle describes.","exampleCN":"名词命名分词所描述的状态。"},{"word":"permanent","structure":"English adjective from permanens","meaning":"lasting; not temporary","meaningCN":"永久的；非临时的","example":"English keeps the participle ending as -ent.","exampleCN":"英语把分词词尾保留为 -ent。"},{"word":"permanence","structure":"English noun","meaning":"the state of lasting","meaningCN":"持久；永久","example":"The noun is the abstract partner of the adjective.","exampleCN":"名词是形容词的抽象搭档。"},{"word":"permanently","structure":"English adverb","meaning":"for a lasting time","meaningCN":"永久地","example":"The adverb marks how long something is meant to stay.","exampleCN":"副词标出打算维持多久。"},{"word":"im-","structure":"Latin negative prefix before p","meaning":"not","meaningCN":"不","example":"The prefix makes impermanent, the negative partner.","exampleCN":"前缀构成 impermanent 这一否定搭档。"},{"word":"impermanent","structure":"English adjective","meaning":"not lasting","meaningCN":"非永久的","example":"The negative keeps the same stay-root.","exampleCN":"否定形式沿用同一「停留」词根。"}],"latinEntries":[{"word":"permanere","structure":"permanere, permansi, permansum (v., second conjugation)","meaning":"to remain throughout","meaningCN":"一直留到最后"},{"word":"manere","structure":"manere, mansi, mansum (v., second conjugation)","meaning":"to stay; to remain","meaningCN":"停留；留下"},{"word":"permanens","structure":"permanens, permanentis (participle)","meaning":"remaining; lasting","meaningCN":"留下的；持久的"}],"derivatives":[{"word":"permanence","pos":"n.","zh":"永久；持久"},{"word":"permanency","pos":"n.","zh":"永久性；长期职位"},{"word":"permanently","pos":"adv.","zh":"永久地；长期地"},{"word":"impermanent","pos":"adj.","zh":"非永久的"},{"word":"impermanence","pos":"n.","zh":"无常；非永久"}]}},{"word":"profound","ipa_uk":"/prəˈfaʊnd/","ipa_us":"/prəˈfaʊnd/","definition_zh":"深刻的；深远的；深奥的；极度的；深度的（医学）","definition_en":"very deep in meaning, knowledge or effect; intense","core_image":"一口井的井底，光只照到井壁上很窄的一圈","scene":"老教授讲完只留一句短话，学生回去想了整晚。Her remark had a profound effect on the whole class.","sceneCN":"这里指影响深入而持久（第 2 个义项：影响深远、强烈而持久）；句意是她那句话对全班产生了深刻影响。","pos":[{"tag":"adj.","zh":"深刻的；深远的；深奥的；极度的；深部的"}],"collocations":[{"phrase":"profound effect","zh":"深远影响"},{"phrase":"profound change","zh":"深刻变化"},{"phrase":"profound knowledge","zh":"渊博学识"},{"phrase":"profound silence","zh":"深沉的寂静"},{"phrase":"profound sleep","zh":"深度睡眠"},{"phrase":"profound insight","zh":"深刻洞见"}],"forms":[{"label":"原形","form":"profound"},{"label":"比较级","form":"profounder / more profound"},{"label":"最高级","form":"profoundest / most profound"},{"label":"副词","form":"profoundly"},{"label":"名词","form":"profoundness"}],"derivatives":[{"word":"profoundly","pos":"adv.","zh":"深刻地；深深地"},{"word":"profundity","pos":"n.","zh":"深刻；深奥"},{"word":"profoundness","pos":"n.","zh":"深刻；深度"}],"senses":[{"no":"01","title":"Deep in meaning","titleCN":"意义深刻","definition":"showing deep thought or understanding","definitionCN":"显出深思或深理解的","example":"The book offers a profound reading of the poem.","exampleCN":"这本书对这首诗给出了深刻的解读。","why":"Latin profundus meant deep like a well, and depth of meaning borrows the same image.","whyCN":"拉丁 profundus 指像井一样的深，意义之深借用了同一意象。"},{"no":"02","title":"Far-reaching in effect","titleCN":"影响深远","definition":"having a strong and lasting influence","definitionCN":"有强烈而持久的影响","example":"The discovery had a profound effect on medicine.","exampleCN":"这项发现对医学有深远影响。","why":"An effect that reaches the bottom is felt long after the surface event.","whyCN":"触到底部的影响，在表面事件过后很久仍能被感到。"},{"no":"03","title":"Deep in knowledge","titleCN":"学识深湛","definition":"showing wide and deep learning","definitionCN":"显出广博而深厚的学识","example":"She is a profound scholar of ancient law.","exampleCN":"她是一位研究古代法律的渊博学者。","why":"The well image marks a mind that has gone far below the surface.","whyCN":"井的意象标出一个远潜于表面之下的心灵。"},{"no":"04","title":"Intense in feeling","titleCN":"情感强烈","definition":"very strong or deeply felt","definitionCN":"非常强烈或感受极深的","example":"A profound sadness settled over the room.","exampleCN":"一种深沉的悲伤笼住了屋子。","why":"Depth of feeling keeps the physical image but moves it into the body.","whyCN":"情感的深度保留具体意象，却把它移进身体里。"},{"no":"05","title":"Deep sleep or unconsciousness","titleCN":"深度睡眠或昏迷","definition":"a state of sleep or lost consciousness from which it is hard to wake","definitionCN":"难以唤醒的深睡或失去意识的状态","example":"The patient fell into a profound sleep.","exampleCN":"病人陷入了深度睡眠。","why":"Clinical language uses depth literally for states below ordinary waking.","whyCN":"临床用语把「深」按字面用于低于寻常清醒的状态。"},{"no":"06","title":"Deep in physical space","titleCN":"空间上深的","definition":"reaching far down or far in from the surface","definitionCN":"从表面向下或向内延伸很远","example":"The mine reaches a profound depth.","exampleCN":"这座矿达到很深的深度。","why":"This is the oldest layer, where the word still points at a hole.","whyCN":"这是最古老的一层，词仍指着洞。"},{"no":"07","title":"Deep silence or darkness","titleCN":"深沉的寂静或黑暗","definition":"complete and heavy, as of silence or dark","definitionCN":"指寂静或黑暗，浓重而彻底","example":"A profound silence followed the question.","exampleCN":"问题之后是一片深沉的寂静。","why":"Anything that feels bottomless can take the word.","whyCN":"凡是让人感到深不见底的事物，都能用这个词。"},{"no":"08","title":"A fundamental change","titleCN":"根本性的变化","definition":"a change that alters the base of a system, not its surface","definitionCN":"改变系统根基而非表层的变化","example":"The reform brought profound change to the courts.","exampleCN":"这场改革给法院带来了根本性变化。","why":"Fundus is the bottom, so a profound change touches what everything stands on.","whyCN":"fundus 是底部，因此深刻的变化触及万物的立足处。"}],"etymology":{"intro":{"en":"Profound comes from Latin profundus, deep or bottomless, from pro- forward or downward plus fundus, bottom. The source and the internal formation are both clear.","cn":"profound 来自拉丁 profundus「深的、无底的」，由 pro-「向前、向下」与 fundus「底部」构成。来源与内部构词都清楚。"},"items":[{"era":"LATIN FUNDUS","en":"Fundus meant the bottom of a thing and also a farm or estate, the land at the base of a holding.","cn":"fundus 指物体的底部，也指农庄或地产，即一份产业的根基之地。"},{"era":"PROFUNDUS","en":"Profundus joined pro- with fundus and meant deep, high in depth, and by extension bottomless.","cn":"profundus 把 pro- 与 fundus 结合，意为深的、深处很大的，引申为无底的。"},{"era":"OLD FRENCH PROFOND","en":"Old French profond carried the adjective into English with the same physical core.","cn":"古法语 profond 把这个形容词带进英语，具体核心义保持不变。"},{"era":"THE MENTAL SHIFT","en":"Depth of water became depth of thought, feeling and knowledge without any new word.","cn":"水之深变成思想、情感与知识之深，并未另造新词。"},{"era":"MEDICAL USE","en":"Clinical writing uses profound for sleep or coma, where depth is again literal.","cn":"临床写作把 profound 用于睡眠或昏迷，那里的「深」又回到字面。"},{"era":"THE FAMILY","en":"Fundus also lies behind foundation and fundamental, which name the base rather than the depth.","cn":"fundus 也藏在 foundation 与 fundamental 背后，那两个词命名根基而非深度。"}]},"similar":{"note":{"en":"The first group shares the Latin bottom-root; the second group names depth of meaning, feeling or effect.","cn":"第一组共享拉丁语「底部」词根；第二组是意义、情感或影响之深的近义说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"profundity","ipa":"/prəˈfʌndəti/","tag":"same root","definition":"Depth of thought or feeling; the noun from the same adjective.","definitionCN":"思想或情感的深度；同一形容词的名词。"},{"word":"profoundly","ipa":"/prəˈfaʊndli/","tag":"same root","definition":"Deeply; to a great degree.","definitionCN":"深深地；极度地。"},{"word":"fundamental","ipa":"/ˌfʌndəˈmentl/","tag":"same root","definition":"Serving as a base; from fundus, not a form of profound.","definitionCN":"作为根基的；出自 fundus，不是 profound 的变形。"},{"word":"foundation","ipa":"/faʊnˈdeɪʃn/","tag":"same root","definition":"The base on which something is built.","definitionCN":"建筑物或事物的根基。"},{"word":"profuse","ipa":"/prəˈfjuːs/","tag":"different root","definition":"Pouring out in great amount; from fundere, to pour, not from fundus.","definitionCN":"大量涌出；出自 fundere「灌注」，与 fundus 无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"deep","ipa":"/diːp/","tag":"near meaning","definition":"Extending far down or far into a subject.","definitionCN":"向下或向主题内部延伸很远。"},{"word":"far-reaching","ipa":"/ˌfɑːˈriːtʃɪŋ/","tag":"near meaning","definition":"Having wide and lasting effects.","definitionCN":"影响宽广而持久。"},{"word":"intense","ipa":"/ɪnˈtens/","tag":"near meaning","definition":"Very strong in degree.","definitionCN":"程度上非常强烈。"},{"word":"penetrating","ipa":"/ˈpenətreɪtɪŋ/","tag":"near meaning","definition":"Reaching below the surface, of insight or gaze.","definitionCN":"洞察或目光直达表面之下。"},{"word":"weighty","ipa":"/ˈweɪti/","tag":"near meaning","definition":"Serious and important, often of words or matters.","definitionCN":"严肃重要，多指言辞或事情。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real Latin parts, the real family and real collocations.","cn":"正常联想使用真实的拉丁构件、真实同族词与真实搭配。"},"normal":[{"en":"Fundus is bottom, pro- is downward, so profound is having its bottom far below.","cn":"fundus 是底，pro- 是向下，所以 profound 是底在很深的地方。"},{"en":"Foundation and fundamental come from fundus, but they name the base, not the depth.","cn":"foundation 与 fundamental 出自 fundus，但命名根基，而非深度。"},{"en":"Profuse looks close but comes from pouring, not from a bottom.","cn":"profuse 形近，却出自「灌注」，不是「底」。"},{"en":"Fixed phrases mark the use: profound effect, profound silence, profound sleep.","cn":"固定搭配标出用法：深远影响、深沉寂静、深度睡眠。"},{"en":"Profundity is the noun for depth of thought or feeling.","cn":"profundity 是思想或情感深度的名词。"}],"abstract":[{"en":"Profound is a well whose bottom you cannot see from the rim.","cn":"深刻是一口从井沿看不见底的井。"},{"en":"A shallow pool can be clear; a deep one holds what light never reaches.","cn":"浅水可以清澈；深水藏着光到不了的东西。"},{"en":"The word moves from water to thought without changing its shape.","cn":"这个词从水移到思想，形状始终未变。"}]},"examples":[{"en":"The lecture left a profound impression on the younger students.","cn":"这场讲座给年轻学生留下了深刻印象。"},{"en":"A profound silence followed the reading of the will.","cn":"宣读遗嘱之后是一片深沉的寂静。"},{"en":"The war brought profound change to the border towns.","cn":"战争给边境城镇带来了深刻变化。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「普若放的」——底放得很深：深刻的","word":"profound"},"root":"拉丁 profundus「深的、无底的」← pro-「向前、向下」+ fundus「底部」；fundus 也指农庄、地产，并衍生 foundation 与 fundamental，但那两个词指根基而非深度。古法语 profond 传入英语；水的深度转为思想、情感与知识之深，医学又按字面用「深度」。","sensesIntro":{"en":"Eight senses descend from the physical well to meaning, effect, learning, feeling, sleep, space, silence and fundamental change.","cn":"八个义项从具体的井往下走，依次是意义、影响、学识、情感、睡眠、空间、寂静与根本性变化。"},"semanticMap":{"core":{"en":"CORE IMAGE: the bottom of a well, where light reaches only a narrow ring on the wall.","cn":"核心意象：井底，光只照到井壁上很窄的一圈。"},"chain":["BOTTOM","FAR DOWN","DEEP WATER","DEEP THOUGHT","STRONG EFFECT","UNSHAKEN BASE"],"branches":[{"senses":"01 · 03","en":"THE DEEP MIND: meaning and learning that go far below the surface.","cn":"深的心智：远潜于表面之下的意义与学识。"},{"senses":"02 · 08","en":"THE DEEP EFFECT: influence that reaches the base and changes it.","cn":"深的影响：抵达根基并改变它的影响。"},{"senses":"04 · 07","en":"THE HEAVY FEELING: intense emotion and a silence that feels bottomless.","cn":"沉重的感受：强烈情感与深不见底的寂静。"},{"senses":"05","en":"THE DEEP STATE: sleep or coma below ordinary waking.","cn":"深的状态：低于寻常清醒的睡眠或昏迷。"},{"senses":"06","en":"THE PHYSICAL DEPTH: a shaft that goes far down.","cn":"具体的深度：向下延伸很远的矿井。"}]},"affixes":{"intro":{"en":"Profound is Latin profundus plus the English adjective form; pro- and fundus are both clear.","cn":"profound 是拉丁 profundus 加英语形容词形式；pro- 与 fundus 两部分都清楚。"},"latinIntro":{"en":"Fundus supplies the bottom, pro- stretches it downward, and profundus carries both.","cn":"fundus 提供「底部」，pro- 把它向下拉长，profundus 兼有两者。"},"items":[{"word":"pro-","structure":"Latin prefix","meaning":"forward; downward","meaningCN":"向前；向下","example":"The prefix stretches the bottom away from the surface.","exampleCN":"前缀把底部从表面向下拉开。"},{"word":"fundus","structure":"Latin noun, second declension","meaning":"bottom; base; farm","meaningCN":"底部；根基；农庄","example":"The stem names what everything stands on.","exampleCN":"词干命名万物所立之处。"},{"word":"profundus","structure":"Latin adjective","meaning":"deep; bottomless","meaningCN":"深的；无底的","example":"The adjective joins the prefix and the bottom.","exampleCN":"形容词把前缀与底部合在一起。"},{"word":"profunditas","structure":"Latin noun","meaning":"depth","meaningCN":"深度","example":"The noun measures the distance to the bottom.","exampleCN":"名词量到井底的距离。"},{"word":"profound","structure":"English adjective from profundus","meaning":"deep in meaning or effect","meaningCN":"意义或影响深的","example":"English keeps the adjective and drops the Latin ending.","exampleCN":"英语保留形容词，收掉拉丁词尾。"},{"word":"profoundly","structure":"English adverb","meaning":"deeply","meaningCN":"深刻地","example":"The adverb marks the degree of an effect.","exampleCN":"副词标出影响的程度。"},{"word":"profundity","structure":"English noun from Latin profunditas","meaning":"depth of thought or feeling","meaningCN":"思想或情感的深度","example":"The noun carries the abstract side.","exampleCN":"名词承担抽象的一面。"},{"word":"foundation","structure":"English noun from Latin fundatio","meaning":"the base of a building or system","meaningCN":"建筑或体系的根基","example":"The family member names the base, not the distance down.","exampleCN":"同族词命名根基，而不是向下的距离。"},{"word":"fundamental","structure":"English adjective from Latin fundamentalis","meaning":"serving as a base","meaningCN":"作为根基的","example":"The adjective belongs to the base line of the family.","exampleCN":"这个形容词属于词族的「根基」一支。"},{"word":"-ous","structure":"Latin adjective ending","meaning":"having the quality of","meaningCN":"具有…性质的","example":"The ending marks the adjective in other Latin borrowings.","exampleCN":"这一词尾在别的拉丁借词里标记形容词。"}],"latinEntries":[{"word":"fundus","structure":"fundus, fundi (n., second declension)","meaning":"bottom; base; estate","meaningCN":"底部；根基；地产"},{"word":"profundus","structure":"profundus, profunda, profundum (adj.)","meaning":"deep; bottomless","meaningCN":"深的；无底的"},{"word":"profunditas","structure":"profunditas, profunditatis (n., third declension)","meaning":"depth","meaningCN":"深度"}],"derivatives":[{"word":"profoundly","pos":"adv.","zh":"深刻地；深深地"},{"word":"profundity","pos":"n.","zh":"深刻；深奥"},{"word":"profoundness","pos":"n.","zh":"深刻；深度"}]}},{"word":"remarkable","ipa_uk":"/rɪˈmɑːkəbl/","ipa_us":"/rɪˈmɑːrkəbl/","definition_zh":"非凡的；值得注意的；显著的；惊人的","definition_en":"unusual or extraordinary enough to be noticed and remembered","core_image":"人群里一个人顶着木箱走路，街上所有人都回头","scene":"赛场边记分牌一路翻上去，观众到最后都站了起来。Her recovery in three weeks was remarkable.","sceneCN":"这里指出色到引人注意（第 2 个义项：明显高于平常水平、出色得非同寻常）；句意为她三周内康复，这件事很了不起。","pos":[{"tag":"adj.","zh":"非凡的；值得注意的；显著的"}],"collocations":[{"phrase":"remarkable achievement","zh":"非凡成就"},{"phrase":"remarkable resemblance","zh":"惊人的相似"},{"phrase":"remarkable recovery","zh":"惊人的康复"},{"phrase":"remarkable progress","zh":"显著进步"},{"phrase":"nothing remarkable","zh":"没有特别之处"},{"phrase":"remarkable for","zh":"以…著称"}],"forms":[{"label":"原形","form":"remarkable"},{"label":"比较级","form":"more remarkable"},{"label":"最高级","form":"most remarkable"},{"label":"副词","form":"remarkably"},{"label":"名词","form":"remarkableness"}],"derivatives":[{"word":"remarkably","pos":"adv.","zh":"非凡地；显著地"},{"word":"remarkableness","pos":"n.","zh":"非凡；引人注目"},{"word":"unremarkable","pos":"adj.","zh":"平淡无奇的"},{"word":"remark","pos":"n./v.","zh":"评论；注意到（基词）"}],"senses":[{"no":"01","title":"Worthy of notice","titleCN":"值得注意","definition":"unusual enough that people notice and comment on it","definitionCN":"不寻常到人们会注意并议论","example":"The tower is remarkable for its narrow base.","exampleCN":"这座塔因塔基极窄而引人注意。","why":"Remark meant to mark or note, and -able means worth, so remarkable is worth marking down.","whyCN":"remark 意为标记、注意，-able 意为值得，因此 remarkable 就是值得记下一笔。"},{"no":"02","title":"Unusually good","titleCN":"出色得非同寻常","definition":"much better than the ordinary level","definitionCN":"明显高于平常水平","example":"Her recovery in three weeks was remarkable.","exampleCN":"她三周内康复，令人惊叹。","why":"The word praises by pointing at difference, not by naming a virtue.","whyCN":"这个词通过指出「不同」来称赞，并不直接命名某种美德。"},{"no":"03","title":"Surprising and strange","titleCN":"奇特而出人意料","definition":"strange enough to attract attention","definitionCN":"奇特到足以吸引注意","example":"A remarkable coincidence brought them to the same train.","exampleCN":"一次奇特的巧合让他们上了同一班火车。","why":"Notice can come from charm or from oddity; the adjective does not choose.","whyCN":"引人注意可能因为迷人，也可能因为古怪，这个形容词并不挑选。"},{"no":"04","title":"Large in degree","titleCN":"程度上显著","definition":"very noticeable in size or amount","definitionCN":"在规模或数量上十分明显","example":"There is a remarkable difference between the two editions.","exampleCN":"两个版本之间有显著差别。","why":"A difference must be marked before it can be called remarkable.","whyCN":"差别要先被「标出」，才能被称为显著。"},{"no":"05","title":"An extraordinary ability","titleCN":"非凡的能力","definition":"a capacity or achievement far above the usual","definitionCN":"远高于寻常的能力或成就","example":"The child showed a remarkable ear for rhythm.","exampleCN":"这孩子对节奏有非凡的听觉。","why":"Talent becomes remarkable when it makes others stop and look.","whyCN":"才能让别人停下来看时，就成了非凡。"},{"no":"06","title":"A striking resemblance","titleCN":"惊人的相似","definition":"a likeness so close that it draws comment","definitionCN":"相似到会引起议论","example":"The two paintings have a remarkable resemblance.","exampleCN":"两幅画有惊人的相似。","why":"Resemblance is noticed before it is explained, and the word marks that moment.","whyCN":"相似先被看见，再被解释，这个词标出看见的那一刻。"},{"no":"07","title":"Known for a trait","titleCN":"因某特点而著称","definition":"notable because of a particular feature","definitionCN":"因某一特征而显眼","example":"The region is remarkable for its dry winters.","exampleCN":"这个地区以冬季干燥著称。","why":"The phrase remarkable for points at the feature that makes a thing stand out.","whyCN":"表示「因某事物而著称」的固定说法直接指向使事物突出的特征。"},{"no":"08","title":"Nothing special, in the negative","titleCN":"否定式中的「平平无奇」","definition":"unworthy of notice when used with nothing or hardly","definitionCN":"与「没有什么」「几乎不」这类否定说法连用时表示不值得注意","example":"There was nothing remarkable about the room.","exampleCN":"这间屋子没有任何特别之处。","why":"The negative shows that the word measures notice, not value.","whyCN":"否定式说明这个词量的是「是否引人注意」，而非价值。"}],"etymology":{"intro":{"en":"Remarkable is English remark plus -able. Remark came from French remarquer, to mark or note, which joins re- with marquer, to mark; the mark itself is Germanic. Only the suffix -able is Latin, so no Latin root is listed.","cn":"remarkable 是英语 remark 加 -able。remark 来自法语 remarquer「标记、注意」，由 re- 与 marquer「标记」构成，而 mark 本身属日耳曼语。只有后缀 -able 源自拉丁，因此不列拉丁词根。"},"items":[{"era":"GERMANIC MARK","en":"The mark in remark is Germanic, from Old English mearc and Old Norse mork, a boundary or sign.","cn":"remark 里的 mark 属日耳曼语，来自古英语 mearc 与古诺斯语 mork，指边界或记号。"},{"era":"FRENCH REMARQUER","en":"French remarquer meant to mark again in the mind, hence to notice or comment.","cn":"法语 remarquer 意为在心上再标一次，因此指注意或评论。"},{"era":"ENGLISH REMARK","en":"English took remark in the seventeenth century as both verb and noun.","cn":"英语在十七世纪借入 remark，兼作动词与名词。"},{"era":"THE SUFFIX -ABLE","en":"The suffix -able comes from Latin -abilis through French and means worth or able to be.","cn":"-able 后缀经法语来自拉丁 -abilis，意为值得或能够被。"},{"era":"ENGLISH REMARKABLE","en":"Remarkable was formed in English; the exact first date is uncertain.","cn":"remarkable 是在英语内部构成的，确切首见年代不确定。"},{"era":"MODERN USE","en":"The word now praises excellence and also marks plain oddity.","cn":"这个词如今既称赞卓越，也标记单纯的古怪。"}]},"similar":{"note":{"en":"The first group shares the mark-and-note stem; the second group names what draws attention.","cn":"第一组共享「标记、注意」的词干；第二组是引人注意的近义说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"remark","ipa":"/rɪˈmɑːk/","tag":"same root","definition":"To say or notice something; the base verb and noun.","definitionCN":"说出或注意到某事；基词动词与名词。"},{"word":"remarkably","ipa":"/rɪˈmɑːkəbli/","tag":"same root","definition":"In a way that draws notice.","definitionCN":"以引人注意的方式。"},{"word":"unremarkable","ipa":"/ˌʌnrɪˈmɑːkəbl/","tag":"same root","definition":"Not worth noticing; the negative form.","definitionCN":"不值得注意的；否定形式。"},{"word":"mark","ipa":"/mɑːk/","tag":"same root","definition":"A sign or trace; Germanic, the core of remark.","definitionCN":"记号或痕迹；日耳曼语，remark 的核心。"},{"word":"marked","ipa":"/ˈmɑːkɪd/","tag":"same root","definition":"Clearly noticeable.","definitionCN":"明显可见的。"}]},{"heading":"NEAR MEANING","entries":[{"word":"notable","ipa":"/ˈnəʊtəbl/","tag":"near meaning","definition":"Worth attention because of importance.","definitionCN":"因重要而值得注意。"},{"word":"extraordinary","ipa":"/ɪkˈstrɔːdnri/","tag":"near meaning","definition":"Far outside the ordinary.","definitionCN":"远在寻常之外。"},{"word":"striking","ipa":"/ˈstraɪkɪŋ/","tag":"near meaning","definition":"So noticeable that it hits the eye.","definitionCN":"显眼到一眼就撞见。"},{"word":"impressive","ipa":"/ɪmˈpresɪv/","tag":"near meaning","definition":"Arousing admiration by size or quality.","definitionCN":"因规模或质量引起钦佩。"},{"word":"exceptional","ipa":"/ɪkˈsepʃənl/","tag":"near meaning","definition":"An exception to the usual rule or level.","definitionCN":"偏离通常规则或水平的例外。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real French and Germanic parts, the real family and real collocations.","cn":"正常联想使用真实的法语与日耳曼语构件、真实同族词与真实搭配。"},"normal":[{"en":"Remark is to mark something in the mind, so remarkable is worth marking.","cn":"remark 是在心里做标记，因此 remarkable 就是值得标记。"},{"en":"The mark inside remark is Germanic, while -able came from Latin through French.","cn":"remark 里的 mark 属日耳曼语，-able 则经法语来自拉丁。"},{"en":"Unremarkable is the negative: un- plus remarkable.","cn":"unremarkable 是反义：un- 加 remarkable。"},{"en":"Fixed phrases mark the use: remarkable achievement, remarkable recovery, nothing remarkable.","cn":"固定搭配标出用法：非凡成就、惊人康复、没有特别之处。"},{"en":"Remarkably is the adverb for the same kind of notice.","cn":"remarkably 是表示同类「引人注意」的副词。"}],"abstract":[{"en":"Remarkable is a raised hand in a quiet room: nothing is said, but everyone turns.","cn":"非凡是在安静的房间里举起一只手：什么都没说，所有人都转过头。"},{"en":"The word does not measure goodness, only how far a thing stands out.","cn":"这个词不量好坏，只量事物突出多远。"},{"en":"To be remarkable is to leave a mark on the memory of others.","cn":"非凡就是在别人的记忆里留下痕迹。"}]},"examples":[{"en":"The bridge is remarkable for its single span.","cn":"这座桥因单跨而著称。"},{"en":"A remarkable number of birds returned to the lake this year.","cn":"今年回到湖上的鸟数量惊人。"},{"en":"His calm under pressure was remarkable.","cn":"他在压力下的镇定非同寻常。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「瑞马克破布」——破布上也做记号，太值得注意了：非凡的","word":"remarkable"},"root":"英语内部构成：remark + -able。remark 来自法语 remarquer「标记、注意」← re- + marquer「标记」，而 mark 属日耳曼语（古英语 mearc、古诺斯语 mork）；只有后缀 -able 经法语源自拉丁 -abilis，故不列拉丁词根。remarkable 确切首见年代不确定，现代兼指卓越与奇特。","sensesIntro":{"en":"Eight senses all measure notice: worth noticing, unusually good, strange, large in degree, extraordinary ability, striking likeness, known for a trait, and the negative nothing special.","cn":"八个义项都在量「是否引人注意」：值得注意、出色、奇特、程度显著、能力非凡、相似惊人、因某点著称，以及否定式的平平无奇。"},"semanticMap":{"core":{"en":"CORE IMAGE: one person in a crowd carrying a crate on the head, every face turning.","cn":"核心意象：人群里一人头顶木箱，所有脸都转过去。"},"chain":["MARK","NOTE","NOTICE","STAND OUT","EXCELLENT","WORTH TELLING"],"branches":[{"senses":"01 · 07","en":"THE NOTICE ITSELF: what is worth marking and what makes a thing known for a trait.","cn":"注意本身：值得记下的事物，以及使事物因某点著称的特征。"},{"senses":"02 · 05","en":"THE HIGH LEVEL: unusually good performance and extraordinary ability.","cn":"高的水平：出色的表现与非凡的能力。"},{"senses":"03","en":"THE ODDITY: a coincidence or event strange enough to draw comment.","cn":"古怪之处：奇特到会引起议论的巧合或事件。"},{"senses":"04 · 06","en":"THE MARKED DIFFERENCE: a large gap between editions and a likeness that draws comment.","cn":"显著的差别：版本间的明显差距与引人议论的相似。"},{"senses":"08","en":"THE NEGATIVE: nothing worth noticing at all.","cn":"否定：完全没有值得注意之处。"}]},"affixes":{"intro":{"en":"Remarkable joins the English verb remark to the suffix -able; the mark inside is Germanic and the suffix is Latin by way of French.","cn":"remarkable 由英语动词 remark 加后缀 -able 构成；里面的 mark 属日耳曼语，后缀则经法语来自拉丁。"},"latinIntro":{"en":"There is no Latin root for this word; only the suffix -abilis is Latin, so the Latin list is left empty.","cn":"这个词没有拉丁词根；只有后缀 -abilis 属拉丁语，因此拉丁词条留空。"},"items":[{"word":"mark","structure":"Germanic noun and verb","meaning":"a sign; to notice","meaningCN":"记号；标记","example":"The core carries the idea of a visible trace.","exampleCN":"核心带着「可见痕迹」的观念。"},{"word":"re-","structure":"Latin prefix through French","meaning":"again; back","meaningCN":"再次；回","example":"French used it to mark again in the mind.","exampleCN":"法语用它表示在心上再标一次。"},{"word":"marquer","structure":"French verb","meaning":"to mark","meaningCN":"标记","example":"French built remarquer on this verb.","exampleCN":"法语在这个动词上造出 remarquer。"},{"word":"remarquer","structure":"French verb","meaning":"to notice; to comment","meaningCN":"注意；评论","example":"The French verb joins marking with attention.","exampleCN":"法语动词把标记与注意合在一起。"},{"word":"remark","structure":"English verb and noun","meaning":"to notice; a comment","meaningCN":"注意到；评论","example":"English borrowed the French verb in the seventeenth century.","exampleCN":"英语在十七世纪借入这个法语动词。"},{"word":"-able","structure":"Latin suffix -abilis through French","meaning":"worth being; able to be","meaningCN":"值得被；能够被","example":"The suffix turns the act into a quality.","exampleCN":"后缀把动作变成品性。"},{"word":"remarkable","structure":"English adjective","meaning":"worth noticing","meaningCN":"值得注意的","example":"English built the adjective on its own verb.","exampleCN":"英语用自己的动词造出这个形容词。"},{"word":"remarkably","structure":"English adverb","meaning":"in a noticeable way","meaningCN":"以引人注意的方式","example":"The adverb marks the degree of notice.","exampleCN":"副词标出引人注意的程度。"},{"word":"unremarkable","structure":"English adjective with un-","meaning":"not worth noticing","meaningCN":"不值得注意的","example":"The negative prefix removes the notice.","exampleCN":"否定前缀取消「注意」。"},{"word":"marked","structure":"English adjective from mark","meaning":"clearly noticeable","meaningCN":"明显的","example":"The past participle keeps the sign visible.","exampleCN":"过去分词让记号保持可见。"}],"latinEntries":[],"derivatives":[{"word":"remarkably","pos":"adv.","zh":"非凡地；显著地"},{"word":"remarkableness","pos":"n.","zh":"非凡；引人注目"},{"word":"unremarkable","pos":"adj.","zh":"平淡无奇的"}]}},{"word":"amplify","ipa_uk":"/ˈæmplɪfaɪ/","ipa_us":"/ˈæmplɪfaɪ/","definition_zh":"放大（声音、信号）；增强；详述；扩充；夸大","definition_en":"to make larger, stronger or louder; to expand in detail","core_image":"一只小喇叭把耳语推成一屋子都听得见的声音","scene":"礼堂后排听不清，工作人员把台上的小盒子调高了一档。A small box on the desk can amplify the speaker's voice for the back rows.","sceneCN":"这里指把声音放大（第 1 个义项：使声音变响）；句意为桌上的小盒子把讲者的声音放大，供后排听清。","pos":[{"tag":"v.","zh":"放大；增强；详述；扩充；夸大"}],"collocations":[{"phrase":"amplify the sound","zh":"放大声音"},{"phrase":"amplify a signal","zh":"增强信号"},{"phrase":"amplify the effect","zh":"加强效果"},{"phrase":"amplify a point","zh":"详述某一要点"},{"phrase":"amplify the risk","zh":"夸大风险"},{"phrase":"DNA amplification","zh":"脱氧核糖核酸扩增"}],"forms":[{"label":"原形","form":"amplify"},{"label":"第三人称单数","form":"amplifies"},{"label":"过去式","form":"amplified"},{"label":"过去分词","form":"amplified"},{"label":"现在分词","form":"amplifying"},{"label":"名词","form":"amplification"},{"label":"施动者","form":"amplifier"}],"derivatives":[{"word":"amplification","pos":"n.","zh":"放大；扩增；详述"},{"word":"amplifier","pos":"n.","zh":"放大器；扩音器"},{"word":"amplified","pos":"adj.","zh":"放大的；增强的"},{"word":"amplifiable","pos":"adj.","zh":"可放大的；可扩增的"}],"senses":[{"no":"01","title":"To make sound louder","titleCN":"使声音变响","definition":"to increase the volume of sound","definitionCN":"提高声音的音量","example":"The hall amplifies every whisper.","exampleCN":"这间大厅会把每一声耳语放大。","why":"Amplificare joined amplus, large, with facere, to make, so the word first meant to make something large.","whyCN":"amplificare 把 amplus「大的」与 facere「做」结合，因此这个词最早意为「使变大」。"},{"no":"02","title":"To strengthen a signal","titleCN":"增强信号","definition":"to raise the strength of an electrical or radio signal","definitionCN":"提高电信号或无线电信号的强度","example":"The repeater amplifies the weak signal.","exampleCN":"中继器把微弱信号增强。","why":"Electronics gave the old word a measurable quantity to enlarge.","whyCN":"电子学给了这个旧词一个可测量的「量」去放大。"},{"no":"03","title":"To intensify an effect","titleCN":"加强效果","definition":"to make an effect stronger or more vivid","definitionCN":"使效果更强、更鲜明","example":"Cold air amplifies the smell of the sea.","exampleCN":"冷空气让海的味道更浓。","why":"Once size becomes strength, anything with intensity can be amplified.","whyCN":"一旦「大」变成「强」，任何有强度的事物都能被放大。"},{"no":"04","title":"To expand in detail","titleCN":"详述、展开","definition":"to add detail to a statement or theme","definitionCN":"给陈述或主题补充细节","example":"The speaker amplified her point with two examples.","exampleCN":"讲者用两个例子详述了她的观点。","why":"Rhetoric used the word for filling out a theme, making it large in words.","whyCN":"修辞学用这个词表示把主题铺开，使其在言辞上变大。"},{"no":"05","title":"To exaggerate","titleCN":"夸大","definition":"to make something seem larger or worse than it is","definitionCN":"使某事物显得比实际更大或更糟","example":"The report amplifies the danger beyond the evidence.","exampleCN":"这份报告把危险夸大到证据之外。","why":"The same enlarging act becomes a fault when it outruns the facts.","whyCN":"同一个「放大」动作一旦超出事实，就成了过失。"},{"no":"06","title":"To multiply DNA","titleCN":"扩增脱氧核糖核酸","definition":"to make many copies of a DNA sequence","definitionCN":"把一段脱氧核糖核酸序列复制成许多份","example":"The lab amplifies a short fragment of the gene.","exampleCN":"实验室扩增了该基因的一小段。","why":"Molecular biology uses amplification for copying, an exact technical enlargement.","whyCN":"分子生物学用「扩增」表示复制，是一种精确的技术性放大。"},{"no":"07","title":"To raise current or voltage","titleCN":"提高电流或电压","definition":"to increase the amplitude of an electrical wave","definitionCN":"增大电波的振幅","example":"The circuit amplifies the current before it reaches the coil.","exampleCN":"电路在电流到达线圈之前将其放大。","why":"The word amplitude itself comes from the same large-stem.","whyCN":"amplitude 一词本身也出自同一个表示「大」的词干。"},{"no":"08","title":"To fill out a rhetorical theme","titleCN":"修辞上的铺陈","definition":"to develop a theme at length for effect","definitionCN":"为效果而把一个主题长时间展开","example":"The old manuals teach students to amplify a proverb.","exampleCN":"旧时手册教学生把一句谚语铺陈成文。","why":"Ancient rhetoric named this exercise amplification, and English kept the verb.","whyCN":"古代修辞学把这套练习称为铺陈，英语保留了动词。"}],"etymology":{"intro":{"en":"Amplify comes from Latin amplificare, to enlarge, from amplus, large, plus facere, to make. The direct source is clear; the origin of amplus itself is uncertain.","cn":"amplify 来自拉丁 amplificare「使变大」，由 amplus「大的」与 facere「做」构成。直接来源清楚；amplus 本身的来源不确定。"},"items":[{"era":"LATIN AMPLUS","en":"Amplus meant large, spacious or ample; its deeper origin is a reconstruction and is source uncertain.","cn":"amplus 意为大的、宽敞的、充足的；其更深来源属重构，来源不确定。"},{"era":"THE SUFFIX -FICARE","en":"The combining form -ficare comes from facere, to make, so amplificare is to make large.","cn":"组合形式 -ficare 来自 facere「做」，因此 amplificare 就是「使变大」。"},{"era":"LATIN AMPLIFICARE","en":"The verb meant to enlarge, increase or widen, and rhetoric used it for expanding a theme.","cn":"这个动词意为扩大、增加、拓宽，修辞学用它表示展开主题。"},{"era":"ENGLISH AMPLIFY","en":"English borrowed the verb in the fifteenth century; the exact first date is uncertain.","cn":"英语在十五世纪借入这个动词，确切首见年代不确定。"},{"era":"ELECTRONICS","en":"The noun amplifier was coined for devices that raise signal strength in the twentieth century.","cn":"名词 amplifier 在二十世纪被造出，指提高信号强度的装置。"},{"era":"MOLECULAR BIOLOGY","en":"The same verb now names the copying of DNA, where enlargement is exact multiplication.","cn":"同一个动词如今命名 DNA 的复制，那里的「放大」是精确的倍增。"}]},"similar":{"note":{"en":"The first group shares the Latin large-making stem; the second group names ways of adding size, strength or detail.","cn":"第一组共享拉丁语「使变大」的词干；第二组是增加规模、强度或细节的近义说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"amplification","ipa":"/ˌæmplɪfɪˈkeɪʃn/","tag":"same root","definition":"The act of enlarging sound, signal or detail.","definitionCN":"放大声音、信号或细节的行为。"},{"word":"amplifier","ipa":"/ˈæmplɪfaɪə(r)/","tag":"same root","definition":"A device that raises the strength of a signal.","definitionCN":"提高信号强度的装置。"},{"word":"amplitude","ipa":"/ˈæmplɪtjuːd/","tag":"same root","definition":"The size of a wave's swing, from the same large-stem.","definitionCN":"波摆动的幅度，出自同一「大」词干。"},{"word":"ample","ipa":"/ˈæmpl/","tag":"same root","definition":"More than enough in size or supply.","definitionCN":"在规模或供给上绰绰有余。"},{"word":"amplify","ipa":"/ˈæmplɪfaɪ/","tag":"same root","definition":"The verb itself; note that amplifier is built on it, not the reverse.","definitionCN":"动词本身；注意 amplifier 由它构成，而非相反。"}]},{"heading":"NEAR MEANING","entries":[{"word":"magnify","ipa":"/ˈmæɡnɪfaɪ/","tag":"near meaning","definition":"To make something look bigger, especially through a lens.","definitionCN":"使某物看起来更大，尤指通过透镜。"},{"word":"intensify","ipa":"/ɪnˈtensɪfaɪ/","tag":"near meaning","definition":"To make stronger in degree.","definitionCN":"使程度更强。"},{"word":"expand","ipa":"/ɪkˈspænd/","tag":"near meaning","definition":"To grow larger in size or scope.","definitionCN":"在规模或范围上变大。"},{"word":"boost","ipa":"/buːst/","tag":"near meaning","definition":"To raise or push up, often a signal or level.","definitionCN":"提高、推高，常指信号或水平。"},{"word":"exaggerate","ipa":"/ɪɡˈzædʒəreɪt/","tag":"near meaning","definition":"To describe something as larger than it is.","definitionCN":"把某物说得比实际更大。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real Latin parts, the real family and real collocations.","cn":"正常联想使用真实的拉丁构件、真实同族词与真实搭配。"},"normal":[{"en":"Amplificare is amplus plus facere: to make large.","cn":"amplificare 是 amplus 加 facere：使变大。"},{"en":"The amplifier is the device, and amplification is the act.","cn":"amplifier 是装置，amplification 是行为。"},{"en":"The word runs from sound to signal to feeling to detail to genetic copying.","cn":"这个词从声音走到信号、感受、细节，再到基因复制。"},{"en":"Fixed phrases mark the use: amplify the sound, amplify a signal, amplify a point.","cn":"固定搭配标出用法：放大声音、增强信号、详述要点。"},{"en":"Amplify is not augment: one magnifies what is there, the other adds more to it.","cn":"amplify 不是 augment：前者放大已有之物，后者往里添更多。"}],"abstract":[{"en":"Amplify is a bell that turns a small tap into a sound across the valley.","cn":"放大是一口钟，把轻轻一碰变成满谷的声音。"},{"en":"The same act can serve truth or falsehood, depending on what is fed in.","cn":"同一个放大动作既能服务真相，也能服务谎言，取决于输入什么。"},{"en":"To amplify is to make a thing more itself, not to make it another thing.","cn":"放大是让事物更像它自己，而不是变成别的东西。"}]},"examples":[{"en":"The microphone can amplify a voice without changing its tone.","cn":"麦克风能把声音放大，却不改变音色。"},{"en":"The lost keys seemed to amplify the worry of the whole family.","cn":"钥匙丢了，全家的担忧仿佛被放大了。"},{"en":"The essay uses three pages to amplify one short proverb.","cn":"这篇文章用三页篇幅铺陈一句短谚语。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「安普利法艾」——安个小喇叭，声音放到最大：放大","word":"amplify"},"root":"拉丁 amplificare「使变大」← amplus「大的、宽敞的」+ -ficare（来自 facere「做」）。amplus 更深来源属重构，来源不确定；英语十五世纪借入，确切首见年代不确定。同族 amplitude、ample 与 amplifier 共用「大」的词干；现代又用于电子信号与 DNA 扩增。与 augment 不同：amplify 放大已有之物，augment 另行添加。","sensesIntro":{"en":"Eight senses enlarge sound, signal, effect, detail, a claim, DNA, current and a rhetorical theme.","cn":"八个义项分别放大声音、信号、效果、细节、说法、脱氧核糖核酸、电流与修辞主题。"},"semanticMap":{"core":{"en":"CORE IMAGE: a small horn that turns a whisper into a room-filling sound.","cn":"核心意象：一只小喇叭把耳语变成满屋都听得见的声音。"},"chain":["LARGE","MAKE LARGE","LOUDER","STRONGER SIGNAL","RICHER DETAIL","MORE THAN IT IS"],"branches":[{"senses":"01 · 07","en":"THE SOUND AND THE CURRENT: louder volume and a larger electrical swing.","cn":"声音与电流：更大的音量与更大的电波振幅。"},{"senses":"02","en":"THE SIGNAL: a weak carrier made strong enough to travel.","cn":"信号：把微弱载波增强到能传远。"},{"senses":"03 · 05","en":"THE STRONGER EFFECT: intensity raised, and a claim pushed past the facts.","cn":"更强的效果：强度被提高，说法被推到事实之外。"},{"senses":"04 · 08","en":"THE FULLER THEME: a point filled out and an old rhetorical exercise.","cn":"更饱满的主题：被补充细节的要点与古老的修辞练习。"},{"senses":"06","en":"THE COPIED GENE: exact multiplication in the laboratory.","cn":"被复制的基因：实验室里的精确倍增。"}]},"affixes":{"intro":{"en":"Amplify is Latin amplificare, with amplus and facere both visible inside the verb.","cn":"amplify 是拉丁 amplificare，动词内部两个构件 amplus 与 facere 都看得见。"},"latinIntro":{"en":"Amplus supplies the size, -ficare supplies the making, and the noun amplification keeps the act.","cn":"amplus 提供「大」，-ficare 提供「做」，名词 amplification 保留这一行为。"},"items":[{"word":"amplus","structure":"Latin adjective","meaning":"large; spacious; ample","meaningCN":"大的；宽敞的；充足的","example":"The adjective supplies the size that is to be increased.","exampleCN":"形容词提供待增大的规模。"},{"word":"facere","structure":"Latin verb","meaning":"to make; to do","meaningCN":"做；制造","example":"The verb supplies the making in -ficare.","exampleCN":"动词在 -ficare 中提供「制造」。"},{"word":"-ficare","structure":"Latin combining form","meaning":"to make","meaningCN":"使成为","example":"The form turns an adjective into a verb of making.","exampleCN":"这一形式把形容词变成「使…」的动词。"},{"word":"amplificare","structure":"Latin verb","meaning":"to enlarge; to expand","meaningCN":"扩大；展开","example":"Latin already used it for widening and for rhetoric.","exampleCN":"拉丁语已用它表示拓宽与修辞铺陈。"},{"word":"amplify","structure":"English verb from amplificare","meaning":"to make larger or stronger","meaningCN":"放大；增强","example":"English shortened the Latin verb.","exampleCN":"英语把拉丁动词缩短。"},{"word":"amplification","structure":"English noun from Latin amplificatio","meaning":"the act of enlarging","meaningCN":"放大的行为","example":"The noun names the act rather than the device.","exampleCN":"名词命名行为，而非装置。"},{"word":"amplifier","structure":"English noun, amplify plus -er","meaning":"a device that raises a signal","meaningCN":"放大器","example":"The agent suffix names the thing that does the work.","exampleCN":"施动后缀命名干这件事的物件。"},{"word":"amplitude","structure":"English noun from Latin amplitudo","meaning":"the size of a swing","meaningCN":"振幅；幅度","example":"The noun measures how far a wave moves.","exampleCN":"名词量波摆动的幅度。"},{"word":"ample","structure":"English adjective from Latin amplus","meaning":"more than enough","meaningCN":"充足的","example":"The adjective keeps the plain sense of size.","exampleCN":"形容词保留「大」的平实义。"},{"word":"-ify","structure":"English verb suffix from Latin -ificare","meaning":"to make","meaningCN":"使…","example":"It also builds simplify, clarify and verify.","exampleCN":"它也构成 simplify、clarify 与 verify。"}],"latinEntries":[{"word":"amplus","structure":"amplus, ampla, amplum (adj.)","meaning":"large; ample","meaningCN":"大的；充足的"},{"word":"amplificare","structure":"amplificare, amplificavi, amplificatum (v., first conjugation)","meaning":"to enlarge","meaningCN":"扩大"},{"word":"amplitudo","structure":"amplitudo, amplitudinis (n., third declension)","meaning":"size; amplitude","meaningCN":"大小；幅度"}],"derivatives":[{"word":"amplification","pos":"n.","zh":"放大；扩增；详述"},{"word":"amplifier","pos":"n.","zh":"放大器；扩音器"},{"word":"amplified","pos":"adj.","zh":"放大的；增强的"},{"word":"amplifiable","pos":"adj.","zh":"可放大的"}]}},{"word":"augment","ipa_uk":"/ɔːɡˈment/","ipa_us":"/ɔːɡˈment/","definition_zh":"增加；增大；扩充；增援；（音乐）增音","definition_en":"to add to something so that it becomes larger or stronger","core_image":"一只木桶里的水被一勺一勺添到桶沿","scene":"预算本上原本够用的数字，被一行行新条目往后推。New staff were hired to augment the small team.","sceneCN":"这里指在原有基础上追加人手（第 1 个义项：在已有之物上增加）；句意为雇了新员工来扩充这个小团队。","pos":[{"tag":"v.","zh":"增加；增大；扩充；增强"}],"collocations":[{"phrase":"augment income","zh":"增加收入"},{"phrase":"augment the team","zh":"扩充团队"},{"phrase":"augment resources","zh":"补充资源"},{"phrase":"augment the force","zh":"增强兵力"},{"phrase":"augmented reality","zh":"增强现实"},{"phrase":"augment a dose","zh":"增加剂量"}],"forms":[{"label":"原形","form":"augment"},{"label":"第三人称单数","form":"augments"},{"label":"过去式","form":"augmented"},{"label":"过去分词","form":"augmented"},{"label":"现在分词","form":"augmenting"},{"label":"名词","form":"augmentation"},{"label":"形容词","form":"augmented"}],"derivatives":[{"word":"augmentation","pos":"n.","zh":"增加；增大；增强"},{"word":"augmented","pos":"adj.","zh":"增强的；增音的"},{"word":"augmentative","pos":"adj.","zh":"增加的；增强的"},{"word":"augmenter","pos":"n.","zh":"增加者；增强装置"}],"senses":[{"no":"01","title":"To add to what already exists","titleCN":"在已有之物上增加","definition":"to make something larger by adding to it","definitionCN":"通过添加使某物变大","example":"New staff were hired to augment the small team.","exampleCN":"雇了新员工来扩充这个小团队。","why":"Augmentum came from augere, to increase, and the verb always assumes something already there to add to.","whyCN":"augmentum 出自 augere「增加」，这个动词总预设已有某物可供添加。"},{"no":"02","title":"To supplement income or resources","titleCN":"补充收入或资源","definition":"to add a second source so that a supply becomes sufficient","definitionCN":"增加第二个来源，使供给变得充足","example":"She augmented her salary with evening teaching.","exampleCN":"她用晚间教学补充薪水。","why":"The added part fills a gap rather than replacing the whole.","whyCN":"添加的部分填补缺口，而不是替换整体。"},{"no":"03","title":"To strengthen a force","titleCN":"增强兵力","definition":"to add troops or equipment to an existing force","definitionCN":"给现有力量增加兵员或装备","example":"Two companies were sent to augment the garrison.","exampleCN":"派了两个连去增强驻军。","why":"Military language keeps the plain sense of adding men to a line.","whyCN":"军事用语保留「往队列里添人」的平实义。"},{"no":"04","title":"To raise a dose or treatment","titleCN":"提高剂量或加强治疗","definition":"to increase the amount of a medicine or therapy","definitionCN":"增加药物或治疗的用量","example":"The doctor augmented the dose after the first week.","exampleCN":"第一周后医生增加了剂量。","why":"Medicine adds to a regimen rather than magnifying a signal.","whyCN":"医学往方案里添加，而不是放大信号。"},{"no":"05","title":"To raise a musical interval","titleCN":"音乐中增大音程","definition":"to widen a musical interval by a semitone","definitionCN":"把音程扩大一个半音","example":"The theme is augmented in the second movement.","exampleCN":"主题在第二乐章中被增音扩大。","why":"Music gave the old verb a precise measured addition.","whyCN":"音乐给了这个旧动词一种精确可量的添加。"},{"no":"06","title":"A grammatical prefix","titleCN":"语法上的增音","definition":"a prefix added to a verb in some older Indo-European languages","definitionCN":"在一些古老印欧语言中加到动词前的附加成分","example":"Greek marks past time with an augment before the stem.","exampleCN":"希腊语在词干前加增音来标记过去时。","why":"Grammar borrowed the word for an addition fixed to the front of a form.","whyCN":"语法学借这个词，指固定在词形前端的附加成分。"},{"no":"07","title":"To add a factor of production","titleCN":"增加生产要素","definition":"to increase labour, capital or another input","definitionCN":"增加劳动力、资本或其他投入","example":"The firm augmented capital rather than labour.","exampleCN":"这家企业增加的是资本，而不是劳动力。","why":"Economics counts the addition as an input, not as intensity.","whyCN":"经济学把这种添加算作投入，而不是强度。"},{"no":"08","title":"To lay extra information over reality","titleCN":"在现实之上叠加信息","definition":"to add a layer of digital information to what is seen","definitionCN":"在所见之物上添加一层数字信息","example":"The glasses augment the street with names and times.","exampleCN":"这副眼镜在街景上叠加名称与时刻。","why":"Augmented reality keeps the additive sense: the world is not replaced, only enlarged.","whyCN":"增强现实保留了「添加」义：世界没有被替换，只是被扩充。"}],"etymology":{"intro":{"en":"Augment comes from Latin augmentare, to increase, from augmentum, an increase, from augere, to make grow. The line is clear; the deeper root is usually connected with growth.","cn":"augment 来自拉丁 augmentare「增加」，出自 augmentum「增量」，再追到 augere「使增长」。线索清楚；更深词根一般与「生长」相关。"},"items":[{"era":"LATIN AUGERE","en":"Augere meant to increase, enlarge or enrich, and it also lies behind auctor, the one who causes growth.","cn":"augere 意为增加、扩大、使丰盛，也藏在 auctor「使事物生长者」背后。"},{"era":"AUGMENTUM","en":"Augmentum was the increase itself, the amount added to something already present.","cn":"augmentum 指增量本身，即加到已有之物上的那一部分。"},{"era":"LATIN AUGMENTARE","en":"The verb turned the noun into an act of adding, used of troops, wealth and honour.","cn":"动词把名词变成「添加」的行为，用于军队、财富与荣誉。"},{"era":"ENGLISH AUGMENT","en":"English took the verb in the late Middle Ages; the exact first date is uncertain.","cn":"英语在中世纪晚期借入这个动词，确切首见年代不确定。"},{"era":"MUSIC AND GRAMMAR","en":"Music and grammar borrowed the word for measured additions to intervals and verb stems.","cn":"音乐与语法学借这个词，指对音程与动词词干的定量添加。"},{"era":"AUGMENTED REALITY","en":"Late twentieth-century computing added a digital layer and kept the word additive.","cn":"二十世纪后期的计算技术添加了一层数字信息，仍保留「添加」义。"}]},"similar":{"note":{"en":"The first group shares the Latin growth stem; the second group names other ways of making something larger.","cn":"第一组共享拉丁语「增长」词干；第二组是使某物变大的其他近义说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"augmentation","ipa":"/ˌɔːɡmenˈteɪʃn/","tag":"same root","definition":"The act of adding to something; the noun.","definitionCN":"对某物添加的行为；名词。"},{"word":"augmented","ipa":"/ɔːɡˈmentɪd/","tag":"same root","definition":"Having something added, as in augmented reality.","definitionCN":"被添加了东西的，如增强现实。"},{"word":"augmentative","ipa":"/ɔːɡˈmentətɪv/","tag":"same root","definition":"Serving to increase or enlarge.","definitionCN":"起增加或扩大作用的。"},{"word":"auction","ipa":"/ˈɔːkʃn/","tag":"same root","definition":"A sale where bids increase the price; from the same growth verb.","definitionCN":"出价使价格上升的拍卖；出自同一「增长」动词。"},{"word":"author","ipa":"/ˈɔːθə(r)/","tag":"same root","definition":"One who causes something to come into being, from auctor.","definitionCN":"使事物产生的人，出自 auctor。"}]},{"heading":"NEAR MEANING","entries":[{"word":"increase","ipa":"/ɪnˈkriːs/","tag":"near meaning","definition":"To become or make greater in size or amount.","definitionCN":"在规模或数量上变大。"},{"word":"supplement","ipa":"/ˈsʌplɪment/","tag":"near meaning","definition":"To add something extra to fill a gap.","definitionCN":"添加额外之物以补缺口。"},{"word":"boost","ipa":"/buːst/","tag":"near meaning","definition":"To raise or push up quickly.","definitionCN":"快速提高或推高。"},{"word":"reinforce","ipa":"/ˌriːɪnˈfɔːs/","tag":"near meaning","definition":"To strengthen, especially a force or structure.","definitionCN":"加强，尤指力量或结构。"},{"word":"expand","ipa":"/ɪkˈspænd/","tag":"near meaning","definition":"To grow larger in extent or scope.","definitionCN":"在范围或规模上变大。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real Latin growth verb, the real family and real collocations.","cn":"正常联想使用真实的拉丁「增长」动词、真实同族词与真实搭配。"},"normal":[{"en":"Augere is to increase, and augmentum is the amount added.","cn":"augere 是增加，augmentum 是添进去的量。"},{"en":"Auctor and auction come from the same growth verb.","cn":"auctor 与 auction 出自同一个「增长」动词。"},{"en":"Augment adds to what is there; amplify makes what is there larger in effect.","cn":"augment 往已有之物里添，amplify 把已有之物的效果放大。"},{"en":"Fixed phrases mark the use: augment income, augment the team, augmented reality.","cn":"固定搭配标出用法：增加收入、扩充团队、增强现实。"},{"en":"Music augments an interval, grammar augments a verb stem.","cn":"音乐增大音程，语法学给动词词干加增音。"}],"abstract":[{"en":"Augment is a bucket filled spoon by spoon until it reaches the rim.","cn":"增加是一勺一勺把桶添到桶沿。"},{"en":"The word never replaces; it always puts something beside what is already there.","cn":"这个词从不替换，总是把某物放到已有之物旁边。"},{"en":"Augmented reality is the old idea in glass: the street plus a layer of names.","cn":"增强现实是旧观念落在镜片上：街道之上多一层名字。"}]},"examples":[{"en":"The scholarship augmented his savings but did not cover the rent.","cn":"奖学金补充了他的存款，却不够付房租。"},{"en":"Volunteers augmented the thin staff at the shelter.","cn":"志愿者补充了收容所单薄的人手。"},{"en":"The second theme augments the first by a full tone.","cn":"第二主题把第一主题整整扩大一个全音。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「奥格门特」——往桶里再添一格：增加","word":"augment"},"root":"拉丁 augmentare「增加」← augmentum「增量」← augere「使增长」。同族 auctor「使事物生长者」与 auction「竞价拍卖」都出 augere；英语中世纪晚期借入，确切首见年代不确定。音乐与语法学借指定量添加，现代又有增强现实义。与 amplify 的区别：augment 另行添加，amplify 放大已有之物。","sensesIntro":{"en":"Eight senses all add something: to an existing whole, to a supply, a force, a dose, an interval, a verb stem, a capital stock, and a digital layer over the world.","cn":"八个义项都在「添加」：向已有整体、供给、兵力、剂量、音程、动词词干、资本存量，以及现实之上的数字层。"},"semanticMap":{"core":{"en":"CORE IMAGE: a bucket filled one spoon at a time until the water reaches the rim.","cn":"核心意象：一只木桶被一勺一勺添到桶沿。"},"chain":["GROW","INCREASE","ADD TO","SUPPLEMENT","STRENGTHEN","LAYER OVER"],"branches":[{"senses":"01 · 02","en":"THE ADDED PART: what is put beside an existing whole and a second source of supply.","cn":"添加的部分：放在已有整体旁边之物，以及第二个供给来源。"},{"senses":"03 · 07","en":"THE STRONGER STOCK: more troops in the line and more capital in the firm.","cn":"更厚的存量：队列里更多兵员，企业里更多资本。"},{"senses":"04","en":"THE RAISED DOSE: more medicine in the regimen.","cn":"提高的剂量：方案里更多的药。"},{"senses":"05 · 06","en":"THE MEASURED ADDITION: a wider interval and a prefix fixed to a verb.","cn":"定量的添加：扩大的音程与加在动词前的成分。"},{"senses":"08","en":"THE ADDED LAYER: digital information laid over the visible world.","cn":"添加的层：铺在可见世界之上的数字信息。"}]},"affixes":{"intro":{"en":"Augment is the Latin growth verb with its noun and participle; augere sits at the centre.","cn":"augment 是拉丁「增长」动词及其名词、分词形式；中心是 augere。"},"latinIntro":{"en":"Augere supplies growth, augmentum the amount added, and augmentare the act of adding.","cn":"augere 提供「增长」，augmentum 提供「添加的量」，augmentare 提供「添加」的行为。"},"items":[{"word":"augere","structure":"Latin verb, second conjugation","meaning":"to increase; to make grow","meaningCN":"增加；使增长","example":"The verb is the source of the whole family.","exampleCN":"这个动词是整个词族的源头。"},{"word":"augmentum","structure":"Latin noun from augere","meaning":"an increase; added amount","meaningCN":"增量；添加的量","example":"The noun names what is added, not the act.","exampleCN":"名词命名被添加之物，而非行为。"},{"word":"augmentare","structure":"Latin verb from augmentum","meaning":"to increase; to add to","meaningCN":"增加；添加","example":"Latin turned the noun back into a verb.","exampleCN":"拉丁语又把名词变回动词。"},{"word":"augment","structure":"English verb from augmentare","meaning":"to add to; to enlarge","meaningCN":"增加；扩充","example":"English keeps the verb and later makes a noun again.","exampleCN":"英语保留动词，后来又造出名词。"},{"word":"augmentation","structure":"English noun from Latin augmentatio","meaning":"the act of adding","meaningCN":"增加的行为","example":"The noun returns in learned and technical use.","exampleCN":"名词在学术与技术语境中回归。"},{"word":"augmented","structure":"English participle and adjective","meaning":"having something added","meaningCN":"被添加的；增强的","example":"The participle names the state after the act.","exampleCN":"分词命名行为之后的状态。"},{"word":"augmentative","structure":"English adjective","meaning":"serving to enlarge","meaningCN":"起增大作用的","example":"The adjective describes a force or suffix that enlarges.","exampleCN":"形容词描述起增大作用的力量或后缀。"},{"word":"auctor","structure":"Latin noun from augere","meaning":"one who causes growth; author","meaningCN":"使事物生长者；作者","example":"The same stem names the one who makes things come about.","exampleCN":"同一词干命名使事物产生的人。"},{"word":"auctio","structure":"Latin noun from augere","meaning":"a sale by rising bids","meaningCN":"竞价拍卖","example":"The bidding makes the price grow.","exampleCN":"竞价使价格增长。"},{"word":"-ment","structure":"Latin noun suffix through French","meaning":"result or act","meaningCN":"结果或行为","example":"The suffix turns verbs into nouns of result.","exampleCN":"后缀把动词变成表结果的名词。"}],"latinEntries":[{"word":"augere","structure":"augere, auxi, auctum (v., second conjugation)","meaning":"to increase; to make grow","meaningCN":"增加；使增长"},{"word":"augmentum","structure":"augmentum, augmenti (n., second conjugation)","meaning":"increase; added amount","meaningCN":"增量；添加的量"}],"derivatives":[{"word":"augmentation","pos":"n.","zh":"增加；增大；增强"},{"word":"augmented","pos":"adj.","zh":"增强的；增音的"},{"word":"augmentative","pos":"adj.","zh":"增加的；增强的"},{"word":"augmenter","pos":"n.","zh":"增加者；增强装置"}]}},{"word":"authenticate","ipa_uk":"/ɔːˈθentɪkeɪt/","ipa_us":"/ɔːˈθentɪkeɪt/","definition_zh":"鉴定（真伪）；证明……真实；验证身份；（计算机）认证","definition_en":"to prove that something is genuine or that a person or device is what it claims to be","core_image":"一枚旧印章在放大镜下被逐条比对纹路","scene":"拍卖行的人把画翻到背面，对着灯看纸的年轮。An expert was called in to authenticate the painting.","sceneCN":"这里指鉴定物件是否为真品（第 1 个义项：证明某物为真）；句意为请来专家鉴定这幅画的真伪。","pos":[{"tag":"v.","zh":"鉴定真伪；证明真实性；验证身份；认证"}],"collocations":[{"phrase":"authenticate a painting","zh":"鉴定画作"},{"phrase":"authenticate a signature","zh":"验证签名"},{"phrase":"authenticate a user","zh":"验证用户身份"},{"phrase":"authenticate a document","zh":"证明文件为真"},{"phrase":"authenticate evidence","zh":"鉴真证据"},{"phrase":"authenticate a transaction","zh":"核验交易"}],"forms":[{"label":"原形","form":"authenticate"},{"label":"第三人称单数","form":"authenticates"},{"label":"过去式","form":"authenticated"},{"label":"过去分词","form":"authenticated"},{"label":"现在分词","form":"authenticating"},{"label":"名词","form":"authentication"},{"label":"施动者","form":"authenticator"},{"label":"形容词","form":"authentic"}],"derivatives":[{"word":"authentication","pos":"n.","zh":"鉴定；认证"},{"word":"authenticator","pos":"n.","zh":"验证器；认证者"},{"word":"authenticated","pos":"adj.","zh":"已鉴定的；已认证的"},{"word":"authenticity","pos":"n.","zh":"真实性；可靠性"}],"senses":[{"no":"01","title":"To prove something genuine","titleCN":"证明某物为真品","definition":"to establish that an object or document is what it claims to be","definitionCN":"确认某物或文件确如其声称","example":"An expert was called in to authenticate the painting.","exampleCN":"请来一位专家鉴定这幅画。","why":"Greek authentikos meant genuine or original, and the verb makes that judgement an act.","whyCN":"希腊 authentikos 意为「真的、原本的」，动词把这个判断变成一项行为。"},{"no":"02","title":"To verify a person's identity","titleCN":"验证人的身份","definition":"to confirm that a person is who they say they are","definitionCN":"确认某人确为其自称之人","example":"The bank authenticates every caller before moving money.","exampleCN":"银行在动钱之前会验证每一位来电者。","why":"Identity is the modern field where the word is used most often.","whyCN":"身份是现代使用这个词最频繁的领域。"},{"no":"03","title":"To certify a signature or seal","titleCN":"证明签名或印章为真","definition":"to confirm that a signature or seal was made by the right hand","definitionCN":"确认签名或印章出自有权之人","example":"A notary authenticated the signature on the deed.","exampleCN":"公证人证明了契据上的签名。","why":"Law needs a trusted hand to say that another hand was genuine.","whyCN":"法律需要一双可信的手来宣告另一双手为真。"},{"no":"04","title":"To log a user into a system","titleCN":"计算机系统中认证用户","definition":"to check credentials before granting access","definitionCN":"在授予访问权之前核验凭证","example":"The app authenticates users with a one-time code.","exampleCN":"这款应用用一次性验证码认证用户。","why":"Computing shortened the legal judgement into a routine check.","whyCN":"计算技术把法律的判断压缩成例行核验。"},{"no":"05","title":"To establish evidence as genuine","titleCN":"确认证据为真","definition":"to show that evidence is original and unaltered","definitionCN":"证明证据为原件且未被改动","example":"The court must authenticate the recording before using it.","exampleCN":"法院在使用录音之前必须先确认其为真。","why":"Evidence must be traced to its source before it can speak.","whyCN":"证据必须先追溯到来源，才能开口作证。"},{"no":"06","title":"To verify a financial transaction","titleCN":"核验金融交易","definition":"to confirm that a payment or message came from the stated sender","definitionCN":"确认支付或讯息确由所称发送者发出","example":"The network authenticates the transfer in seconds.","exampleCN":"网络在几秒内核验了这笔转账。","why":"Money moves only when the sender can be proven.","whyCN":"只有发送者能被证明，钱才动得了。"},{"no":"07","title":"To judge a work of art","titleCN":"鉴定艺术品","definition":"to decide whether a work was made by the claimed artist or period","definitionCN":"判定作品是否出自所称的艺术家或年代","example":"Two laboratories authenticated the canvas.","exampleCN":"两家实验室鉴定了这幅画布。","why":"The art market rests on a judgement that a hand and a date are real.","whyCN":"艺术市场靠的是一个判断：那双手与那个年代是真的。"},{"no":"08","title":"To establish a claim as credible","titleCN":"确认说法可信","definition":"to give a statement enough support to be believed","definitionCN":"给某说法足够支撑，使其可信","example":"The data authenticate his account of the accident.","exampleCN":"数据证实了他对事故的叙述。","why":"The word can widen from objects to any claim that needs a warrant.","whyCN":"这个词可以从物件扩展到任何需要凭据的说法。"}],"etymology":{"intro":{"en":"Authenticate comes from Greek authentikos, genuine or original, through Latin authenticus and French authentique, with the English verb suffix -ate. The direct source is clear; the second element of the Greek noun authentes is source uncertain.","cn":"authenticate 源自希腊 authentikos「真的、原本的」，经拉丁 authenticus 与法语 authentique，再加英语动词后缀 -ate。直接来源清楚；希腊名词 authentes 的第二成分来源不确定。"},"items":[{"era":"GREEK AUTOS","en":"Autos meant self, and it is the first element of authentes.","cn":"autos 意为自身，是 authentes 的第一成分。"},{"era":"GREEK AUTHENTES","en":"Authentes meant one who acts on his own authority, a master or doer; the second element is often read as a doer but is source uncertain.","cn":"authentes 意为凭自身权威行事的人，即主人或行为者；第二成分常被解作「做者」，但来源不确定。"},{"era":"AUTHENTIKOS","en":"Authentikos meant genuine, original and principal, said of things that carry their own authority.","cn":"authentikos 意为真的、原本的、主要的，用于本身带有权威的事物。"},{"era":"LATIN AND FRENCH","en":"Latin authenticus and French authentique carried the adjective into English.","cn":"拉丁 authenticus 与法语 authentique 把这个形容词带进英语。"},{"era":"THE VERB -ATE","en":"English added the verb suffix -ate, making the judgement an action.","cn":"英语加上动词后缀 -ate，把判断变成动作。"},{"era":"DIGITAL AUTHENTICATION","en":"Computing gave the verb its busiest modern home, where credentials replace seals.","cn":"计算技术给了这个动词最繁忙的现代归宿，凭证取代了印章。"}]},"similar":{"note":{"en":"The first group shares the Greek genuine-stem; the second group names checking and proving.","cn":"第一组共享希腊语「真」的词干；第二组是核验与证明的近义说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"authentic","ipa":"/ɔːˈθentɪk/","tag":"same root","definition":"Genuine and true to its claimed origin.","definitionCN":"真正的，符合其声称来源的。"},{"word":"authenticity","ipa":"/ˌɔːθenˈtɪsəti/","tag":"same root","definition":"The quality of being genuine.","definitionCN":"真实性。"},{"word":"authentication","ipa":"/ɔːˌθentɪˈkeɪʃn/","tag":"same root","definition":"The act or process of proving genuineness.","definitionCN":"证明真实性的行为或过程。"},{"word":"authenticator","ipa":"/ɔːˈθentɪkeɪtə(r)/","tag":"same root","definition":"A person or device that verifies identity.","definitionCN":"验证身份的人或装置。"},{"word":"author","ipa":"/ˈɔːθə(r)/","tag":"different root","definition":"A writer or originator; from Latin auctor, not from Greek authentes.","definitionCN":"作者或创始者；出自拉丁 auctor，与希腊 authentes 无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"verify","ipa":"/ˈverɪfaɪ/","tag":"near meaning","definition":"To check that something is true or accurate.","definitionCN":"核查某事物为真或准确。"},{"word":"validate","ipa":"/ˈvælɪdeɪt/","tag":"near meaning","definition":"To confirm that something is valid or acceptable.","definitionCN":"确认某事物有效或可接受。"},{"word":"certify","ipa":"/ˈsɜːtɪfaɪ/","tag":"near meaning","definition":"To state officially that something is true.","definitionCN":"正式声明某事物为真。"},{"word":"confirm","ipa":"/kənˈfɜːm/","tag":"near meaning","definition":"To establish the truth of something more firmly.","definitionCN":"更牢固地确立某事物的真实性。"},{"word":"attest","ipa":"/əˈtest/","tag":"near meaning","definition":"To bear witness to a fact.","definitionCN":"为某一事实作证。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real Greek source, the real family and real collocations.","cn":"正常联想使用真实的希腊来源、真实同族词与真实搭配。"},"normal":[{"en":"Autos is self, and authentes is one who acts on his own authority.","cn":"autos 是自身，authentes 是凭自身权威行事的人。"},{"en":"Authentic is the adjective, authenticity the noun, authentication the process.","cn":"authentic 是形容词，authenticity 是名词，authentication 是过程。"},{"en":"A notary authenticates a signature; a server authenticates a user.","cn":"公证人证明签名，服务器认证用户。"},{"en":"Fixed phrases mark the use: authenticate a painting, authenticate a document, authenticate a transaction.","cn":"固定搭配标出用法：鉴定画作、证明文件、核验交易。"},{"en":"Author looks close but comes from a different Latin word.","cn":"author 形近，却出自另一个拉丁词。"}],"abstract":[{"en":"Authenticate is a lens over an old seal, line by line until the pattern matches.","cn":"鉴定是拿放大镜对着一枚旧印章，一条条纹路比对到吻合。"},{"en":"A thing is authentic when its origin can be traced, not merely when it looks right.","cn":"事物之为真，在于来源可追，而不只在于看起来像。"},{"en":"Every password is a small claim that someone must prove.","cn":"每一个密码都是一个待证明的小小声称。"}]},"examples":[{"en":"The dealer refused to authenticate the letter without its envelope.","cn":"没有信封，经销商拒绝证明这封信为真。"},{"en":"The system authenticates each device before it joins the network.","cn":"设备加入网络之前，系统会逐一认证。"},{"en":"No one could authenticate the story of the missing hours.","cn":"没有人能证实那几小时空白里的说法。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「奥森提凯特」——把真东西挑出来盖章：鉴定为真","word":"authenticate"},"root":"希腊 authentikos「真的、原本的、主要的」← authentes「凭自身权威行事者」← autos「自身」加一个来源不确定的第二成分；经拉丁 authenticus 与法语 authentique 进入英语，再加动词后缀 -ate。同族 authentic、authenticity、authentication；author 形近但出自拉丁 auctor，与此无关。","sensesIntro":{"en":"Eight senses prove genuineness in objects, persons, seals, systems, evidence, payments, art and claims.","cn":"八个义项在物件、人、印章、系统、证据、支付、艺术品与说法上证明真实。"},"semanticMap":{"core":{"en":"CORE IMAGE: an old seal under a lens, its lines matched one by one.","cn":"核心意象：放大镜下的旧印章，纹路被逐条比对。"},"chain":["SELF","OWN AUTHORITY","GENUINE","PROVEN","CERTIFIED","ACCESS GRANTED"],"branches":[{"senses":"01 · 07","en":"THE GENUINE OBJECT: a painting or document traced to its true origin.","cn":"真品：被追溯到真实来源的画作或文件。"},{"senses":"02","en":"THE PROVEN PERSON: a caller or user confirmed as themselves.","cn":"被证明的人：被确认确为其本人的来电者或用户。"},{"senses":"03 · 05","en":"THE TRUSTED MARK AND THE EVIDENCE: a certified signature and a recording traced to its source.","cn":"可信的印记与证据：被证明的签名与被追溯来源的录音。"},{"senses":"04 · 06","en":"THE SYSTEM CHECK: credentials accepted and a payment confirmed from its sender.","cn":"系统核验：凭证被接受，支付被确认由发送者发出。"},{"senses":"08","en":"THE CREDIBLE CLAIM: a story given enough support to be believed.","cn":"可信的说法：获得足够支撑而可被相信的叙述。"}]},"affixes":{"intro":{"en":"Authenticate is the Greek genuine-adjective plus the English verb suffix -ate; the Greek noun behind it has one uncertain element.","cn":"authenticate 是希腊语「真」的形容词加英语动词后缀 -ate；其背后的希腊名词有一个成分不确定。"},"latinIntro":{"en":"Greek authentikos reached Latin as authenticus and then French; the Latin forms are carriers, not the origin.","cn":"希腊 authentikos 以 authenticus 进入拉丁，再进法语；拉丁形式是载体，不是源头。"},"items":[{"word":"autos","structure":"Greek pronoun","meaning":"self","meaningCN":"自身","example":"The first element points at a thing acting on its own.","exampleCN":"第一成分指向凭自身行动之物。"},{"word":"authentes","structure":"Greek noun","meaning":"one acting on his own authority","meaningCN":"凭自身权威行事者","example":"The noun joins self to a doer of uncertain form.","exampleCN":"名词把「自身」与一个形式不确定的「做者」相加。"},{"word":"authentikos","structure":"Greek adjective","meaning":"genuine; original","meaningCN":"真的；原本的","example":"The adjective turns authority into genuineness.","exampleCN":"形容词把权威变成真实性。"},{"word":"authenticus","structure":"Latin adjective from Greek","meaning":"genuine; original","meaningCN":"真的；原本的","example":"Latin carried the Greek adjective westward.","exampleCN":"拉丁语把这个希腊形容词向西传递。"},{"word":"authentique","structure":"French adjective","meaning":"genuine","meaningCN":"真的","example":"French brought the word to English.","exampleCN":"法语把这个词带到英语。"},{"word":"authentic","structure":"English adjective","meaning":"genuine","meaningCN":"真正的","example":"The adjective survives beside the longer verb.","exampleCN":"形容词与更长的动词并存。"},{"word":"authenticate","structure":"English verb, authentic plus -ate","meaning":"to prove genuine","meaningCN":"证明为真","example":"The suffix turns the quality into an act.","exampleCN":"后缀把性质变成行为。"},{"word":"authentication","structure":"English noun from the verb","meaning":"the act of proving","meaningCN":"证明的行为","example":"The noun names the process rather than the quality.","exampleCN":"名词命名过程，而非性质。"},{"word":"authenticity","structure":"English noun from authentic","meaning":"the state of being genuine","meaningCN":"真实性","example":"The noun belongs to the adjective, not the verb.","exampleCN":"这个名词属于形容词，而非动词。"},{"word":"-ate","structure":"Latin verb suffix","meaning":"to make; to act","meaningCN":"使；做","example":"It also builds validate, activate and calculate.","exampleCN":"它也构成 validate、activate 与 calculate。"}],"latinEntries":[{"word":"authenticus","structure":"authenticus, authentica, authenticum (adj.)","meaning":"genuine; original","meaningCN":"真的；原本的"},{"word":"authenticare","structure":"authenticare (v., medieval Latin)","meaning":"to make authentic","meaningCN":"使成为真品"}],"derivatives":[{"word":"authentication","pos":"n.","zh":"鉴定；认证"},{"word":"authenticator","pos":"n.","zh":"验证器；认证者"},{"word":"authenticated","pos":"adj.","zh":"已鉴定的；已认证的"},{"word":"authenticity","pos":"n.","zh":"真实性；可靠性"}]}},{"word":"compile","ipa_uk":"/kəmˈpaɪl/","ipa_us":"/kəmˈpaɪl/","definition_zh":"编纂；汇编；收集整理；（计算机）编译","definition_en":"to gather material together into a book, list or file; to translate source code into machine instructions","core_image":"一摞散页被按页码收进同一只硬壳夹","scene":"编辑桌上摊着几十封信，她把它们按年份装进同一册。She spent a year compiling letters into a single volume.","sceneCN":"这里指把零散材料收集整理成一部作品（第 1 个义项：汇编成书）；句意是她花一年时间把信件汇编成一册。","pos":[{"tag":"v.","zh":"编纂；汇编；收集整理；编译"}],"collocations":[{"phrase":"compile a dictionary","zh":"编纂词典"},{"phrase":"compile a list","zh":"编制清单"},{"phrase":"compile data","zh":"汇总数据"},{"phrase":"compile a report","zh":"编写报告"},{"phrase":"compile source code","zh":"编译源代码"},{"phrase":"compile an index","zh":"编索引"}],"forms":[{"label":"原形","form":"compile"},{"label":"第三人称单数","form":"compiles"},{"label":"过去式","form":"compiled"},{"label":"过去分词","form":"compiled"},{"label":"现在分词","form":"compiling"},{"label":"名词","form":"compilation"},{"label":"施动者","form":"compiler"}],"derivatives":[{"word":"compilation","pos":"n.","zh":"编纂；汇编；编译产物"},{"word":"compiler","pos":"n.","zh":"编纂者；编译器"},{"word":"compiled","pos":"adj.","zh":"汇编的；编译的"},{"word":"compilable","pos":"adj.","zh":"可编译的"}],"senses":[{"no":"01","title":"To gather material into a book","titleCN":"把材料汇编成书","definition":"to collect scattered writings and arrange them into one work","definitionCN":"收集零散文字并编排成一部作品","example":"She compiled the letters into a single volume.","exampleCN":"她把这些信件汇编成一册。","why":"Latin compilare meant to gather together, and book-making gave the gathering a finished shape.","whyCN":"拉丁 compilare 意为聚拢，制书让这种聚拢有了完成形态。"},{"no":"02","title":"To make a list","titleCN":"编制清单","definition":"to draw up items in an ordered list","definitionCN":"把条目按次序列成清单","example":"He compiled a list of every address in the district.","exampleCN":"他编了一份全区地址清单。","why":"A list is the smallest finished form that gathering can take.","whyCN":"清单是「聚拢」能取得的最小完成形态。"},{"no":"03","title":"To assemble data for use","titleCN":"汇总数据备用","definition":"to collect figures from many sources into one set","definitionCN":"把多处数字汇集为一套","example":"The office compiled the figures before the meeting.","exampleCN":"办公室在会前汇总了这些数字。","why":"Modern administration gathers first and decides later.","whyCN":"现代行政先汇集，后决定。"},{"no":"04","title":"To translate source code","titleCN":"编译源代码","definition":"to turn a program written by a person into instructions a machine can run","definitionCN":"把人类写的程序转成机器能执行的指令","example":"The compiler turns each source file into an object file.","exampleCN":"编译器把每个源文件转成目标文件。","why":"Computing borrowed the gathering word for a one-way translation into machine form.","whyCN":"计算技术借这个「汇集」词，指单向转成机器形式。"},{"no":"05","title":"To collect evidence","titleCN":"汇集证据","definition":"to bring together documents and facts for an argument","definitionCN":"为论证把文件与事实聚在一起","example":"The lawyer compiled the records into one file.","exampleCN":"律师把这些记录汇入一个卷宗。","why":"The old sense of gathering without order survives in this use.","whyCN":"古老的无序聚拢义在这种用法里仍然活着。"},{"no":"06","title":"To build an index or catalogue","titleCN":"编索引或目录","definition":"to arrange entries so that each can be found","definitionCN":"把条目编排到每一条都可查到","example":"The librarian compiled an index of the collection.","exampleCN":"馆员为这批藏书编了索引。","why":"Order is added to the gathering, and the result is a finding tool.","whyCN":"聚拢之上加了次序，结果就是检索工具。"},{"no":"07","title":"To draw up a report","titleCN":"编写报告","definition":"to put gathered facts into a formal written account","definitionCN":"把汇集的事实写成正式叙述","example":"The team compiled a report on the flood damage.","exampleCN":"团队编写了一份洪灾损失报告。","why":"The word moves from collecting to composing without leaving the desk.","whyCN":"这个词从收集走到撰写，始终没有离开书桌。"},{"no":"08","title":"To make an anthology","titleCN":"编成选集","definition":"to choose pieces and arrange them as a collection","definitionCN":"挑选篇目并编排成集","example":"The editor compiled an anthology of river poems.","exampleCN":"编者编了一部河流诗选。","why":"Selection and arrangement are the two halves of compiling.","whyCN":"挑选与编排是「编」的两半。"}],"etymology":{"intro":{"en":"Compile comes from Latin compilare, to gather together, perhaps also to plunder, from com- together plus pilare. The direct source is clear; the meaning of pilare in this compound is source uncertain.","cn":"compile 来自拉丁 compilare「聚拢」，也可能带「掠夺」义，由 com-「一起」与 pilare 构成。直接来源清楚；pilare 在这个复合词中的含义来源不确定。"},"items":[{"era":"LATIN COMPILARE","en":"Compilare meant to plunder, to gather together and to heap up, with the idea of things brought into one place.","cn":"compilare 意为掠夺、聚拢、堆起，核心是把东西弄到一处。"},{"era":"THE PREFIX COM-","en":"Com- means together, and it supplies the collecting force of the verb.","cn":"com- 意为一起，提供这个动词的收集力量。"},{"era":"THE ELEMENT PILARE","en":"Pilare is connected with pressing or plucking, but which of those senses belongs to this compound is source uncertain.","cn":"pilare 与压、拔相关，但在此复合词中取哪一义，来源不确定。"},{"era":"FRENCH COMPILER","en":"Old French compiler narrowed the word to the gathering of writings.","cn":"古法语 compiler 把词义收窄到文字的汇集。"},{"era":"ENGLISH COMPILE","en":"English took the verb in the late Middle Ages; the exact first date is uncertain.","cn":"英语在中世纪晚期借入这个动词，确切首见年代不确定。"},{"era":"COMPUTING","en":"In the 1950s the word was given to the translation of source code, which gathers programmes into machine form.","cn":"二十世纪五十年代，这个词被用于源代码翻译，即把程序汇集为机器形式。"}]},"similar":{"note":{"en":"The first group shares the Latin gathering stem; the second group names collecting and arranging.","cn":"第一组共享拉丁语「聚拢」词干；第二组是收集与编排的近义说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"compilation","ipa":"/kəmˈpaɪleɪʃn/","tag":"same root","definition":"A collection put together, or the act of making one.","definitionCN":"编成的集子，或编成的行为。"},{"word":"compiler","ipa":"/kəmˈpaɪlə(r)/","tag":"same root","definition":"A person who compiles, or a program that translates code.","definitionCN":"编纂者，或翻译代码的程序。"},{"word":"compiled","ipa":"/kəmˈpaɪld/","tag":"same root","definition":"Gathered together into one form.","definitionCN":"被汇集成一种形式的。"},{"word":"compile","ipa":"/kəmˈpaɪl/","tag":"same root","definition":"The verb itself; note compiler is built on it.","definitionCN":"动词本身；注意 compiler 由它构成。"},{"word":"comply","ipa":"/kəmˈplaɪ/","tag":"different root","definition":"To obey a rule; from Latin complere, to fill, not from compilare.","definitionCN":"服从规则；出自拉丁 complere「填满」，与 compilare 无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"collect","ipa":"/kəˈlekt/","tag":"near meaning","definition":"To bring things together, often without arranging them.","definitionCN":"把东西聚到一起，常不含编排。"},{"word":"assemble","ipa":"/əˈsembl/","tag":"near meaning","definition":"To put parts together into a whole.","definitionCN":"把部件装成一个整体。"},{"word":"gather","ipa":"/ˈɡæðə(r)/","tag":"near meaning","definition":"To bring scattered things into one place.","definitionCN":"把散落之物聚到一处。"},{"word":"edit","ipa":"/ˈedɪt/","tag":"near meaning","definition":"To prepare material for publication.","definitionCN":"为出版而整理材料。"},{"word":"anthologize","ipa":"/ænˈθɒlədʒaɪz/","tag":"near meaning","definition":"To collect chosen pieces into a volume.","definitionCN":"把挑选的篇目编成一册。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real Latin verb, the real family and real collocations.","cn":"正常联想使用真实的拉丁动词、真实同族词与真实搭配。"},"normal":[{"en":"Compilare is to gather together, and the book is the gathered thing made visible.","cn":"compilare 是聚拢，而书就是让聚拢之物显现的形态。"},{"en":"Compiler is the person and, later, the program that gathers code into machine form.","cn":"compiler 先是编纂的人，后来是汇集代码为机器形式的程序。"},{"en":"Comply looks close but comes from filling, not from gathering.","cn":"comply 形近，却出自「填满」，不是「聚拢」。"},{"en":"Fixed phrases mark the use: compile a dictionary, compile a list, compile source code.","cn":"固定搭配标出用法：编纂词典、编制清单、编译源代码。"},{"en":"An anthology is a compiled book, chosen and arranged.","cn":"选集就是编成的书，经过挑选与编排。"}],"abstract":[{"en":"Compile is a table covered with loose pages, finally sorted into one binder.","cn":"汇编是一张摊满散页的桌子，最后被理进同一只夹子。"},{"en":"The act is half gathering and half order; without the second half it is only a pile.","cn":"这项行为一半是收集，一半是编排；少了后一半，就只是一堆。"},{"en":"A compiler translates a human arrangement into a machine's arrangement.","cn":"编译器把人的编排翻译成机器的编排。"}]},"examples":[{"en":"The archivist compiled the letters by year and by sender.","cn":"档案员按年份与寄信人汇编这些信件。"},{"en":"The program compiles the whole project in under a second.","cn":"这个程序在一秒之内编译整个项目。"},{"en":"She compiled a short list of the books worth keeping.","cn":"她编了一份值得保留的短书单。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「肯派尔」——把一堆散页肯（肯）定派进同一册：汇编","word":"compile"},"root":"拉丁 compilare「聚拢、堆起」，也可能带「掠夺」义 ← com-「一起」+ pilare（与压、拔相关，此复合词中取义来源不确定）。古法语 compiler 把义收窄到文字汇集；英语中世纪晚期借入，确切首见年代不确定。同族 compilation、compiler；comply 形近但出自 complere「填满」。二十世纪五十年代起又指源代码编译。","sensesIntro":{"en":"Eight senses gather writings, list items, assemble data, translate code, collect evidence, build indexes, draft reports and choose an anthology.","cn":"八个义项分别汇集文字、列清单、汇总数据、编译代码、汇集证据、编索引、写报告与编选集。"},"semanticMap":{"core":{"en":"CORE IMAGE: loose pages gathered from a table into one hard binder.","cn":"核心意象：散页从桌面上被收进同一只硬壳夹。"},"chain":["GATHER","PLUNDER","COLLECT WRITINGS","MAKE A BOOK","ASSEMBLE DATA","TRANSLATE CODE"],"branches":[{"senses":"01 · 08","en":"THE FINISHED VOLUME: scattered writings made into a book and chosen pieces made into an anthology.","cn":"成书：散落文字编成书，挑选篇目编成选集。"},{"senses":"02 · 06","en":"THE FINDING FORM: an ordered list and an index built to be searched.","cn":"检索形态：按序的清单与供查找的索引。"},{"senses":"03 · 05","en":"THE GATHERED MATERIAL: figures from many sources and records for an argument.","cn":"汇集的材料：多处数字与供论证的记录。"},{"senses":"04","en":"THE MACHINE TRANSLATION: source code turned into instructions.","cn":"机器翻译：源代码转成指令。"},{"senses":"07","en":"THE WRITTEN ACCOUNT: gathered facts set down as a report.","cn":"成文的叙述：汇集的事实写成报告。"}]},"affixes":{"intro":{"en":"Compile is the Latin verb compilare with English noun and agent forms; com- is clear and the other element is disputed.","cn":"compile 是拉丁动词 compilare 加英语名词与施动形式；com- 清楚，另一成分有争议。"},"latinIntro":{"en":"Com- supplies the gathering, pilare supplies the disputed action, and compilatio supplies the noun.","cn":"com- 提供「聚拢」，pilare 提供有争议的动作，compilatio 提供名词。"},"items":[{"word":"com-","structure":"Latin prefix","meaning":"together; with","meaningCN":"一起；共同","example":"The prefix brings scattered things into one place.","exampleCN":"前缀把散落之物带到一处。"},{"word":"pilare","structure":"Latin verb of uncertain sense","meaning":"to press; to pluck","meaningCN":"压；拔","example":"The element is the disputed part of the compound.","exampleCN":"这一成分是复合词中有争议的部分。"},{"word":"compilare","structure":"Latin verb","meaning":"to gather; to heap up","meaningCN":"聚拢；堆起","example":"The verb already carried both collection and seizure.","exampleCN":"这个动词已兼有收集与夺取。"},{"word":"compilatio","structure":"Latin noun from compilare","meaning":"a gathering; a compilation","meaningCN":"汇集；汇编","example":"The noun names the finished gathering.","exampleCN":"名词命名完成的汇集。"},{"word":"compiler","structure":"French verb then English noun","meaning":"to gather writings; one who gathers","meaningCN":"汇集文字；汇集者","example":"French narrowed the verb to writings before English took it.","exampleCN":"法语先把动词收窄到文字，再传给英语。"},{"word":"compile","structure":"English verb","meaning":"to gather into one work","meaningCN":"编成一部作品","example":"English keeps the book-making sense at the centre.","exampleCN":"英语把制书义留在中心。"},{"word":"compilation","structure":"English noun","meaning":"a collected work","meaningCN":"汇编作品","example":"The noun can name the book or the act.","exampleCN":"名词既可指书，也可指行为。"},{"word":"compiled","structure":"English participle","meaning":"gathered together","meaningCN":"被汇编的","example":"The participle marks the finished state.","exampleCN":"分词标记完成状态。"},{"word":"compiler program","structure":"English technical compound","meaning":"a translator of source code","meaningCN":"编译器程序","example":"Computing reused the agent word for a machine.","exampleCN":"计算技术把施动名词复用给了机器。"},{"word":"-ation","structure":"Latin noun suffix","meaning":"act or result","meaningCN":"行为或结果","example":"It also builds compilation, foundation and creation.","exampleCN":"它也构成 compilation、foundation 与 creation。"}],"latinEntries":[{"word":"compilare","structure":"compilare, compilavi, compilatum (v., first conjugation)","meaning":"to gather together; to heap up","meaningCN":"聚拢；堆起"},{"word":"compilatio","structure":"compilatio, compilationis (n., third declension)","meaning":"a gathering; compilation","meaningCN":"汇集；汇编"}],"derivatives":[{"word":"compilation","pos":"n.","zh":"编纂；汇编；编译产物"},{"word":"compiler","pos":"n.","zh":"编纂者；编译器"},{"word":"compiled","pos":"adj.","zh":"汇编的；编译的"},{"word":"compilable","pos":"adj.","zh":"可编译的"}]}},{"word":"complement","ipa_uk":"/ˈkɒmplɪment/","ipa_us":"/ˈkɑːmpləment/","definition_zh":"补充物；补足；配套；（语法）补语；（数学）补集；（生物）补体","definition_en":"something that completes another thing or makes it whole; to complete by adding what is missing","core_image":"一片拼图正好补进缺口，边线严丝合缝","scene":"餐桌上的深色桌布衬得浅色餐具更亮。The cool sauce is a complement to the rich meat.","sceneCN":"这里指补足他物、使其完整的东西（第 1 个义项：补足物）；句意为这清爽的酱汁与厚重的肉相配，正好补足。","pos":[{"tag":"n.","zh":"补充物；补足物；配套物；补语；补集；补体"},{"tag":"v.","zh":"补充；补足；与…相配"}],"collocations":[{"phrase":"a complement to","zh":"对…的补充"},{"phrase":"full complement","zh":"全额编制；整套"},{"phrase":"complement each other","zh":"相互补足"},{"phrase":"complement system","zh":"补体系统"},{"phrase":"complementary colours","zh":"互补色"},{"phrase":"subject complement","zh":"主语补足语"}],"forms":[{"label":"名词单数","form":"complement"},{"label":"名词复数","form":"complements"},{"label":"动词原形","form":"complement"},{"label":"第三人称单数","form":"complements"},{"label":"过去式","form":"complemented"},{"label":"过去分词","form":"complemented"},{"label":"现在分词","form":"complementing"}],"derivatives":[{"word":"complementary","pos":"adj.","zh":"互补的；补充的"},{"word":"complementation","pos":"n.","zh":"补足；互补"},{"word":"complemented","pos":"adj.","zh":"有补足的"},{"word":"complementarity","pos":"n.","zh":"互补性"}],"senses":[{"no":"01","title":"Something that completes another thing","titleCN":"使另一物完整的东西","definition":"a thing that supplies what another thing lacks","definitionCN":"补上另一物所缺之物的东西","example":"The cool sauce is a complement to the rich meat.","exampleCN":"这清爽的酱汁与厚重的肉相配。","why":"Complementum is that which fills up, from complere, to fill completely.","whyCN":"complementum 指把东西填满的部分，出自 complere「完全填满」。"},{"no":"02","title":"To complete by adding","titleCN":"补足使完整","definition":"to add what is needed to make something whole","definitionCN":"加上所需之物使某事物完整","example":"The two parts complement each other.","exampleCN":"这两部分相互补足。","why":"The verb turns the filling into an act performed by one thing on another.","whyCN":"动词把「填满」变成一物对另一物施行的动作。"},{"no":"03","title":"A matched set","titleCN":"配套的一组","definition":"the full number needed for a set or a ship's crew","definitionCN":"一个组合或一艘船所需的全额人数","example":"The ship sailed with its full complement of crew.","exampleCN":"这艘船载着全额船员出海。","why":"A set is complete when its count is filled, and the word marks that count.","whyCN":"一个组合在人数填满时才算完整，这个词标记那个数额。"},{"no":"04","title":"A grammatical complement","titleCN":"语法上的补语","definition":"a word or phrase that completes the meaning of a verb or subject","definitionCN":"补足动词或主语意义的词或短语","example":"In the sentence she is a doctor, the noun is a complement.","exampleCN":"在「她是一名医生」这句话里，那个名词是补语。","why":"Grammar borrowed the filling image for the part that makes a clause whole.","whyCN":"语法学借「填充」意象，指使从句完整的部分。"},{"no":"05","title":"A mathematical complement","titleCN":"数学上的补集","definition":"the set of elements not in a given set","definitionCN":"不属于某集合的元素所成的集合","example":"The complement of the odd numbers is the even numbers.","exampleCN":"奇数的补集是偶数。","why":"Set theory asks what is left when a part is taken away, and calls it the filling of the rest.","whyCN":"集合论问取走一部分后剩下什么，并把剩余称为补。"},{"no":"06","title":"A part of the immune system","titleCN":"免疫系统的补体","definition":"a group of proteins that help antibodies destroy pathogens","definitionCN":"协助抗体消灭病原体的一组蛋白","example":"The complement system marks the bacterium for destruction.","exampleCN":"补体系统给细菌做上待清除的标记。","why":"The name was given because the proteins complete the work of antibodies.","whyCN":"得名是因为这些蛋白完成抗体的工作。"},{"no":"07","title":"A colour opposite","titleCN":"互补的颜色","definition":"a colour that sits opposite another on the colour wheel","definitionCN":"色轮上与另一色相对的颜色","example":"Blue and orange are complementary colours.","exampleCN":"蓝与橙是互补色。","why":"Two opposites complete a neutral balance, so the word fits the pair.","whyCN":"两个相反色合成中性平衡，因此这个词适用于这一对。"},{"no":"08","title":"A logical complement","titleCN":"逻辑上的补","definition":"the negation or remainder of a proposition or class","definitionCN":"命题或类别的否定或剩余","example":"The complement of the claim covers every other case.","exampleCN":"这一说法的补覆盖其余所有情况。","why":"Logic uses the word for whatever the first statement leaves outside it.","whyCN":"逻辑学用这个词指第一个陈述留在其外的一切。"}],"etymology":{"intro":{"en":"Complement comes from Latin complementum, that which fills up, from complere, to fill completely, built on com- together and plere, to fill. The direct source is clear.","cn":"complement 来自拉丁 complementum「用来填满之物」，出自 complere「完全填满」，由 com-「一起」与 plere「填」构成。直接来源清楚。"},"items":[{"era":"LATIN PLERE","en":"Plere meant to fill, and it also lies behind complete, supply and plenty.","cn":"plere 意为填满，也藏在 complete、supply 与 plenty 背后。"},{"era":"COMPLERE","en":"Complere joined com- together with plere, giving the sense of filling something to the full.","cn":"complere 把 com-「一起」与 plere 结合，给出「填到满」的意思。"},{"era":"COMPLEMENTUM","en":"Complementum was the part that did the filling, the thing needed to make a whole.","cn":"complementum 指完成填充的那部分，即使整体成立所需之物。"},{"era":"FRENCH AND ENGLISH","en":"French passed the word to English; the exact first English date is uncertain.","cn":"法语把这个词传给英语，英语确切首见年代不确定。"},{"era":"COMPLIMENT","en":"Compliment reached English through French and Italian courtesy, and though both lines end at complere, the two words separated early.","cn":"compliment 经法语与意大利语的礼节用法进入英语；两条线虽都止于 complere，词却很早分道。"},{"era":"TECHNICAL SENSES","en":"Grammar, set theory, immunology and colour theory each name their missing piece a complement.","cn":"语法、集合论、免疫学与色彩理论都把自己缺的那一块叫作补。"}]},"similar":{"note":{"en":"The first group shares the Latin filling stem; the second group names things that complete or go well with another.","cn":"第一组共享拉丁语「填满」词干；第二组是补足或相配的近义说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"compliment","ipa":"/kəmˈplɪment/","tag":"near form","definition":"Praise or a polite remark; a different word despite the closeness.","definitionCN":"称赞或礼貌用语；虽形近却是另一个词。"},{"word":"complementary","ipa":"/ˌkɒmplɪˈmentri/","tag":"same root","definition":"Serving to complete or balance another thing.","definitionCN":"起补足或平衡另一物作用的。"},{"word":"complementation","ipa":"/ˌkɒmplɪmenˈteɪʃn/","tag":"same root","definition":"The act or process of completing.","definitionCN":"补足的行为或过程。"},{"word":"complete","ipa":"/kəmˈpliːt/","tag":"same root","definition":"Whole, with nothing missing; from the same filling verb.","definitionCN":"完整的，什么都不缺；出自同一「填满」动词。"},{"word":"supply","ipa":"/səˈplaɪ/","tag":"same root","definition":"To provide what is needed; from supplere, to fill up.","definitionCN":"提供所需之物；出自 supplere「填满」。"}]},{"heading":"NEAR MEANING","entries":[{"word":"supplement","ipa":"/ˈsʌplɪment/","tag":"near meaning","definition":"Something added to improve or extend, not to complete.","definitionCN":"为改进或延长而添加之物，不是为补全。"},{"word":"counterpart","ipa":"/ˈkaʊntəpɑːt/","tag":"near meaning","definition":"A person or thing matching another in role.","definitionCN":"在角色上与他者对应的人或物。"},{"word":"addition","ipa":"/əˈdɪʃn/","tag":"near meaning","definition":"Something put in beside what is already there.","definitionCN":"放到已有之物旁边的东西。"},{"word":"match","ipa":"/mætʃ/","tag":"near meaning","definition":"One of a pair that goes well with the other.","definitionCN":"与另一件相配的一件。"},{"word":"balance","ipa":"/ˈbæləns/","tag":"near meaning","definition":"An even arrangement of opposite parts.","definitionCN":"相反部分之间的均衡安排。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real Latin filling verb, the real family and real collocations.","cn":"正常联想使用真实的拉丁「填满」动词、真实同族词与真实搭配。"},"normal":[{"en":"Complere is to fill completely, so a complement is the piece that fills the gap.","cn":"complere 是完全填满，所以 complement 就是填缺口的那一块。"},{"en":"Complement completes; supplement adds without necessarily completing.","cn":"complement 补全；supplement 添加，却未必补全。"},{"en":"Compliment is praise, not completion, even though the two words look alike.","cn":"compliment 是称赞，不是补全，尽管两个词长得像。"},{"en":"Fixed phrases mark the use: a complement to, full complement, complement each other.","cn":"固定搭配标出用法：对…的补充、全额编制、相互补足。"},{"en":"Set theory and immunology both name their missing piece a complement.","cn":"集合论与免疫学都把自己缺的那一块叫补。"}],"abstract":[{"en":"Complement is a puzzle piece whose edge fits exactly, making the picture whole.","cn":"补充是一块边线正吻合的拼图，让画面完整。"},{"en":"The word does not add more of the same; it adds what was missing.","cn":"这个词不是添加同类的更多，而是添加缺少的那一种。"},{"en":"Two opposite colours complete each other into grey.","cn":"两种相反色相互补足成灰。"}]},"examples":[{"en":"The two sisters have complementary talents but very different habits.","cn":"两姐妹才能互补，习惯却大不相同。"},{"en":"A full complement of officers reported for duty.","cn":"全额军官报到履职。"},{"en":"The wine complements the cheese without overpowering it.","cn":"这款酒与奶酪相配，却不压过它。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「康普力门特」——把缺的那块补齐：补充；补足物","word":"complement"},"root":"拉丁 complementum「用来填满之物」← complere「完全填满」← com-「一起」+ plere「填」。同族 complete、supply 同出 plere；compliment 经法语与意大利语礼节用法另成一路，虽同止于 complere 但很早分道。法语传入英语，确切首见年代不确定；语法、集合论、免疫学与色彩理论各有专义。","sensesIntro":{"en":"Eight senses fill a gap in table, theory, grammar, sets, immunity, colour, logic and a taste.","cn":"八个义项在餐桌、理论、语法、集合、免疫、色彩、逻辑与口味上填补缺口。"},"semanticMap":{"core":{"en":"CORE IMAGE: a puzzle piece whose edge fits exactly, leaving no gap.","cn":"核心意象：一块边线严丝合缝的拼图，不留缺口。"},"chain":["FILL","FILL UP","COMPLETE","MATCHED SET","GRAMMATICAL PART","BALANCED WHOLE"],"branches":[{"senses":"01 · 02","en":"THE FILLING PIECE: the thing supplied and the act of supplying it.","cn":"填充的那块：被补上的东西与补上的动作。"},{"senses":"03","en":"THE FULL COUNT: a set or crew brought to its required number.","cn":"全额：组合或船员达到所需人数。"},{"senses":"04 · 08","en":"THE CLAUSE AND THE PROPOSITION: what completes a sentence and what the first claim leaves outside itself.","cn":"从句与命题：使句子完整的部分，以及首个陈述留在其外的东西。"},{"senses":"05","en":"THE SET REMAINDER: everything not in a given set.","cn":"集合的剩余：不在给定集合中的一切。"},{"senses":"06 · 07","en":"THE BALANCED PAIR: proteins completing antibodies and colours completing each other.","cn":"平衡的一对：完成抗体工作的蛋白与彼此补足的两种颜色。"}]},"affixes":{"intro":{"en":"Complement is the Latin filling noun and verb; plere is the core and com- adds the togetherness.","cn":"complement 是拉丁语「填满」的名词与动词；plere 是核心，com- 加上「一起」。"},"latinIntro":{"en":"Plere supplies the fill, complementum the thing that fills, and complere the act; compliment is a separate courtesy line.","cn":"plere 提供「填」，complementum 提供填充之物，complere 提供动作；compliment 是另一条礼节线。"},"items":[{"word":"com-","structure":"Latin prefix","meaning":"together; wholly","meaningCN":"一起；完全","example":"The prefix makes the filling complete rather than partial.","exampleCN":"前缀使填充完全，而不是部分。"},{"word":"plere","structure":"Latin verb","meaning":"to fill","meaningCN":"填满","example":"The verb is the core of the whole family.","exampleCN":"这个动词是整个词族的核心。"},{"word":"complere","structure":"Latin verb from com- and plere","meaning":"to fill up; to complete","meaningCN":"填满；完成","example":"The compound adds the sense of reaching fullness.","exampleCN":"复合词加上「达到满」的意思。"},{"word":"complementum","structure":"Latin noun from complere","meaning":"that which fills up","meaningCN":"用来填满之物","example":"The noun names the missing piece.","exampleCN":"名词命名缺失的那一块。"},{"word":"complement","structure":"English noun and verb","meaning":"a completing part; to complete","meaningCN":"补足物；补足","example":"English keeps both the thing and the act.","exampleCN":"英语同时保留物与动作。"},{"word":"complementary","structure":"English adjective","meaning":"completing another","meaningCN":"互补的","example":"The adjective describes the relation between two parts.","exampleCN":"形容词描述两部分之间的关系。"},{"word":"complementation","structure":"English noun","meaning":"the act of completing","meaningCN":"补足的行为","example":"The noun belongs to grammar and biology.","exampleCN":"名词用于语法与生物学。"},{"word":"complete","structure":"English adjective and verb","meaning":"whole; to finish","meaningCN":"完整的；完成","example":"The same filling verb gives the everyday word.","exampleCN":"同一「填满」动词给出日常词。"},{"word":"supplement","structure":"English noun and verb","meaning":"an addition to improve or extend","meaningCN":"增补之物","example":"The word adds rather than completes.","exampleCN":"这个词是添加，而非补全。"},{"word":"-ment","structure":"Latin noun suffix","meaning":"result or means","meaningCN":"结果或手段","example":"The suffix turns the verb into the filling thing.","exampleCN":"后缀把动词变成填充之物。"}],"latinEntries":[{"word":"plere","structure":"plere, plevi, pletum (v., second conjugation)","meaning":"to fill","meaningCN":"填满"},{"word":"complere","structure":"complere, complevi, completum (v., second conjugation)","meaning":"to fill up; to complete","meaningCN":"填满；完成"},{"word":"complementum","structure":"complementum, complementi (n., second declension)","meaning":"that which fills up","meaningCN":"用来填满之物"}],"derivatives":[{"word":"complementary","pos":"adj.","zh":"互补的；补充的"},{"word":"complementation","pos":"n.","zh":"补足；互补"},{"word":"complementarity","pos":"n.","zh":"互补性"},{"word":"complemented","pos":"adj.","zh":"有补足的"}]}},{"word":"conceal","ipa_uk":"/kənˈsiːl/","ipa_us":"/kənˈsiːl/","definition_zh":"隐藏；隐瞒；掩饰；遮盖","definition_en":"to keep something from being seen or known","core_image":"一个大衣口袋里塞着一只没拆封的信","scene":"有人把账本塞进柜子最下层，用旧布盖上。He tried to conceal the loss from his partners.","sceneCN":"这里指把事实藏起来不让人知道（第 2 个义项：隐瞒事实）；句意是他试图向合伙人隐瞒这笔亏损。","pos":[{"tag":"v.","zh":"隐藏；隐瞒；掩饰；遮盖"}],"collocations":[{"phrase":"conceal the truth","zh":"隐瞒真相"},{"phrase":"conceal evidence","zh":"隐匿证据"},{"phrase":"conceal one's feelings","zh":"掩饰情绪"},{"phrase":"conceal a weapon","zh":"藏匿武器"},{"phrase":"conceal flaws","zh":"遮掩缺陷"},{"phrase":"conceal oneself","zh":"藏身"}],"forms":[{"label":"原形","form":"conceal"},{"label":"第三人称单数","form":"conceals"},{"label":"过去式","form":"concealed"},{"label":"过去分词","form":"concealed"},{"label":"现在分词","form":"concealing"},{"label":"名词","form":"concealment"},{"label":"形容词","form":"concealed"}],"derivatives":[{"word":"concealment","pos":"n.","zh":"隐藏；隐瞒；隐匿处"},{"word":"concealed","pos":"adj.","zh":"隐藏的；暗藏的"},{"word":"concealer","pos":"n.","zh":"遮瑕膏；隐匿者"},{"word":"concealable","pos":"adj.","zh":"可隐藏的"}],"senses":[{"no":"01","title":"To hide an object from view","titleCN":"把物件藏起来","definition":"to put something where it cannot be seen","definitionCN":"把某物放到看不见的地方","example":"He concealed the key under a loose floorboard.","exampleCN":"他把钥匙藏在一块松动的地板下。","why":"Latin concelare joined com- with celare, to hide, and the physical act came first.","whyCN":"拉丁 concelare 把 com- 与 celare「隐藏」结合，具体动作最先出现。"},{"no":"02","title":"To keep a fact secret","titleCN":"隐瞒事实","definition":"to prevent a fact from becoming known","definitionCN":"不让某一事实被人知道","example":"He tried to conceal the loss from his partners.","exampleCN":"他试图向合伙人隐瞒这笔亏损。","why":"The hidden object becomes a hidden fact, and the verb follows without changing form.","whyCN":"被藏的物件变成被藏的事实，动词形态不变地跟过去。"},{"no":"03","title":"To mask a feeling","titleCN":"掩饰情绪","definition":"to keep an emotion from showing","definitionCN":"不让某种情绪外露","example":"She concealed her disappointment behind a smile.","exampleCN":"她用微笑掩饰失望。","why":"The face becomes the surface where something is covered over.","whyCN":"脸变成被盖住某物的那个表面。"},{"no":"04","title":"To hide oneself","titleCN":"藏身","definition":"to stay where one cannot be found","definitionCN":"待在找不到自己的地方","example":"The child concealed herself behind the curtain.","exampleCN":"孩子把自己藏在窗帘后面。","why":"The verb turns from object to person without losing the covering idea.","whyCN":"动词从物件转到人，仍未丢掉「遮盖」的观念。"},{"no":"05","title":"To hide evidence","titleCN":"隐匿证据","definition":"to keep proof out of sight or out of reach","definitionCN":"把证据藏到看不见或拿不到的地方","example":"The files were concealed in a locked drawer.","exampleCN":"这些文件被藏在上了锁的抽屉里。","why":"Law treats concealment as an act with its own consequences.","whyCN":"法律把隐匿视为一种自带后果的行为。"},{"no":"06","title":"To hide a weapon","titleCN":"藏匿武器","definition":"to keep a weapon where it is not visible","definitionCN":"把武器放在看不见的地方","example":"The guard concealed a knife in his boot.","exampleCN":"守卫把刀藏进靴子里。","why":"The physical hiding is precise here, with no mental extension.","whyCN":"这里只指具体的藏，没有心理引申。"},{"no":"07","title":"To mask an intention","titleCN":"掩盖意图","definition":"to keep a plan or motive from being guessed","definitionCN":"不让人猜出计划或动机","example":"He concealed his intention until the last vote.","exampleCN":"直到最后一轮投票，他才不再掩盖自己的意图。","why":"Intentions are invisible already; concealment adds a second layer of cover.","whyCN":"意图本来看不见，掩盖等于再加上一层覆盖。"},{"no":"08","title":"To cover a defect","titleCN":"遮掩缺陷","definition":"to keep a flaw from being noticed","definitionCN":"不让人注意到缺陷","example":"The paint concealed the cracks in the wall.","exampleCN":"涂料遮住了墙上的裂缝。","why":"The word can hide a fault, not only a treasure.","whyCN":"这个词能藏起珍宝，也能藏起毛病。"}],"etymology":{"intro":{"en":"Conceal comes from Latin concelare, to hide, from com- plus celare, to hide or keep secret. The direct source is clear, and celare is connected with the root behind cell and cellar.","cn":"conceal 来自拉丁 concelare「隐藏」，由 com- 与 celare「隐藏、保密」构成。直接来源清楚，celare 与 cell、cellar 背后的词根相关。"},"items":[{"era":"LATIN CELARE","en":"Celare meant to hide or keep secret, and the same root gives cell and cellar, the enclosed places.","cn":"celare 意为隐藏或保密，同一词根给出 cell 与 cellar，即被围起来的地方。"},{"era":"THE PREFIX COM-","en":"Com- here strengthens the verb rather than adding a literal together.","cn":"这里的 com- 起加强作用，而非字面「一起」。"},{"era":"CONCELARE","en":"Concelare meant to cover something over so that it is out of sight.","cn":"concelare 意为把某物盖住，使其离开视线。"},{"era":"OLD FRENCH CONCELER","en":"Old French conceler carried the verb to English.","cn":"古法语 conceler 把这个动词带到英语。"},{"era":"ENGLISH CONCEAL","en":"Conceal appears in the late Middle Ages; the exact first date is uncertain.","cn":"conceal 在中世纪晚期出现，确切首见年代不确定。"},{"era":"CONCEALMENT","en":"The noun concealment names both the act and the state of being hidden.","cn":"名词 concealment 既命名行为，也命名被隐藏的状态。"}]},"similar":{"note":{"en":"The first group shares the Latin hide-stem; the second group names hiding and disguising. Confine is a different word and must not be merged with this one.","cn":"第一组共享拉丁语「隐藏」词干；第二组是藏匿与掩饰的近义说法。confine 是另一个词，不能与它混为一谈。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"concealment","ipa":"/kənˈsiːlmənt/","tag":"same root","definition":"The act or state of being hidden.","definitionCN":"隐藏的行为或状态。"},{"word":"concealed","ipa":"/kənˈsiːld/","tag":"same root","definition":"Hidden from sight; the adjective from the participle.","definitionCN":"看不见的；由分词而来的形容词。"},{"word":"concealer","ipa":"/kənˈsiːlə(r)/","tag":"same root","definition":"A cosmetic that covers marks, or one who hides.","definitionCN":"遮盖痕迹的化妆品，或隐藏者。"},{"word":"confine","ipa":"/kənˈfaɪn/","tag":"different root","definition":"To keep within limits; from finis, a boundary, and unrelated in root to conceal.","definitionCN":"限制在范围内；出自 finis「边界」，词根与 conceal 无关。"},{"word":"council","ipa":"/ˈkaʊnsl/","tag":"different root","definition":"An assembly; from Latin concilium, not from celare.","definitionCN":"议事机构；出自拉丁 concilium，与 celare 无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"hide","ipa":"/haɪd/","tag":"near meaning","definition":"To put or keep out of sight; the plain English word.","definitionCN":"使不被看见；最平实的英语说法。"},{"word":"disguise","ipa":"/dɪsˈɡaɪz/","tag":"near meaning","definition":"To change appearance so as not to be recognised.","definitionCN":"改变外表使不被认出。"},{"word":"mask","ipa":"/mɑːsk/","tag":"near meaning","definition":"To cover so that the true thing is not noticed.","definitionCN":"覆盖住，使真相不被注意。"},{"word":"cover up","ipa":"/ˈkʌvə ʌp/","tag":"near meaning","definition":"To keep wrongdoing from being discovered.","definitionCN":"不让不当行为被发现。"},{"word":"withhold","ipa":"/wɪðˈhəʊld/","tag":"near meaning","definition":"To refuse to give information or a thing.","definitionCN":"拒绝提供信息或物品。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real Latin hide verb, the real family and real collocations.","cn":"正常联想使用真实的拉丁「隐藏」动词、真实同族词与真实搭配。"},"normal":[{"en":"Celare is to hide, and cell and cellar are the enclosed places from the same root.","cn":"celare 是隐藏，cell 与 cellar 则是同一词根下的围合之地。"},{"en":"Concealment is the noun for both the act and the state.","cn":"concealment 这个名词兼指行为与状态。"},{"en":"You conceal an object, a fact, a feeling, a weapon or a defect.","cn":"可以藏物件、瞒事实、掩情绪、匿武器、遮缺陷。"},{"en":"Confine is built on a boundary, not on hiding, so the two words are not synonyms.","cn":"confine 建在「边界」上，不在「隐藏」上，两者不是同义词。"},{"en":"Fixed phrases mark the use: conceal the truth, conceal evidence, conceal one's feelings.","cn":"固定搭配标出用法：隐瞒真相、隐匿证据、掩饰情绪。"}],"abstract":[{"en":"Conceal is a letter folded into a coat pocket, its edge never showing.","cn":"隐藏是一封折进大衣口袋的信，边角从不露出来。"},{"en":"What is concealed is still there; only the view has been taken away.","cn":"被藏起的东西仍在，只是视线被拿走了。"},{"en":"A hidden intention is covered twice, once by the mind and once by the act.","cn":"被掩盖的意图被盖了两次，一次是心思本身，一次是动作。"}]},"examples":[{"en":"The thick branches concealed the road from above.","cn":"浓密的树枝从上方遮住了道路。"},{"en":"She concealed the letter inside a book of maps.","cn":"她把信藏在一本地图册里。"},{"en":"No one can conceal a change of tone for long.","cn":"没有人能长久掩饰语气的变化。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「肯吸尔」——把东西吸进暗处：隐藏","word":"conceal"},"root":"拉丁 concelare「隐藏」← com-（加强）+ celare「隐藏、保密」；同一词根给出 cell 与 cellar 这些围合之处。古法语 conceler 传入英语，中世纪晚期出现，确切首见年代不确定；名词 concealment 兼指行为与状态。confine 出自 finis「边界」，与 conceal 不同源，也不是同义词。","sensesIntro":{"en":"Eight senses hide an object, a fact, a feeling, a person, evidence, a weapon, an intention and a defect.","cn":"八个义项分别藏起物件、事实、情绪、人、证据、武器、意图与缺陷。"},"semanticMap":{"core":{"en":"CORE IMAGE: an unopened letter stuffed into a coat pocket.","cn":"核心意象：一封未拆的信被塞进大衣口袋。"},"chain":["HIDE","KEEP SECRET","OUT OF SIGHT","MASK FEELING","HIDE EVIDENCE","COVER A FAULT"],"branches":[{"senses":"01 · 04 · 06","en":"THE PHYSICAL HIDING: an object, a person and a weapon put where they cannot be seen.","cn":"具体的藏：把物件、人或武器放到看不见的地方。"},{"senses":"02 · 05","en":"THE SECRET FACT: a loss kept from partners and evidence kept from law.","cn":"被瞒的事实：瞒着合伙人的亏损与瞒着法律的证据。"},{"senses":"03","en":"THE MASKED FEELING: disappointment behind a smile.","cn":"被掩饰的情绪：微笑背后的失望。"},{"senses":"07","en":"THE COVERED INTENTION: a plan kept from being guessed.","cn":"被盖住的意图：不让人猜出的计划。"},{"senses":"08","en":"THE HIDDEN DEFECT: cracks under a coat of paint.","cn":"被遮住的缺陷：涂料下的裂缝。"}]},"affixes":{"intro":{"en":"Conceal is the Latin hide verb with English noun and participle forms; celare supplies the root and com- strengthens it.","cn":"conceal 是拉丁「隐藏」动词加英语名词与分词形式；celare 提供词根，com- 起加强作用。"},"latinIntro":{"en":"Celare gives the hiding, concelare the compound verb, and concealment the abstract noun.","cn":"celare 提供「隐藏」，concelare 提供复合动词，concealment 提供抽象名词。"},"items":[{"word":"celare","structure":"Latin verb, first conjugation","meaning":"to hide; to keep secret","meaningCN":"隐藏；保密","example":"The verb is the root of the whole family.","exampleCN":"这个动词是整个词族的根。"},{"word":"com-","structure":"Latin intensive prefix","meaning":"wholly; strongly","meaningCN":"完全；强力","example":"Here the prefix strengthens rather than meaning together.","exampleCN":"这里前缀表加强，而非「一起」。"},{"word":"concelare","structure":"Latin verb","meaning":"to cover over; to hide","meaningCN":"盖住；隐藏","example":"The compound names the completed hiding.","exampleCN":"复合词命名完成的隐藏。"},{"word":"conceal","structure":"English verb from Old French","meaning":"to hide from sight or knowledge","meaningCN":"隐藏；隐瞒","example":"English keeps the verb without the Latin prefix form.","exampleCN":"英语保留了动词，却未保留拉丁前缀形态。"},{"word":"concealment","structure":"English noun","meaning":"the act or state of hiding","meaningCN":"隐藏的行为或状态","example":"The noun covers both action and condition.","exampleCN":"名词兼指行为与状态。"},{"word":"concealed","structure":"English participle and adjective","meaning":"hidden","meaningCN":"隐藏的","example":"The participle marks what has been covered.","exampleCN":"分词标记被盖住的东西。"},{"word":"concealer","structure":"English agent noun","meaning":"one who hides, or a covering cosmetic","meaningCN":"隐藏者；遮瑕膏","example":"The agent suffix names person or product.","exampleCN":"施动后缀命名人或产品。"},{"word":"cell","structure":"Latin cella","meaning":"a small room","meaningCN":"小室","example":"The same root names an enclosed place.","exampleCN":"同一词根命名围合之地。"},{"word":"cellar","structure":"Latin cellarium","meaning":"a storeroom","meaningCN":"地窖；储藏室","example":"The family keeps the idea of a covered store.","exampleCN":"词族保留「盖起来的储藏处」这一观念。"},{"word":"occult","structure":"Latin occultus, hidden","meaning":"hidden; secret","meaningCN":"隐秘的","example":"The same hiding root gives a learned adjective.","exampleCN":"同一「隐藏」词根给出一个学术形容词。"}],"latinEntries":[{"word":"celare","structure":"celare, celavi, celatum (v., first conjugation)","meaning":"to hide; to keep secret","meaningCN":"隐藏；保密"},{"word":"concelare","structure":"concelare, concelavi, concelatum (v., first conjugation)","meaning":"to hide; to cover","meaningCN":"隐藏；遮盖"},{"word":"cella","structure":"cella, cellae (n., first declension)","meaning":"a small room; store","meaningCN":"小室；储藏处"}],"derivatives":[{"word":"concealment","pos":"n.","zh":"隐藏；隐瞒；隐匿处"},{"word":"concealed","pos":"adj.","zh":"隐藏的；暗藏的"},{"word":"concealer","pos":"n.","zh":"遮瑕膏；隐匿者"},{"word":"concealable","pos":"adj.","zh":"可隐藏的"}]}},{"word":"conceive","ipa_uk":"/kənˈsiːv/","ipa_us":"/kənˈsiːv/","definition_zh":"构想；设想；理解；认为；怀孕","definition_en":"to form an idea or plan in the mind; to become pregnant; to understand","core_image":"灯下图纸上先出现一个只有轮廓的圆","scene":"设计会上没人说话，她在纸上画出一个谁也想不到的结构。She conceived a bridge that could be built without closing the road.","sceneCN":"这里指在脑中形成新的方案（第 1 个义项：构想、构思）；句意是她构想出一座不用封路就能建的桥。","pos":[{"tag":"v.","zh":"构想；设想；理解；认为；怀孕"}],"collocations":[{"phrase":"conceive a plan","zh":"构想一个方案"},{"phrase":"conceive of","zh":"设想；想象"},{"phrase":"conceive a child","zh":"怀孕"},{"phrase":"conceive an idea","zh":"形成一个想法"},{"phrase":"hard to conceive","zh":"难以想象"},{"phrase":"conceive of as","zh":"把…视为"}],"forms":[{"label":"原形","form":"conceive"},{"label":"第三人称单数","form":"conceives"},{"label":"过去式","form":"conceived"},{"label":"过去分词","form":"conceived"},{"label":"现在分词","form":"conceiving"},{"label":"名词","form":"conception"},{"label":"形容词","form":"conceivable"},{"label":"否定形容词","form":"inconceivable"}],"derivatives":[{"word":"conception","pos":"n.","zh":"构想；概念；受孕"},{"word":"conceivable","pos":"adj.","zh":"可想象的；可能的"},{"word":"inconceivable","pos":"adj.","zh":"难以想象的"},{"word":"conceptive","pos":"adj.","zh":"有构想力的"}],"senses":[{"no":"01","title":"To form a new idea or plan","titleCN":"构想新想法或方案","definition":"to bring a new idea or design into the mind","definitionCN":"在脑中形成新的想法或设计","example":"She conceived a bridge that could be built without closing the road.","exampleCN":"她构想出一座不用封路就能建的桥。","why":"Latin concipere meant to take in, and the mind was seen as receiving and holding a seed of an idea.","whyCN":"拉丁 concipere 意为「纳入」，心智被看作接受并孕育一粒想法的种子。"},{"no":"02","title":"To imagine a possibility","titleCN":"设想一种可能","definition":"to picture something that might exist or happen","definitionCN":"想象可能存在或发生的事物","example":"I cannot conceive of a city without a river.","exampleCN":"我无法想象一座没有河的城市。","why":"The word allows the mind to hold what the senses have never met.","whyCN":"这个词让心智握住感官从未遇见的东西。"},{"no":"03","title":"To understand","titleCN":"理解、领会","definition":"to grasp the meaning of something","definitionCN":"把握某事物的意义","example":"He could not conceive how the trick was done.","exampleCN":"他无法理解这个戏法是怎么做的。","why":"To take something in is also to understand it, and the two senses share the same image.","whyCN":"把某物「纳进来」也就是理解它，两义共享同一意象。"},{"no":"04","title":"To become pregnant","titleCN":"怀孕","definition":"to become pregnant","definitionCN":"怀上孩子","example":"She conceived in the spring.","exampleCN":"她在春天怀孕了。","why":"The oldest sense is biological: to take in and begin a new life.","whyCN":"最古老的义是生物学的：纳入并开始新的生命。"},{"no":"05","title":"To regard something as","titleCN":"把某事物视为","definition":"to think of something in a particular way","definitionCN":"以某种方式看待某事物","example":"The plan was conceived as a temporary measure.","exampleCN":"这个方案最初被设想为临时措施。","why":"A thing is conceived in the shape the mind gives it at the start.","whyCN":"事物在开端时，被构想成心智给它的那个形状。"},{"no":"06","title":"A work is conceived in a certain way","titleCN":"作品以某种方式被构思","definition":"to have a work planned or imagined in a stated form","definitionCN":"以所述形式规划或想象一部作品","example":"The novel was conceived as three separate voices.","exampleCN":"这部小说被构思成三个各自独立的声音。","why":"Artists speak of conception before execution, and the word marks that first holding.","whyCN":"艺术家在动笔前先谈构思，这个词标出最初的握有。"},{"no":"07","title":"To devise a scheme","titleCN":"策划计谋","definition":"to invent a plan, often a secret or clever one","definitionCN":"发明一个计划，常指隐秘或机巧的","example":"The pair conceived a scheme to avoid the tax.","exampleCN":"这两个人策划了一个避税方案。","why":"The neutral act of forming a plan takes a darker colour when the plan is hidden.","whyCN":"构思本是中性行为，计划一旦隐秘，就染上更暗的颜色。"},{"no":"08","title":"To hold an opinion","titleCN":"认为","definition":"to think or believe something, in formal use","definitionCN":"以正式语体表示思考或相信","example":"The author conceived of the soul as a kind of music.","exampleCN":"作者把灵魂看作一种音乐。","why":"Formal writing keeps the old sense of taking a view into the mind.","whyCN":"正式写作保留「把一种看法纳入心中」的旧义。"}],"etymology":{"intro":{"en":"Conceive comes from Latin concipere, to take in or receive, from com- together plus capere, to take. The direct source and both elements are clear.","cn":"conceive 来自拉丁 concipere「纳入、接受」，由 com-「一起」与 capere「拿取」构成。直接来源与两个构件都清楚。"},"items":[{"era":"LATIN CAPERE","en":"Capere meant to take or seize, and it is the source of capture, accept and receive as well.","cn":"capere 意为拿取、抓住，也是 capture、accept 与 receive 的来源。"},{"era":"CONCIPERE","en":"Concipere joined com- with capere and meant to take in, to hold within, and to become pregnant.","cn":"concipere 把 com- 与 capere 结合，意为纳入、容纳、受孕。"},{"era":"THE MIND AS WOMB","en":"Latin and later European writers used the same verb for an idea held in the mind, as if thought were conceived.","cn":"拉丁及后来欧洲的写作者用同一个动词指心中怀有的想法，仿佛思想也被孕育。"},{"era":"OLD FRENCH CONCEVEIR","en":"Old French conceveir brought the verb into English.","cn":"古法语 conceveir 把这个动词带进英语。"},{"era":"ENGLISH CONCEIVE","en":"Conceive appears in the late Middle Ages; the exact first date is uncertain.","cn":"conceive 在中世纪晚期出现，确切首见年代不确定。"},{"era":"THE FAMILY","en":"Concept, conception and inception all come from the same taking-in verb.","cn":"concept、conception 与 inception 都出自同一个「纳入」动词。"}]},"similar":{"note":{"en":"The first group shares the Latin take-in stem; the second group names forming, imagining and understanding.","cn":"第一组共享拉丁语「纳入」词干；第二组是形成、想象与理解的近义说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"conception","ipa":"/kənˈsepʃn/","tag":"same root","definition":"The act of forming an idea, or the beginning of pregnancy.","definitionCN":"形成想法的行为，或怀孕的开始。"},{"word":"conceivable","ipa":"/kənˈsiːvəbl/","tag":"same root","definition":"Able to be imagined or believed.","definitionCN":"可想象或可相信的。"},{"word":"inconceivable","ipa":"/ˌɪnkənˈsiːvəbl/","tag":"same root","definition":"Impossible to imagine.","definitionCN":"无法想象的。"},{"word":"concept","ipa":"/kənˈsept/","tag":"same root","definition":"An idea taken into the mind and held.","definitionCN":"被纳入心中并持守的观念。"},{"word":"deceive","ipa":"/dɪˈsiːv/","tag":"different root","definition":"To mislead; from decipere, to catch by a trick, with a different prefix.","definitionCN":"误导；出自 decipere「以计捕获」，前缀不同。"}]},{"heading":"NEAR MEANING","entries":[{"word":"imagine","ipa":"/ɪˈmædʒɪn/","tag":"near meaning","definition":"To form a picture in the mind.","definitionCN":"在脑中形成图像。"},{"word":"devise","ipa":"/dɪˈvaɪz/","tag":"near meaning","definition":"To work out a plan or method.","definitionCN":"设计出计划或方法。"},{"word":"envision","ipa":"/ɪnˈvɪʒn/","tag":"near meaning","definition":"To picture a future state clearly.","definitionCN":"清晰地想象未来状态。"},{"word":"understand","ipa":"/ˌʌndəˈstænd/","tag":"near meaning","definition":"To grasp the meaning of something.","definitionCN":"把握某事物的意义。"},{"word":"design","ipa":"/dɪˈzaɪn/","tag":"near meaning","definition":"To plan the form of something before making it.","definitionCN":"在制作前规划某物的形态。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real Latin taking-in verb, the real family and real collocations.","cn":"正常联想使用真实的拉丁「纳入」动词、真实同族词与真实搭配。"},"normal":[{"en":"Concipere is to take in, and the mind takes in an idea as a body takes in a new life.","cn":"concipere 是纳入，心智纳入想法，正如身体纳入新生命。"},{"en":"Concept and conception come from the same verb; deceive has a different prefix.","cn":"concept 与 conception 出自同一动词；deceive 前缀不同。"},{"en":"The phrase with of is used for imagining what does not exist yet.","cn":"后面带介词的说法用于想象尚未存在之物。"},{"en":"Fixed phrases mark the use: conceive a plan, conceive a child, hard to conceive.","cn":"固定搭配标出用法：构想方案、怀孕、难以想象。"},{"en":"Conceivable and inconceivable are the two adjective poles.","cn":"conceivable 与 inconceivable 是两个形容词极端。"}],"abstract":[{"en":"Conceive is a lamp over blank paper where a shape first appears as an outline.","cn":"构想是灯下白纸上先浮出一个轮廓。"},{"en":"The word holds two kinds of beginning in one: an idea and a life.","cn":"这个词同时握住两种开端：一个想法与一条生命。"},{"en":"To understand is to let a meaning inside, not merely to look at it.","cn":"理解是让意义进来，而不只是看着它。"}]},"examples":[{"en":"The architect conceived the house as a single open room.","cn":"建筑师把这栋房子构想成一个开放的单间。"},{"en":"Few could conceive of a winter without snow here.","cn":"这里的人很难想象一个不下雪的冬天。"},{"en":"The plan was conceived in secret and announced at the end.","cn":"这个计划在暗中构思，最后才公布。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「肯吸物」——把想法吸进脑子里：构想","word":"conceive"},"root":"拉丁 concipere「纳入、接受、受孕」← com-「一起」+ capere「拿取」。capere 也是 capture、accept、receive 的来源；同族 concept、conception、inception 都出同一动词，deceive 则出自 decipere，前缀不同。古法语 conceveir 传入英语，中世纪晚期出现，确切首见年代不确定。","sensesIntro":{"en":"Eight senses hold idea, possibility, understanding, pregnancy, regard, artistic conception, scheme and formal opinion.","cn":"八个义项分别握住想法、可能性、理解、怀孕、看待、艺术构思、计谋与正式看法。"},"semanticMap":{"core":{"en":"CORE IMAGE: a lamp over blank paper where a shape first appears as an outline.","cn":"核心意象：灯下白纸上，一个形状先以轮廓浮现。"},"chain":["TAKE IN","HOLD WITHIN","FORM AN IDEA","IMAGINE","UNDERSTAND","BEGIN A LIFE"],"branches":[{"senses":"01 · 06","en":"THE FORMED IDEA: a plan brought into being and a work shaped at conception.","cn":"形成的想法：被带入存在的方案与在构思时定形的作品。"},{"senses":"02 · 07","en":"THE IMAGINED POSSIBILITY: what might exist and the scheme devised in secret.","cn":"想象的可能：可能存在之物与暗中策划的计谋。"},{"senses":"03 · 08","en":"THE UNDERSTOOD MEANING: grasping how something works and holding a formal view.","cn":"被理解的意义：把握事物如何运作，以及持有正式看法。"},{"senses":"04","en":"THE BIOLOGICAL BEGINNING: new life taken in.","cn":"生物学的开端：新生命被纳入。"},{"senses":"05","en":"THE ASSIGNED SHAPE: a thing regarded in a stated way.","cn":"被赋予的形状：以所述方式看待的事物。"}]},"affixes":{"intro":{"en":"Conceive is the Latin taking-in verb with English noun and adjective forms; capere is the core.","cn":"conceive 是拉丁「纳入」动词加英语名词与形容词形式；capere 是核心。"},"latinIntro":{"en":"Capere supplies the taking, com- supplies the inward direction, and conceptio supplies the noun.","cn":"capere 提供「拿取」，com- 提供向内的方向，conceptio 提供名词。"},"items":[{"word":"com-","structure":"Latin prefix","meaning":"together; into","meaningCN":"一起；向内","example":"The prefix turns taking into taking in.","exampleCN":"前缀把「拿」变成「纳入」。"},{"word":"capere","structure":"Latin verb, third conjugation","meaning":"to take; to seize","meaningCN":"拿取；抓住","example":"The verb is the core of capture and accept as well.","exampleCN":"这个动词也是 capture 与 accept 的核心。"},{"word":"concipere","structure":"Latin verb from com- and capere","meaning":"to take in; to conceive","meaningCN":"纳入；受孕","example":"The compound carries both the mental and the biological sense.","exampleCN":"复合词兼有心理与生物两义。"},{"word":"conceptio","structure":"Latin noun from concipere","meaning":"a taking in; conception","meaningCN":"纳入；构思；受孕","example":"The noun names the beginning.","exampleCN":"名词命名开端。"},{"word":"conceptus","structure":"Latin noun from concipere","meaning":"a taking in; a concept","meaningCN":"纳入；概念","example":"The held idea becomes a noun of its own.","exampleCN":"被握有的想法独立成名词。"},{"word":"conceive","structure":"English verb from Old French","meaning":"to form in the mind; to become pregnant","meaningCN":"构想；怀孕","example":"English keeps both the mental and the bodily senses.","exampleCN":"英语同时保留心理与身体两义。"},{"word":"conception","structure":"English noun","meaning":"the act of forming or beginning","meaningCN":"构想或开始的行为","example":"The noun covers idea and pregnancy alike.","exampleCN":"名词兼指想法与怀孕。"},{"word":"conceivable","structure":"English adjective","meaning":"able to be imagined","meaningCN":"可想象的","example":"The suffix -able marks what the mind can hold.","exampleCN":"后缀 -able 标记心智握得住的东西。"},{"word":"inconceivable","structure":"English negative adjective","meaning":"unimaginable","meaningCN":"难以想象的","example":"The negative prefix refuses the holding.","exampleCN":"否定前缀拒绝这种握有。"},{"word":"-able","structure":"Latin suffix -abilis","meaning":"able to be","meaningCN":"能够被","example":"It also builds achievable, visible and readable.","exampleCN":"它也构成 achievable、visible 与 readable。"}],"latinEntries":[{"word":"capere","structure":"capere, cepi, captum (v., third conjugation)","meaning":"to take; to seize","meaningCN":"拿取；抓住"},{"word":"concipere","structure":"concipere, concepi, conceptum (v., third conjugation)","meaning":"to take in; to conceive","meaningCN":"纳入；受孕"},{"word":"conceptio","structure":"conceptio, conceptionis (n., third declension)","meaning":"a taking in; conception","meaningCN":"纳入；构思"}],"derivatives":[{"word":"conception","pos":"n.","zh":"构想；概念；受孕"},{"word":"conceivable","pos":"adj.","zh":"可想象的；可能的"},{"word":"inconceivable","pos":"adj.","zh":"难以想象的"},{"word":"conceptive","pos":"adj.","zh":"有构想力的"}]}},{"word":"confine","ipa_uk":"/kənˈfaɪn/","ipa_us":"/kənˈfaɪn/","definition_zh":"限制；把……关在里面；使局限于；（复数）范围、边界","definition_en":"to keep within limits or inside a place; to restrict","core_image":"白线在地上围出一小块区域，脚步都停在线上","scene":"病房门口拉了一条黄带，来访者只能站到线外。Visitors were confined to the waiting room during the test.","sceneCN":"这里指把人限制在某个范围内（第 1 个义项：限制在界限之内）；句意为检查期间来访者被限制在等候室里。","pos":[{"tag":"v.","zh":"限制；关押；使局限于"},{"tag":"n.","zh":"（常用复数）范围；边界"}],"collocations":[{"phrase":"confine to","zh":"限制在…之内"},{"phrase":"be confined to bed","zh":"卧床不起"},{"phrase":"confine the discussion","zh":"限定讨论范围"},{"phrase":"within the confines of","zh":"在…的范围内"},{"phrase":"confine a fire","zh":"控制火势范围"},{"phrase":"confine the spread","zh":"控制扩散"}],"forms":[{"label":"原形","form":"confine"},{"label":"第三人称单数","form":"confines"},{"label":"过去式","form":"confined"},{"label":"过去分词","form":"confined"},{"label":"现在分词","form":"confining"},{"label":"名词（单数）","form":"confine"},{"label":"名词（常用复数）","form":"confines"},{"label":"名词","form":"confinement"}],"derivatives":[{"word":"confinement","pos":"n.","zh":"限制；监禁；分娩期"},{"word":"confined","pos":"adj.","zh":"受限的；狭窄的"},{"word":"confines","pos":"n.","zh":"边界；范围"},{"word":"confining","pos":"adj.","zh":"限制性的；局促的"}],"senses":[{"no":"01","title":"To restrict within limits","titleCN":"限制在界限之内","definition":"to keep something inside set limits","definitionCN":"使某事物保持在设定界限内","example":"Visitors were confined to the waiting room during the test.","exampleCN":"检查期间来访者被限制在等候室。","why":"Latin confinis meant sharing a boundary, and the verb applies that line to movement and scope.","whyCN":"拉丁 confinis 意为「共有一条边界」，动词把这条线施于行动与范围。"},{"no":"02","title":"To shut inside a space","titleCN":"关在里面","definition":"to keep a person or animal inside an enclosed place","definitionCN":"把人或动物关在围合的空间里","example":"The animals were confined in a narrow pen.","exampleCN":"这些动物被关在狭窄的围栏里。","why":"A boundary becomes a wall, and the word moves from limit to enclosure.","whyCN":"边界变成墙，这个词就从「限制」走到「围住」。"},{"no":"03","title":"To restrict activity to a place","titleCN":"使活动限于某地","definition":"to make someone stay in one place","definitionCN":"使某人只能待在一处","example":"Illness confined him to the house for a week.","exampleCN":"疾病让他在家待了一周。","why":"The restriction is on movement rather than on permission.","whyCN":"受限的是行动，而不是许可。"},{"no":"04","title":"To limit the spread of something","titleCN":"控制某物的扩散","definition":"to stop a fire, disease or problem from spreading","definitionCN":"阻止火、病或问题蔓延","example":"Crews confined the fire to one floor.","exampleCN":"消防队把火势控制在一层楼内。","why":"The word draws a line around a process that would otherwise grow.","whyCN":"这个词给一个本会扩大的过程画上界线。"},{"no":"05","title":"To be kept in bed","titleCN":"因病卧床","definition":"to be unable to leave bed because of illness","definitionCN":"因病无法离开床","example":"She was confined to bed with a fever.","exampleCN":"她因发烧卧床不起。","why":"The fixed phrase narrows the boundary to the edge of a bed.","whyCN":"固定说法把边界收窄到床边。"},{"no":"06","title":"The boundaries of a place","titleCN":"某地的边界、范围","definition":"the outer limits of an area or subject","definitionCN":"区域或主题的外缘","example":"The old walls mark the confines of the town.","exampleCN":"旧城墙标出这座镇的边界。","why":"The plural noun keeps the Latin sense of a shared border.","whyCN":"复数名词保留拉丁语「共有边界」的义。"},{"no":"07","title":"To hold particles in place","titleCN":"约束粒子","definition":"to keep plasma or particles inside a region by force","definitionCN":"用力量把等离子体或粒子限制在区域内","example":"Magnetic fields confine the hot plasma.","exampleCN":"磁场约束住高温等离子体。","why":"Physics uses the boundary image for an invisible bottle.","whyCN":"物理学把边界意象用作一只看不见的瓶子。"},{"no":"08","title":"To limit a discussion","titleCN":"限定讨论范围","definition":"to keep a debate or inquiry within a topic","definitionCN":"使辩论或探究不越出某一题目","example":"Let us confine the discussion to the budget.","exampleCN":"我们把讨论限定在预算上吧。","why":"The verb can bound speech as easily as bodies.","whyCN":"这个动词能像围住身体一样围住言语。"}],"etymology":{"intro":{"en":"Confine comes from Latin confinis, sharing a boundary, from com- together plus finis, boundary or end. The direct source and both elements are clear.","cn":"confine 来自拉丁 confinis「共有一条边界」，由 com-「一起」与 finis「边界、终点」构成。直接来源与两个构件都清楚。"},"items":[{"era":"LATIN FINIS","en":"Finis meant a boundary, an end or a limit, and it also lies behind final, finish and define.","cn":"finis 意为边界、终点、限度，也藏在 final、finish 与 define 背后。"},{"era":"CONFINIS","en":"Confinis described places or peoples that share a border, hence neighbouring.","cn":"confinis 描述共享边界的地区或民族，因此指相邻的。"},{"era":"CONFINIA","en":"The plural confinia meant the borders themselves, the outer lines of a territory.","cn":"复数 confinia 指边界本身，即领土的外缘。"},{"era":"THE VERB","en":"Latin and French use turned the bordering adjective into an act of keeping inside a line.","cn":"拉丁与法语的用法把这个「相邻」形容词变成「限制在一条线内」的动作。"},{"era":"ENGLISH CONFINE","en":"English took the verb in the late Middle Ages; the exact first date is uncertain.","cn":"英语在中世纪晚期借入这个动词，确切首见年代不确定。"},{"era":"SPECIALISED USES","en":"Medicine confines a patient to bed, physics confines plasma, and debate confines a topic.","cn":"医学把病人限制在床，物理学约束等离子体，辩论则限定题目。"}]},"similar":{"note":{"en":"The first group shares the Latin boundary stem; the second group names limiting and enclosing. Conceal is a different word and must not be merged with this one.","cn":"第一组共享拉丁语「边界」词干；第二组是限制与围住的近义说法。conceal 是另一个词，不能与它混为一谈。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"confinement","ipa":"/kənˈfaɪnmənt/","tag":"same root","definition":"The state of being limited or shut in.","definitionCN":"被限制或关住的状态。"},{"word":"confined","ipa":"/kənˈfaɪnd/","tag":"same root","definition":"Limited in space or scope.","definitionCN":"空间或范围受限的。"},{"word":"confines","ipa":"/ˈkɒnfaɪnz/","tag":"same root","definition":"The outer limits of a place or subject.","definitionCN":"地方或主题的外缘。"},{"word":"conceal","ipa":"/kənˈsiːl/","tag":"different root","definition":"To hide from sight; from celare, not from finis.","definitionCN":"藏起来不让人看见；出自 celare，与 finis 无关。"},{"word":"define","ipa":"/dɪˈfaɪn/","tag":"same root","definition":"To mark the limits of a meaning, from finis.","definitionCN":"标出意义的界限，出自 finis。"}]},{"heading":"NEAR MEANING","entries":[{"word":"restrict","ipa":"/rɪˈstrɪkt/","tag":"near meaning","definition":"To keep within a rule or limit.","definitionCN":"使处在规则或限度之内。"},{"word":"limit","ipa":"/ˈlɪmɪt/","tag":"near meaning","definition":"To set the furthest point allowed.","definitionCN":"设定允许的最远点。"},{"word":"imprison","ipa":"/ɪmˈprɪzn/","tag":"near meaning","definition":"To shut a person in a prison.","definitionCN":"把人关进监狱。"},{"word":"enclose","ipa":"/ɪnˈkləʊz/","tag":"near meaning","definition":"To surround with a barrier.","definitionCN":"用屏障围住。"},{"word":"constrain","ipa":"/kənˈstreɪn/","tag":"near meaning","definition":"To force or hold back by pressure.","definitionCN":"以压力迫使或抑制。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real Latin boundary word, the real family and real collocations.","cn":"正常联想使用真实的拉丁「边界」词、真实同族词与真实搭配。"},"normal":[{"en":"Finis is a boundary, and confinis means sharing that line.","cn":"finis 是边界，confinis 意为共享这条线。"},{"en":"Final, finish and define all come from the same boundary word.","cn":"final、finish 与 define 都出自同一个「边界」词。"},{"en":"Conceal hides what is inside; confine draws the line around it.","cn":"conceal 藏起里面的东西，confine 则在外围画线。"},{"en":"Fixed phrases mark the use: confine to, be confined to bed, within the confines of.","cn":"固定搭配标出用法：限制在…、卧床、在…范围内。"},{"en":"Physics confines plasma; a chair confines a discussion.","cn":"物理学约束等离子体，主持人则限定讨论。"}],"abstract":[{"en":"Confine is a white line on the floor with every foot stopped at it.","cn":"限制是地上一条白线，所有脚都停在线上。"},{"en":"A boundary makes a space real by saying where it stops.","cn":"边界说出空间在哪里停止，空间才变得真实。"},{"en":"The same line can protect or imprison, depending on who drew it.","cn":"同一条线既能保护也能囚禁，取决于谁画的。"}]},"examples":[{"en":"The rule confines the use of the field to research only.","cn":"规定把这块场地的用途限于研究。"},{"en":"A high wall confines the garden on three sides.","cn":"一堵高墙从三面围住花园。"},{"en":"The report confines itself to the years after the war.","cn":"这份报告只限于战后那些年。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"读作「肯凡」——肯把范围划到最凡（窄）处：限制","word":"confine"},"root":"拉丁 confinis「共有一条边界的」← com-「一起」+ finis「边界、终点」；复数 confinia 指边界本身。finis 也给出 final、finish、define。拉丁与法语用法把这个形容词变成「限制在线内」的动词，英语中世纪晚期借入，确切首见年代不确定。conceal 出自 celare「隐藏」，与 confine 不同源，也非同义词。","sensesIntro":{"en":"Eight senses draw a line around movement, place, activity, spread, bed, territory, plasma and talk.","cn":"八个义项分别在行动、场所、活动、扩散、病床、领土、等离子体与言谈外围画线。"},"semanticMap":{"core":{"en":"CORE IMAGE: a white line on the floor, every foot stopped at it.","cn":"核心意象：地上一道白线，所有的脚都停在线上。"},"chain":["BOUNDARY","SHARED BORDER","KEEP INSIDE","SHUT IN","LIMIT SPREAD","OUTER LIMITS"],"branches":[{"senses":"01 · 03","en":"THE DRAWN LIMIT: movement and activity kept inside a line.","cn":"画出的界限：行动与活动被保持在一条线内。"},{"senses":"02","en":"THE ENCLOSURE: a person or animal shut inside a space.","cn":"围住：把人或动物关在空间里。"},{"senses":"04 · 07","en":"THE CONTAINED PROCESS: a fire held to one floor and plasma held by a field.","cn":"被约束的过程：火被控制在一层，等离子体被场约束。"},{"senses":"05 · 08","en":"THE NARROWED FIELD: a patient kept to bed and a debate kept to one topic.","cn":"收窄的范围：病人限于床，辩论限于一个题目。"},{"senses":"06","en":"THE OUTER LINE: the confines of a town or a subject.","cn":"外缘：城镇或主题的边界。"}]},"affixes":{"intro":{"en":"Confine is the Latin boundary adjective turned into an English verb; finis is the root and com- adds the shared line.","cn":"confine 是拉丁语「边界」形容词变成英语动词；finis 是词根，com- 加上「共有」的线。"},"latinIntro":{"en":"Finis supplies the line, confinis the shared border, and confinia the outer limits in the plural.","cn":"finis 提供「线」，confinis 提供「共有的边界」，复数 confinia 提供「外缘」。"},"items":[{"word":"finis","structure":"Latin noun, third declension","meaning":"boundary; end; limit","meaningCN":"边界；终点；限度","example":"The noun is the root of the whole family.","exampleCN":"这个名词是整个词族的根。"},{"word":"com-","structure":"Latin prefix","meaning":"together; with","meaningCN":"一起；共同","example":"The prefix makes the border a shared one.","exampleCN":"前缀使边界成为共有的。"},{"word":"confinis","structure":"Latin adjective","meaning":"sharing a boundary; neighbouring","meaningCN":"共有一条边界的；相邻的","example":"The adjective describes places that touch.","exampleCN":"这个形容词描述相接的地方。"},{"word":"confinia","structure":"Latin plural noun","meaning":"borders; outer limits","meaningCN":"边界；外缘","example":"The plural names the lines themselves.","exampleCN":"复数形式命名这些线本身。"},{"word":"confine","structure":"English verb","meaning":"to keep within limits","meaningCN":"限制在界限内","example":"English turns the bordering adjective into an act.","exampleCN":"英语把「相邻」形容词变成动作。"},{"word":"confinement","structure":"English noun","meaning":"the state of being limited or shut in","meaningCN":"受限或被关住的状态","example":"The noun also names the period of childbirth.","exampleCN":"这个名词也指分娩期。"},{"word":"confined","structure":"English participle and adjective","meaning":"limited; narrow","meaningCN":"受限的；狭窄的","example":"The participle describes a space or a condition.","exampleCN":"分词描述空间或状况。"},{"word":"confines","structure":"English plural noun","meaning":"outer limits","meaningCN":"边界；范围","example":"The plural keeps the Latin shape of the word.","exampleCN":"复数保留了这个词的拉丁形态。"},{"word":"define","structure":"Latin definire plus English form","meaning":"to mark the limits of a meaning","meaningCN":"标出意义的界限","example":"The same root builds a different verb about meaning.","exampleCN":"同一词根构成另一个关于意义的动词。"},{"word":"final","structure":"Latin finalis","meaning":"of the end or boundary","meaningCN":"终点或边界的","example":"The family member names the last point.","exampleCN":"同族词命名最后一点。"}],"latinEntries":[{"word":"finis","structure":"finis, finis (n., third declension)","meaning":"boundary; end; limit","meaningCN":"边界；终点；限度"},{"word":"confinis","structure":"confinis, confine (adj.)","meaning":"sharing a boundary","meaningCN":"共有一条边界的"},{"word":"confinium","structure":"confinium, confinii (n., second declension)","meaning":"a common border; limits","meaningCN":"共有边界；范围"}],"derivatives":[{"word":"confinement","pos":"n.","zh":"限制；监禁；分娩期"},{"word":"confined","pos":"adj.","zh":"受限的；狭窄的"},{"word":"confines","pos":"n.","zh":"边界；范围"},{"word":"confining","pos":"adj.","zh":"限制性的；局促的"}]}}]);
